add(2, [
'''בקיץ 1954, באולפן הקטן של חברת Sun בממפיס, נהג משאית בן 19 בשם אלביס פרסלי הקליט את התקליטים הראשונים שלו, עם הגיטריסט סקוטי מור והבסיסט ביל בלאק. בתוך שנה הוא הפך לתופעה בדרום ארצות הברית, ובנובמבר 1955 קנתה חברת RCA הענקית את החוזה שלו תמורת 35 אלף דולר, סכום עצום באותם ימים. בינואר 1956 הוא הקליט בנאשוויל את Heartbreak Hotel, ובאותם שבועות הופיע לראשונה בטלוויזיה הארצית ועורר סערה. אלבום הבכורה שלו יצא במרץ 1956, בדיוק כשכל אמריקה התחילה לדבר עליו.''',
'''האלבום מחבר שני סוגים של הקלטות: שירים חדשים שהוקלטו ב־RCA, וחמש הקלטות ישנות מתקופת Sun שעוד לא יצאו. שומעים כאן את כל החומרים שמהם נבנה הרוקנרול: ריתם אנד בלוז של זמרים שחורים (I Got a Woman של ריי צ׳רלס, Tutti Frutti של ליטל ריצ׳רד), קאנטרי לבן, בלדות ישנות וגוספל. הכול עובר דרך הקול של אלביס: מתגרה, רועד, מתנשף, ולפעמים כמעט צוחק. הלהקה קטנה ומנגנת רזה ומהר, עם הגיטרה של מור, הבס של בלאק והתופים של די. ג׳יי. פונטנה.''',
'''זה היה אלבום הרוקנרול הראשון שהגיע למקום הראשון במצעד האלבומים האמריקאי, והוא נשאר שם עשרה שבועות. בכך הוא הוכיח שהמוזיקה החדשה היא לא רק סינגלים זולים לבני נוער, אלא גם עסק גדול. גם העטיפה נעשתה אייקון: אלביס באמצע צעקה עם הגיטרה, בשחור־לבן, ומעליו השם באותיות ורודות וירוקות. עשרים ושלוש שנים אחר כך להקת The Clash העתיקה אותה לעטיפה של London Calling, כמחווה לרגע שבו הכול התחיל.''',
'''נסו השוואה: שמעו את Tutti Frutti כאן, ומיד אחריו את המקור של ליטל ריצ׳רד באלבום 14. אלביס שר אותו שנה אחרי המקור, ואפשר לשמוע מה הוא לקח ממנו ומה הוסיף משלו.''',
], [
('Blue Suede Shoes', 'השיר של קארל פרקינס, חבר של אלביס מחברת Sun, פותח את האלבום בפיצוץ. הגרסה של אלביס הפכה אותו להמנון של התקופה.'),
('I Got a Woman', 'להיט של ריי צ׳רלס, שממנו אלביס לקח את האנרגיה של הגוספל אל הרוקנרול. שימו לב איך הוא מושך את המילה הראשונה.'),
('Blue Moon', 'הקלטה מתקופת Sun: בלדה ישנה שהופכת כאן למשהו מוזר ורפאי, עם פלסטו ארוך וכמעט בלי ליווי.'),
])

add(3, [
'''איירה וצ׳רלי לודרמילק גדלו בשנות העשרים והשלושים במשפחת חקלאים ענייה באזור הררי בצפון אלבמה. בבית ובכנסייה הם למדו לשיר בהרמוניה, ובדרך ספגו גם בלדות עתיקות שעברו מדור לדור. כשהתחילו להופיע הם שינו את שם המשפחה ל"לובין", ובשנות החמישים הפכו לאחד מצמדי האחים הגדולים של הקאנטרי, בעיקר עם שירי גוספל. Tragic Songs of Life, אלבום הבכורה שלהם, הוקלט בנאשוויל במאי 1956. דווקא בשנה שבה אלביס כבש את הרדיו, הם בחרו להקליט בלדות ישנות על מוות, פרידה וחטא.''',
'''הליווי צנוע: איירה מנגן במנדולינה, צ׳רלי בגיטרה, ועוד כמה נגנים ברקע. אבל הכוכבים הם שני הקולות. איירה שר גבוה מאוד, בקול חד וצלול, וצ׳רלי מתחתיו, בקול נמוך וחם יותר, והם צמודים כל כך שלפעמים קשה לדעת מי שר מה. השירים מספרים סיפורים קשים: נערה שנרצחת בידי אהובה, אם צעירה שמתה בסערה מול דלת הבית של אביה, חייל שמבקש למסור לאמו שהוא לא יחזור. והם שרים את כל זה בלי דרמה ובלי בכי, בשקט, כמעט כמו תפילה. זה מה שעושה את זה מצמרר.''',
'''בתקופה שבה הקאנטרי התחיל לנסות להישמע מודרני, האחים לובין הקדישו אלבום שלם לשירים שגדלו עליהם, ובזכות זה הוא נשמע כמעט כמו אלבום קונספט. ההרמוניות שלהם השפיעו ישירות על האחים אוורלי, ודרכם על דור שלם של זמרי רוק ופופ. שנים אחר כך גילה אותם מחדש גראם פרסונס, מחלוצי הקאנטרי־רוק, שהקליט שירים שלהם ונתן לאמילו האריס קלטת שלהם; אחד הלהיטים הגדולים הראשונים שלה היה שיר של האחים לובין. הצמד עצמו התפרק ב־1963, ושנתיים אחר כך איירה נהרג בתאונת דרכים.''',
'''באלבום הזה המילים חשובות לא פחות מהמוזיקה, אז שווה לחפש אותן ולקרוא תוך כדי האזנה. ואחרי In The Pines נסו לשמוע את Where Did You Sleep Last Night של נירוונה, מההופעה האקוסטית שלהם ב־MTV: זה אותו שיר עם, כמעט ארבעים שנה אחר כך.''',
], [
('Knoxville Girl', 'בלדת רצח שמקורה בבלדות אנגליות עתיקות, מושרת בשקט כמעט מתוק, וזה מה שהופך אותה למפחידה עוד יותר.'),
('In The Pines', 'שיר עם עתיק שהגיע לימים גם לנירוונה. כאן הוא נשמע מבודד וקר כמו הלילה שהוא מתאר.'),
('Kentucky', 'הדוגמה המושלמת להרמוניה הצפופה של האחים: שני קולות שנשמעים כמו קול אחד.'),
])

add(4, [
'''לואי פרימה נולד ב־1910 בניו אורלינס, למשפחה ממוצא סיציליאני, וגדל על הג׳אז של העיר. בשנות השלושים והארבעים הוא היה חצוצרן, זמר ומנהיג להקה מצליח, וכתב את Sing, Sing, Sing, שהפך לאחד הלהיטים הגדולים של עידן הסווינג. אבל באמצע שנות החמישים הלהקות הגדולות כבר נעלמו, והקריירה שלו דעכה. ב־1954 הוא קיבל עבודה בלאונג׳ של מלון Sahara בלאס וגאס והקים שם מופע חדש: הוא, אשתו הזמרת קילי סמית׳, והסקסופוניסט סם בוטרה עם הלהקה שלו, The Witnesses. הם הופיעו כמה פעמים בלילה, עד לפנות בוקר, וזה נודע כ"מופע הכי פרוע בווגאס". The Wildest! מ־1956 הוא הניסיון לתפוס את המופע הזה בתקליט.''',
'''זה נשמע כמו מסיבה שמישהו שכח לכבות: קצב שאפל עקשני שלא עוצר, סקסופון שצועק, בדיחות באיטלקית ובאנגלית, ופרימה שמתלהב, צועק, מושך מילים ומכניס את כולם לטירוף. מולו עומדת קילי סמית׳, ששרה ברוגע ובפנים חתומות, כאילו כל הבלגן הזה לא קשור אליה, והניגוד ביניהם הוא חלק גדול מהקסם. השירים הם תערובת: סטנדרטים אמריקאיים ותיקים, שירים איטלקיים ישנים, וקטעים שנכתבו כדי להרים את הקהל מהכיסאות.''',
'''האלבום עומד בדיוק בצומת שבין הסווינג, הג׳אמפ בלוז וראשית הרוקנרול, ומראה כמה הגבולות ביניהם היו דקים. הוא גם הזכיר לכולם שפרימה עוד כאן, ובעשור שאחריו הוא המשיך להצליח; ב־1967 הוא דיבב את המלך לואי, מלך הקופים, בסרט "ספר הג׳ונגל" של דיסני. עשרות שנים אחר כך השירים חזרו לחיים: דייוויד לי רות׳ הפך ב־1985 את Just a Gigolo ללהיט, בגרסה שנשענת כמעט לגמרי על העיבוד של פרימה, ו־Jump, Jive An' Wail בביצוע של בריאן סצר הצית את תחיית הסווינג של סוף שנות התשעים.''',
'''זה לא אלבום לאוזניות בשקט. שימו אותו בערב עם חברים, בזמן בישול או לפני יציאה, ותנו לו לרוץ. ואם בא לכם עוד, חפשו ביוטיוב את Just a Gigolo של דייוויד לי רות׳, ותשמעו כמה הוא לקח מפרימה.''',
], [
("Medley: Just a Gigolo - I Ain't Got Nobody", 'הפתיחה של האלבום: בלדה עצובה על ג׳יגולו שהזדקן, שמתחילה לאט ומתפוצצת באמצע לשאפל מטורף.'),
("Jump, Jive An' Wail", 'שלוש וחצי דקות של אנרגיה טהורה, השיר שמסביר למה אנשים רקדו על השולחנות בווגאס.'),
('Buona Sera', 'שיר אהבה איטלקי־אמריקאי, רומנטי ומצחיק בבת אחת, בדיוק כמו פרימה עצמו.'),
])

add(5, [
'''אנטואן "פאטס" דומינו נולד ב־1928 בניו אורלינס, במשפחה שדיברה בבית צרפתית קריאולית. הוא למד פסנתר כילד, עבד במפעל, ובלילות ניגן במועדונים. ב־1949 הקליט, יחד עם המפיק, המעבד והחצוצרן דייב ברתולומיו, את The Fat Man, שיש מי שרואים בו את אחד מתקליטי הרוקנרול הראשונים. מאז הם עבדו יחד שנים ארוכות, כתבו יחד רבים מהלהיטים שלו, והקליטו אותם לחברת Imperial. באמצע שנות החמישים דומינו היה אחד האמנים השחורים הראשונים שהשירים שלהם עברו מתחנות הרדיו של הקהל השחור אל מצעדי הפופ הכלליים. This Is Fats Domino! יצא בסוף 1956, בשיא ההצלחה שלו.''',
'''הכול נשען על הפסנתר: אקורדים מתגלגלים בשלישונים, יד שמאל כבדה של בוגי־ווגי, וקול חם ונינוח, עם המבטא של ניו אורלינס, שאף פעם לא ממהר. מסביב נושפים סקסופונים, והתופים מנגנים בקצב המתנדנד של העיר. השירים קצרים, רובם בסביבות שתי דקות, ובנויים בפשטות: בית, פזמון, סולו סקסופון, ושוב מההתחלה. זה רוקנרול מחייך, בלי אגרסיביות ובלי מרד, אבל עם גרוב שקשה מאוד לשבת מולו בלי לזוז.''',
'''Blueberry Hill הוא שיר מ־1940, ודומינו הכיר אותו מהגרסה של לואי ארמסטרונג. הביצוע שלו, מהאלבום הזה, עמד אחד־עשר שבועות בראש מצעד הריתם אנד בלוז, הגיע למקום השני במצעד הפופ, והפך לאחד השירים הגדולים של העשור. דומינו השפיע על כולם: אלביס קרא לו "המלך האמיתי של הרוקנרול", הביטלס אהבו אותו, ובג׳מייקה הקצב המתנדנד שלו היה אחד הזרעים שמהם צמחה הסקא.''',
'''הקשיבו ליד שמאל של דומינו. בכל שיר, נסו לעקוב רק אחרי הצלילים הנמוכים של הפסנתר, שחוזרים שוב ושוב ומחזיקים את כל השיר. זה סוד הגרוב של ניו אורלינס. ואם אהבתם, תמצאו את אותה עיר ואת אותו קצב גם אצל ליטל ריצ׳רד, באלבום 14.''',
], [
('Blueberry Hill', 'שיר ישן משנות הארבעים שדומינו הפך לשלו לגמרי. את הפתיחה בפסנתר מכירים בכל העולם.'),
('Blue Monday', 'שיר על שבוע עבודה ארוך מול סוף שבוע קצר מדי, שדומינו כתב עם ברתולומיו. פשוט, קצת עצוב, ומאוד כיפי.'),
("The Fat Man's Hop", 'קטע בלי שירה, שמראה את דומינו כפסנתרן: בוגי־ווגי מהיר מהמסורת של ניו אורלינס.'),
])

add(6, [
'''דיוק אלינגטון היה אחד המלחינים והמנהיגים הגדולים של הג׳אז, והתזמורת שלו כבשה את אמריקה בשנות השלושים והארבעים. אבל באמצע שנות החמישים היא נראתה לרבים כשריד מעידן אחר: הסווינג דעך, הג׳אז החדש היה הביבופ, והתקליטים של אלינגטון כמעט לא נמכרו. ב־7 ביולי 1956 הוא הגיע לפסטיבל הג׳אז של ניופורט, והתזמורת עלתה לבמה המרכזית רק קרוב לחצות, כשחלק מהקהל כבר התחיל ללכת הביתה. מה שקרה בשעה שאחרי הפך לאחת האגדות הגדולות של הג׳אז.''',
'''התזמורת פתחה בסוויטה חדשה שאלינגטון ושותפו בילי סטריהורן כתבו במיוחד לפסטיבל, ואז הגיעה Diminuendo and Crescendo in Blue, יצירה ישנה משנות השלושים. באמצע הקטע נכנס הסקסופוניסט פול גונסלבס לסולו ארוך של 27 סבבים של בלוז. הקהל התחיל להתעורר, אישה בשמלה שחורה קמה לרקוד בין הכיסאות, ותוך דקות כל האולם עמד, צעק ורקד, ואלינגטון המשיך לדחוף את הלהקה קדימה. בסוף, החצוצרן קאט אנדרסון מטפס לצלילים גבוהים שנשמעים כמו צעקה. ההקלטה תופסת את הרגע שבו קונצרט ג׳אז הופך למסיבה.''',
'''האלבום היה הנמכר ביותר בקריירה של אלינגטון, זמן קצר אחרי הקונצרט הוא הופיע על שער המגזין Time, והתזמורת זכתה לחיים חדשים שנמשכו עוד שני עשורים. שנים אחר כך התברר סוד קטן: גונסלבס ניגן את הסולו שלו למיקרופון הלא נכון, ולכן חלק ממה שיצא בתקליט המקורי הוקלט מחדש באולפן, עם מחיאות כפיים שהודבקו. בשנות התשעים נמצאו הקלטות של שידור הרדיו מאותו ערב, ויצאה גרסה מלאה של הקונצרט האמיתי.''',
'''האלבום בנוי לקראת הקטע האחרון, אז אם אין לכם זמן לכולו, קפצו ישר ל־Diminuendo And Crescendo In Blue. שמעו אותו בקול רם, וחכו לרגע שבו מתחיל הסולו של גונסלבס: הקשיבו איך הקהל, שבהתחלה כמעט לא נשמע, הופך לאט לאט לחלק מהלהקה.''',
], [
('Diminuendo And Crescendo In Blue', 'הלב של האלבום: הסולו של גונסלבס והקהל שמתעורר סביבו. רבע שעה שעוברת כמו חמש דקות.'),
("Jeep's Blues", 'ג׳וני הודג׳ס, אחד הסקסופוניסטים הגדולים של הג׳אז, מנגן בלוז חלק ומתוק כמו דבש.'),
('Festival Junction', 'הפתיחה של הסוויטה שנכתבה במיוחד לפסטיבל, עם סולנים שמתחלפים בזה אחר זה ומציגים את התזמורת.'),
])

add(7, [
'''שנה אחרי In the Wee Small Hours (אלבום 1) חזרו פרנק סינטרה ונלסון רידל לאולפן בהוליווד, הפעם עם תקליט שהוא בדיוק ההפך. אם הקודם היה לילה של בדידות, כאן סינטרה מאוהב, בטוח בעצמו ובשיא הכושר. הקאמבק שלו כבר הושלם: הוא שוב היה הזמר הגדול באמריקה, כוכב קולנוע, ומי שכל זמר אחר מודד את עצמו מולו. Songs for Swingin' Lovers! יצא במרץ 1956, והוקלט בכמה סשנים בסוף 1955 ובתחילת 1956.''',
'''רידל כתב עיבודים של סווינג רגוע: קצב שנע בנחת, כלי נשיפה שנבנים לאט עד לפיצוץ, ומעל הכול סינטרה, ששר בביטחון ומשחק עם המילים ועם הקצב, קצת לפני הביט או קצת אחריו. השירים הם סטנדרטים ישנים של קול פורטר, גרשווין ואחרים, אבל הם נשמעים רעננים לגמרי. את I've Got You Under My Skin, לפי הסיפור, רידל גמר לכתוב במונית בדרך לאולפן, בהשראת הבולרו של ראוול. באמצע השיר הוא השאיר מקום לסולו של הטרומבוניסט מילט ברנהרט, שאילתר אותו, ונאלץ לנגן אותו שוב ושוב עד שסינטרה היה מרוצה.''',
'''האלבום קבע את הצליל הקלאסי של סינטרה, זה שרוב העולם מכיר, והפך לתבנית של שירת הפופ המבוגרת במשך עשורים. בבריטניה הוא היה האלבום הראשון אי־פעם שהגיע למקום הראשון במצעד האלבומים, שהתחיל באותה שנה. יחד עם In the Wee Small Hours הוא הוכיח שאלבום יכול להיות יצירה מתוכננת עם מצב רוח אחד, ולא רק ערימה של להיטים.''',
'''שימו לב איך רידל בונה כל שיר כמו גל: הוא מתחיל בשקט, מוסיף כלים לאט, ומגיע לשיא רק לקראת הסוף. הכי ברור זה ב־I've Got You Under My Skin, בערך באמצע השיר. ואם עוד לא שמעתם את אלבום 1, שמעו את שניהם באותו יום: אותו זמר, אותו מעבד, ומצב רוח הפוך לגמרי.''',
], [
("I've Got You Under My Skin", 'הרגע הכי מפורסם באלבום: רידל בונה קרשנדו של כלי נשיפה, ומילט ברנהרט מתפוצץ בסולו טרומבון שנכנס להיסטוריה.'),
('You Make Me Feel So Young', 'הפתיחה של האלבום: שמחה נקייה, ואפשר ממש לשמוע את סינטרה מחייך.'),
('Pennies From Heaven', 'שיר משנות השלושים שמקבל כאן סווינג קליל ואלגנטי, בלי שום מאמץ נראה לעין.'),
])

add(8, [
'''באדי הולי היה נער מלובוק, טקסס, עם משקפיים עבות וגיטרת פנדר. ב־1957, בגיל עשרים, הוא וחבריו ללהקה The Crickets נסעו לאולפן הקטן של נורמן פטי בעיירה קלוביס שבניו מקסיקו, והקליטו שם שירים שכתבו בעצמם. That'll Be the Day הגיע באותה שנה למקום הראשון בארצות הברית ובבריטניה, והאלבום יצא בנובמבר 1957. זה האלבום היחיד שיצא בשם הקריקטס בחייו של הולי: בפברואר 1959, בגיל 22, הוא נהרג בהתרסקות מטוס קטן באמצע סיבוב הופעות.''',
'''שתי גיטרות, בס ותופים, ומעליהם הקול של הולי, עם השיהוק המפורסם שלו, שקופץ פתאום לצליל גבוה באמצע מילה. הצליל פשוט וישיר: גיטרה חדה, מקצבים מקוריים, ושירים קצרים וקליטים, כמעט כולם מתחת לשתי דקות וחצי. ב־Not Fade Away המתופף ג׳רי אליסון לא ניגן על תופים בכלל, אלא הכה על קופסת קרטון. בכמה מהשירים נוספו אחר כך קולות ליווי של קבוצה ווקאלית, שמוסיפים ״אוּ״ ו״אָה״ מתוקים ברקע.''',
'''הקריקטס קבעו את התבנית של להקת רוק: ארבעה חברים, שתי גיטרות, בס ותופים, שכותבים ומנגנים את השירים של עצמם. בליברפול, קבוצת נערים בשם The Quarrymen בחרה ב־That'll Be the Day כשיר הראשון שהקליטה אי־פעם, ב־1958; שנתיים אחר כך הם כבר נקראו הביטלס, שם שנבחר בין השאר בהשראת ה"צרצרים" של הולי. הרולינג סטונס הפכו את Not Fade Away ללהיט הראשון שלהם בטופ 10 הבריטי. ואפשר לשמוע את הולי כמעט אצל כל להקת גיטרות שבאה אחריו.''',
'''האלבום כולו קצר מ־26 דקות, פחות מפרק של סדרה, אז שמעו אותו בבת אחת. ואחרי That'll Be The Day, דמיינו ארבעה נערים בליברפול שמנסים לנגן אותו בפעם הראשונה: שם זה התחיל.''',
], [
("That'll Be The Day", 'הלהיט שהגיע למקום הראשון באמריקה ובבריטניה. השם לקוח ממשפט שג׳ון וויין חוזר עליו בסרט "המחפשים".'),
('Not Fade Away', 'במקום תופים יש כאן קופסת קרטון, בקצב שנשען על המקצב של בו דידלי. הסטונס עשו ממנו את אחד הלהיטים הראשונים שלהם.'),
('Oh Boy!', 'שתי דקות של אושר רוקנרול, עם הקולות המלווים שנוספו ברקע ועם הולי בשיא האנרגיה.'),
])

add(9, [
'''קאונט בייסי, פסנתרן מרד בנק שבניו ג׳רזי, הוביל בשנות השלושים והארבעים את אחת התזמורות הגדולות והמסווינגות בג׳אז, שנולדה במועדונים של קנזס סיטי. אבל עידן התזמורות הגדולות נגמר, וב־1950 בייסי נאלץ לפרק אותה. בתחילת שנות החמישים הוא הקים תזמורת חדשה, שקיבלה את הכינוי "הברית החדשה". באוקטובר 1957 הוא נכנס עם התזמורת הזו לאולפן בשביל חברת Roulette החדשה, ונתן לכותב ולמעבד ניל הפטי לכתוב בשבילה אלבום שלם של קטעים חדשים. האלבום יצא בינואר 1958, עם תמונה של פטריית פיצוץ אטומי על העטיפה, ומכאן השם.''',
'''זו תזמורת גדולה שמנגנת בדיוק של שעון שוויצרי ובעוצמה של מטוס סילון, אבל גם יודעת לרדת פתאום לשקט כמעט מוחלט. בייסי עצמו מנגן מעט מאוד תווים בפסנתר, אבל כל אחד מהם נוחת בדיוק במקום הנכון. מתחת לכל זה, הגיטרה של פרדי גרין מנגנת אקורד על כל פעמה ומחזיקה את התזמורת כולה. הפטי כתב מנגינות קליטות ופשוטות, שמשאירות הרבה מקום לסולנים, ובהם הסקסופוניסט אדי "לוקג׳ו" דייוויס. ובסוף מגיע Li'l Darlin', בלדה איטית עד כדי כך שהיא כמעט עוצרת, ובכל זאת מסווינגת.''',
'''האלבום נחשב לאחד השיאים של הג׳אז לתזמורת גדולה, ומראה שהסווינג לא מת עם שנות הארבעים, אלא התבגר והשתכלל. כמה מהקטעים כאן הפכו לסטנדרטים שכל להקת ג׳אז גדולה מנגנת עד היום, ובראשם Li'l Darlin'. ניל הפטי המשיך לכתוב גם לטלוויזיה ולקולנוע: הוא כתב, למשל, את נעימת הפתיחה של סדרת "באטמן" משנות השישים.''',
'''נסו להקשיב לגיטרה של פרדי גרין. קשה לשמוע אותה בהתחלה, כי היא נמצאת מתחת לכל השאר, אבל נסו לעקוב רק אחריה לאורך שיר אחד. אחרי שתשמעו אותה פעם אחת, תבינו למה אומרים שהיא הלב של התזמורת.''',
], [
("Li'l Darlin'", 'בלדה איטית כל כך שהיא כמעט עוצרת, ובכל זאת מסווינגת. אחד הקטעים המפורסמים ביותר של בייסי.'),
('The Kid from Red Bank', 'בייסי, שנולד ברד בנק, מקבל כאן במה לפסנתר שלו מול התזמורת כולה, ומראה שהוא יודע גם לנגן מהר.'),
('Whirly Bird', 'התזמורת בכל הכוח, עם סולו סוער של אדי "לוקג׳ו" דייוויס בסקסופון טנור.'),
])

add(10, [
'''תלוניוס מונק גדל בניו יורק, ובשנות הארבעים היה מהנגנים שבנו את הביבופ, הג׳אז המהיר והמורכב שהחליף את הסווינג. אבל בעוד שחבריו, כמו צ׳רלי פארקר ודיזי גילספי, זכו להצלחה, מונק נחשב בעיקר לפסנתרן מוזר שקשה להבין. ב־1951 הוא נעצר בפרשת סמים ואיבד את הרישיון לנגן במועדונים בניו יורק, והקריירה שלו כמעט נעצרה. Brilliant Corners הוקלט בסוף 1956 לחברת Riverside הקטנה, והיה נקודת המפנה: הפעם הראשונה שהמבקרים, ואחריהם הקהל, התחילו באמת להקשיב.''',
'''מונק כותב מנגינות עם זוויות חדות, קצב שמועד בכוונה, והרמוניות שנשמעות כמעט כמו טעויות. אבל כל תו במקום. לצדו מנגנים שני סקסופוניסטים, סוני רולינס וארני הנרי, והמתופף מקס רואץ׳. קטע הנושא היה כל כך קשה שהלהקה ניסתה לנגן אותו 25 פעמים באותו ערב ולא הצליחה אפילו פעם אחת להגיע עד הסוף; הגרסה שבאלבום הודבקה מחלקים של כמה ניסיונות. ב־Pannonica מונק מנגן גם בצ׳לסטה, כלי שנשמע כמו תיבת נגינה, וב־I Surrender Dear הוא לבד לגמרי, רק הוא והפסנתר.''',
'''האלבום הציג את מונק כאחד המלחינים החשובים של הג׳אז, ולא רק כנגן מוזר. זמן קצר אחריו הוא קיבל בחזרה את הרישיון, וב־1957 ניגן חודשים ארוכים במועדון Five Spot בניו יורק עם ג׳ון קולטריין, הופעות שהפכו לאגדה. הרבה מהקטעים שלו נעשו לחומר לימוד בסיסי לכל נגן ג׳אז, והיום הוא נחשב לאחד המלחינים האמריקאים הגדולים של המאה העשרים.''',
'''אל תיבהלו אם בהאזנה הראשונה זה נשמע מוזר או "לא נכון". זה חלק מהעניין. תנו לאלבום שתי האזנות, ואם צריך, התחילו מ־Pannonica, הקטע הרך והמזמין ביותר. בפעם השנייה, מה שנשמע כמו טעות מתחיל להישמע כמו בדיחה פרטית שאתם כבר מבינים.''',
], [
('Brilliant Corners', 'המנגינה מתנגנת פעם לאט ופעם מהר פי שניים. זה מבלבל בהתחלה, ואז פתאום הכול מתחבר.'),
('Pannonica', 'בלדה שנכתבה לברונית פאנוניקה דה קניגסוורטר, פטרונית של נגני הג׳אז. מונק מנגן בה גם בצ׳לסטה, כלי שנשמע כמו תיבת נגינה.'),
('Bemsha Swing', 'מקס רואץ׳ מוסיף טימפני, תופים סימפוניים גדולים, לקטע שקופץ כמו כדור.'),
])

add(11, [
'''לואיס "סאבו" מרטינס נולד ב־1930 בהארלם הספרדית שבניו יורק, למשפחה פורטוריקנית. בסוף שנות הארבעים הוא כבר ניגן בקונגה בתזמורת של דיזי גילספי, ובשנים שאחר כך עם כמה מגדולי הג׳אז, ובהם המתופף ארט בלייקי. באפריל 1957 הזמינה אותו חברת Blue Note, הבית של הג׳אז המודרני, להקליט את האלבום הראשון בשמו. התוצאה, באופן מפתיע, כמעט בלי ג׳אז בכלל.''',
'''Palo Congo הוא בעיקר תופים וקולות: קונגות, בונגו, קריאות ומקהלות שמגיעות מהמסורות האפרו־קובניות, וחלקן משירי פולחן של דתות שהגיעו לקובה מאפריקה. לצד סאבו מופיע ארסניו רודריגס, מגדולי המוזיקאים של קובה במאה העשרים, שהתעוור כילד והפך לאחד האבות של הסון הקובני המודרני. הוא שר, מתופף ומנגן בטרס, גיטרה קובנית עם שלושה זוגות מיתרים, ואיתו שני אחיו וזמרים נוספים. התחושה היא של מפגש לילי ברחוב, לא של הופעה באולם.''',
'''זה אחד התקליטים הראשונים שהביאו לקהל הג׳אז האמריקאי את המוזיקה האפרו־קובנית כמו שהיא, בלי לעבד אותה לאוזן מערבית. דורות של מתופפים ונגני לטין למדו ממנו, והוא מזכיר עד כמה הג׳אז, הסלסה והרוק חייבים לקצבים שהגיעו מאפריקה דרך הקריביים. סאבו עצמו עבר בסוף שנות השישים לשוודיה, והמשיך לנגן ולהקליט גם שם.''',
'''נסו להקשיב לכל קטע כמה פעמים, ובכל פעם לעקוב אחרי תוף אחר: אחד מחזיק דפוס קבוע, אחד משוחח עם הזמר, ואחד משתולל מעל כולם. אחר כך עברו לאלבום 13, של מאצ׳יטו, ותשמעו איך אותם קצבים נשמעים מתחת לתזמורת ג׳אז שלמה.''',
], [
('El Cumbanchero', 'שיר מפורסם של המלחין הפורטוריקני רפאל הרננדס, שהופך כאן למרוץ של תופים. הקשיבו איך המקצבים נשזרים זה בזה.'),
('Aggo Elegua', 'קריאה לאלגואה, השומר של הפתחים והדרכים במסורת היורובה הקובנית. מקהלה ותופים, כמו בטקס.'),
('Choferito-Plena', 'פלנה, סגנון עממי מפוארטו ריקו, עם מנגינה שמחה שקל מאוד להיסחף אחריה.'),
])

add(12, [
'''ב־1948 מיילס דייוויס היה בן 22, חצוצרן מוכשר שעדיין עמד בצלו של צ׳רלי פארקר. באותה תקופה הוא התחיל לבקר בדירת מרתף קטנה במנהטן, מאחורי מכבסה סינית, שבה גר המעבד גיל אוונס. שם נפגשו מוזיקאים צעירים, ובהם ג׳רי מוליגן, ג׳ון לואיס ולי קוניץ, וחיפשו ביחד חלופה לביבופ המהיר והלוהט. מתוך השיחות האלה נולד הרכב של תשעה נגנים (נונט), שהופיע שבועיים במועדון בניו יורק והקליט בין 1949 ל־1950 שנים־עשר קטעים. רק ב־1957, כשהקטעים כבר נחשבו לקלאסיקה, אספה אותם חברת Capitol לאלבום אחד ונתנה לו את השם Birth of the Cool.''',
'''ההרכב עצמו יוצא דופן: יש בו קרן יער וטובה, כלים שכמעט לא נשמעו בג׳אז, לצד חצוצרה, טרומבון ושני סקסופונים. העיבודים של מוליגן, לואיס ואוונס נשמעים רכים, מאופקים ומדויקים. במקום סולו ארוך אחרי סולו ארוך, כמו בביבופ, יש כאן מרקמים וצבעים, ומנגינות שעוברות מכלי לכלי כמו במוזיקה קאמרית. הקטעים קצרים, בערך שלוש דקות כל אחד, כי הם הוקלטו במקור לתקליטים קטנים.''',
'''השם אומר הכול: מכאן נולד ה"קול ג׳אז", הסגנון הרגוע והקריר שהפך לצליל של החוף המערבי בשנות החמישים. כמעט כל מי שניגן כאן הפך אחר כך לדמות מרכזית בג׳אז. וגם השותפות בין דייוויס לגיל אוונס נולדה כאן; כעבור כמה שנים היא הולידה כמה מהאלבומים הגדולים של שניהם.''',
'''שמעו את האלבום הזה, ואחר כך עברו לאלבום 21, Kind of Blue, שדייוויס הקליט עשר שנים אחרי הסשנים האלה. תשמעו את אותה שלווה ואותו איפוק, אבל הפעם בחופש של להקה קטנה.''',
], [
('Boplicity', 'העיבוד של גיל אוונס שמסכם את כל הרעיון: מנגינה קלילה ושכבות רכות של כלים.'),
('Jeru', 'נקרא על שם הכינוי של ג׳רי מוליגן, שכתב ועיבד אותו. מקצב קופצני שמשנה כיוון כל הזמן.'),
('Moon Dreams', 'העיבוד השאפתני ביותר: כמעט בלי קצב, צלילים ארוכים שנעים כמו עננים. אפשר לשמוע בו את העתיד של גיל אוונס.'),
])

add(13, [
'''פרנק "מאצ׳יטו" גריו גדל בהוואנה, והיה זמר ונגן מרקאס. ב־1940, בניו יורק, הוא הקים את התזמורת Machito and His Afro-Cubans, יחד עם גיסו, החצוצרן והמעבד מריו באוסה, שכבר ניגן לפני כן בתזמורות ג׳אז אמריקאיות. הם היו מהראשונים שחיברו באמת בין תזמורת ג׳אז גדולה לבין מקצבים קובניים, ומהחיבור הזה נולד הג׳אז האפרו־קובני. Kenya הוקלט בניו יורק בדצמבר 1957, יצא בחברת Roulette, והוא אחד השיאים של התזמורת.''',
'''מעל חטיבת קצב של מתופפים לטיניים מהטובים בעולם, ובהם נגני הקונגה קנדידו קמרו ופטאטו ואלדס, יושבת חטיבת כלי נשיפה של תזמורת ג׳אז גדולה, עם חצוצרות שנעות בין צעקה חדה לשקט מאיים. את רוב הקטעים כתבו ועיבדו באוסה, הפסנתרן רנה הרננדס והמעבד א.ק. סלים. ומעל כולם מאלתרים סולני ג׳אז אורחים, ובראשם הסקסופוניסט קאנונבול אדרלי, כאילו נולדו בתוך הקצבים האלה. הקטעים קצרים ודחוסים, כמעט כולם כשלוש דקות.''',
'''Kenya מראה כמה עמוק הג׳אז והמוזיקה הקובנית השפיעו זה על זה. הצליל של מאצ׳יטו היה בסיס לסלסה של ניו יורק בשנות השישים והשבעים, ולכמעט כל תזמורת לטין ג׳אז שבאה אחריו. הוא גם מזכיר תקופה שבה אולמות הריקודים של ניו יורק היו המקום שבו נפגשו מהגרים מקובה ומפוארטו ריקו עם אמריקאים שחורים ולבנים, ורקדו יחד לאותה מוזיקה.''',
'''שמעו את Cannonology ואחר כך את קאנונבול אדרלי באלבום 21, Kind of Blue, שהוקלט שנה וחצי אחרי זה. אותו סקסופון, שני עולמות: כאן מעל תופים קובניים, ושם בתוך השקט של מיילס דייוויס.''',
], [
('Kenya', 'קטע הנושא: כלי נשיפה עוצמתיים מעל תופים, דרמטי כמו פסקול של סרט הרפתקאות.'),
('Tin Tin Deo', 'קלאסיקה של נגן הקונגה צ׳אנו פוסו, מהשירים שייסדו את הג׳אז האפרו־קובני בתזמורת של דיזי גילספי.'),
('Cannonology', 'קטע שנקרא על שם קאנונבול אדרלי, שמאלתר כאן בסקסופון אלט מעל המקצבים הלטיניים.'),
])

add(14, [
'''ריצ׳רד פנימן גדל במייקון שבג׳ורג׳יה ולמד לשיר בכנסייה. בתחילת שנות החמישים הקליט כמה תקליטים שלא הצליחו, הופיע במועדונים בדרום ועבד כשוטף כלים בתחנת האוטובוסים של העיר. בספטמבר 1955 שלחה אותו חברת התקליטים Specialty להקלטות בניו אורלינס, והן לא הלכו טוב. בהפסקה, במועדון סמוך, הוא ראה פסנתר, התיישב והתחיל לצרוח שיר גס שכתב ליד הכיור. הקהל התפוצץ מצחוק, והמפיק באמפס בלאקוול הבין מיד שזה להיט. רק המילים היו צריכות להשתנות: כותבת מקומית, דורותי לה־בוסטרי, ניקתה אותן, וכך נולד Tutti Frutti. האלבום יצא ב־1957 ואוסף את הלהיטים שבאו אחריו.''',
'''מאחורי ליטל ריצ׳רד מנגנים כמה מנגני האולפן הטובים של ניו אורלינס, ביניהם המתופף ארל פאלמר והסקסופוניסט לי אלן. אבל הכוכב הוא הוא: פסנתר שדופק אקורדים מהירים בלי לעצור, וקול שעובר בתוך שנייה מצעקה לצחוק ומשם לייבבה גבוהה, ה־"וּוּוּ" שהביטלס אימצו אחר כך. הוא שר כמו מטיף בכנסייה, רק שהנושא הוא מסיבות, בחורות ושמחה. רוב השירים קצרים מ־2.5 דקות, ואין בהם רגע אחד של מנוחה.''',
'''ב־1956 הקליט הזמר פט בון גרסה מנומסת ל־Tutti Frutti, וזו הגיעה במצעד גבוה יותר מהמקור. זה היה דבר נפוץ באותן שנים: זמרים לבנים הקליטו מחדש להיטים של זמרים שחורים. אבל הצעירים חיפשו את האמיתי. אלביס (אלבום 2) הקליט ארבעה משירי האלבום הזה, ופול מקרטני שר את Long Tall Sally בהופעות של הביטלס במשך שנים. ב־1957, בשיא ההצלחה, ליטל ריצ׳רד הפסיק באמצע סיבוב הופעות באוסטרליה, עזב את הרוקנרול והלך ללמוד תיאולוגיה. הוא חזר לבמות רק כעבור כמה שנים, אבל עד אז כבר היה ברור מי הניח את היסודות.''',
'''את האלבום כדאי לשמוע בקול רם, מההתחלה ועד הסוף; הוא פחות מחצי שעה. אחר כך נסו ניסוי קטן: חפשו ביוטיוב את הגרסה של פט בון ל־Tutti Frutti, ומיד אחריה שמעו שוב את המקור. אותו שיר, כמעט אותן מילים, ושני עולמות. ואם בא לכם עוד, חזרו לאלבום 2 ושמעו איך אלביס שר אותו.''',
], [
('Tutti Frutti', 'השיר שהתחיל הכול. הקריאה בפתיחה היא אחד הרגעים המפורסמים בתולדות הרוק.'),
('Long Tall Sally', 'עוד יותר מהיר. שימו לב לסולו הסקסופון, ולאיך שהקול עולה בסוף כל שורה.'),
('Jenny Jenny', 'שתי דקות בלי לעצור לנשום. דוגמה טובה לאנרגיה שלא נגמרת אצלו.'),
])

add(15, [
'''טיטו פואנטה נולד ב־1923 בהארלם הספרדית שבניו יורק, להורים מפוארטו ריקו. הוא ניגן בטימבלס, זוג תופי מתכת של המוזיקה הקובנית, ובוויברפון, שירת בצי האמריקאי במלחמת העולם השנייה, ואחרי המלחמה למד מוזיקה והקים תזמורת משלו. בשנות החמישים אולם הריקודים Palladium במנהטן היה מקדש המאמבו, ופואנטה היה אחד משלושת המלכים שלו, לצד מאצ׳יטו (אלבום 13) וטיטו רודריגס. Dance Mania הוקלט בסוף 1957 לחברת RCA הגדולה, יצא בתחילת 1958, והפך לאלבום הנמכר ביותר שלו.''',
'''זו תזמורת ריקודים במלוא הכוח: חצוצרות וסקסופונים חדים, פסנתר שחוזר על דפוסים מסחררים, ושכבה עבה של תופים שפואנטה מוביל מלפנים, בטימבלס. את השירה מוסיף הזמר הפורטוריקני סנטיטוס קולון, בקול רך וחם שמאזן את כל העוצמה מסביב. יש כאן מאמבו, צ׳ה־צ׳ה־צ׳ה וגוארצ׳ה, ואפילו שיר אמריקאי ישן משנות העשרים שהופך למאמבו. אבל בניגוד לתקליטי "לטין" רבים של אותה תקופה, שנעשו כדי להישמע אקזוטיים לקהל האמריקאי, כאן הקצבים הקובניים מנוגנים כמו שהם.''',
'''Dance Mania הוא אחד מאלבומי הלטין החשובים שהוקלטו מחוץ לקובה, והוא הניח חלק מהיסודות לסלסה של ניו יורק. פואנטה המשיך להקליט עוד ארבעים שנה, יותר ממאה אלבומים, וזכה לכינוי "מלך הטימבלס". השיר שלו Oye Como Va, מתחילת שנות השישים, הפך ב־1970 ללהיט עולמי בביצוע של קרלוס סנטנה.''',
'''זה אלבום לריקוד, אז אל תשבו. ואם כבר יושבים, הקשיבו לטימבלס של פואנטה: הצלצולים החדים על המתכת, שמסמנים לתזמורת מתי להיכנס ומתי להתפוצץ. שמעו אותו אחרי מאצ׳יטו (אלבום 13), ותשמעו את שני הצדדים של אותה סצנה.''',
], [
('El Cayuco', 'הפתיחה: קצב מתגלגל ומקהלה שחוזרת על אותה מילה עד שאי אפשר להוציא אותה מהראש.'),
('Complicación', 'אחד השירים המוכרים באלבום, עם דו־שיח בין הזמר לכלי הנשיפה.'),
('Hong Kong Mambo', 'מנגינה "מזרחית" משעשעת מעל מאמבו אמיתי, עם כלי הקשה מלודיים בחזית.'),
])

add(16, [
'''בילי הולידיי הייתה אחת הזמרות הגדולות של הג׳אז, עם ילדות קשה בבולטימור ובניו יורק, וקריירה שבה הקליטה שירים כמו Strange Fruit, שיר מחאה נגד הלינץ׳ באמריקה. אבל ב־1958 היא הייתה בת 42 ונשמעה מבוגרת בהרבה: שנים של התמכרות לאלכוהול ולסמים, מאסר, ורדיפה של המשטרה פגעו בה ובקול שלה. באותה שנה היא ביקשה להקליט עם המעבד ריי אליס, שאת תקליט התזמורת שלו אהבה במיוחד, ואמרה לו שהיא רוצה להישמע כמו סינטרה. Lady in Satin הוקלט בניו יורק בפברואר 1958. שנה וחצי אחר כך, ביולי 1959, היא מתה.''',
'''העיבודים של אליס רכים, כמעט הוליוודיים: כינורות, מקהלה עדינה וכלי נשיפה חמים. באמצע כל זה עומד קול סדוק, צרוד ושביר, שכבר לא מסוגל לעשות את מה שעשה פעם, ודווקא לכן כל מילה בו כואבת. רוב השירים כאן הם על אהבה שכבר נגמרה או שמעולם לא הייתה טובה. הולידיי לא נשמעת כמו מי ששרה על אהבה אבודה; היא נשמעת כמו מי שחייתה את כולה.''',
'''בזמנו מבקרים רבים שמעו כאן בעיקר זמרת גמורה, והאלבום נחשב עצוב מדי. היום רבים רואים בו אחת ההקלטות המרגשות בתולדות הג׳אז, ודוגמה לכך שאמת רגשית חשובה יותר משלמות טכנית. לפי הסיפור, זה היה האלבום האהוב עליה מכל מה שהקליטה.''',
'''שלושה מהשירים כאן, Glad to Be Unhappy, I Get Along Without You Very Well ו־I'll Be Around, מופיעים גם באלבום 1 של סינטרה, שהקליט אותם שלוש שנים קודם. שמעו אותם זה אחרי זה: שני לילות בודדים, אחד של גבר בשיא הקאמבק שלו, ואחד של אישה בסוף הדרך.''',
], [
('I’m a Fool to Want You', 'שיר שפרנק סינטרה כתב בחלקו, על אהבה הרסנית. אצל הולידיי זה נשמע כמו וידוי.'),
('You Don’t Know What Love Is', 'אולי הרגע הכי חשוף באלבום: קול עייף שמסביר מה זו אהבה למי שעוד לא הבין.'),
('You’ve Changed', 'המיתרים מתנפחים והקול כמעט נשבר, ובכל זאת היא מחזיקה כל שורה עד הסוף.'),
])

add(17, [
'''אליוט אדנופוז נולד ב־1931 בברוקלין, בן לרופא יהודי מוערך, ואביו רצה שיהיה מנתח. אבל הילד התאהב בקאובואים שראה ברודאו של מדיסון סקוור גארדן, ובגיל 15 ברח מהבית והצטרף לרודאו נודד. בשנות החמישים המוקדמות הוא נדד בארצות הברית עם זמר הפולק וודי גאת׳רי, למד ממנו כל שיר וכל תנועה, והפך ל"רמבלין׳ ג׳ק אליוט", ג׳ק הנודד. ב־1955 נסע לאנגליה, והופיע שם בפאבים ובמועדונים בשירים אמריקאיים שהבריטים הכירו רק מתקליטים. Jack Takes the Floor הוקלט שם, לחברת Topic הקטנה, ויצא ב־1958.''',
'''זה אלבום של אדם אחד וגיטרה: שירי בלוז, שירי עבודה, שירי קאובואים ובלדות עממיות, מנוגנים בגיטרה אקוסטית זריזה ומושרים בקול מחוספס ומחייך. אליוט מספר סיפורים, משחק עם המילים ושר בסגנון של גאת׳רי, של לד בלי ושל זמרי הבלוז שאהב. גאת׳רי עצמו אמר עליו פעם שהוא נשמע יותר כמוהו ממנו עצמו. השירים קצרים ופשוטים, וכמעט כולם שירי עם ישנים שעברו מפה לפה.''',
'''אליוט היה גשר: הוא לקח את המסורת של גאת׳רי והעביר אותה הלאה. באנגליה השפיע על סצנת הסקיפל והפולק, שממנה צמחו לימים חלק מלהקות הרוק הבריטיות. כשחזר לניו יורק, זמר צעיר בשם בוב דילן למד ממנו כל כך הרבה, עד שאליוט נהג להציג את השירים שלו על הבמה כ"שיר של הבן שלי, בוב דילן".''',
'''אחרי האלבום הזה, עברו לאלבום 36, The Freewheelin' Bob Dylan. הקשיבו לגיטרה, להרמוניקה ולדרך שבה דילן הצעיר מספר סיפור בשיר, ותשמעו כמה מזה הגיע ישר מג׳ק אליוט.''',
], [
('San Francisco Bay Blues', 'שיר של ג׳סי פולר שאליוט עזר להפוך לסטנדרט. חם, שמח ומזמין לשיר יחד.'),
('Mule Skinner’s Blues', 'שיר של ג׳ימי רוג׳רס, אבי הקאנטרי, עם יודל קטן ורוח של דרך פתוחה.'),
('Cocaine', 'בלוז מסורתי על התמכרות, שאליוט שר עם הומור יבש.'),
])

add(18, [
'''שרה ווהן גדלה בניוארק שבניו ג׳רזי, שרה בכנסייה, וב־1942, בגיל 18, ניצחה בתחרות כישרונות בתיאטרון אפולו בהארלם. זמן קצר אחר כך היא כבר שרה בלהקות שבהן ניגנו צ׳רלי פארקר ודיזי גילספי, בלב המהפכה של הביבופ. חבריה קראו לה Sassy, והקהל "האלוהית". באוגוסט 1957 היא הופיעה כמה ערבים במועדון Mister Kelly's בשיקגו, עם שלישייה קטנה: הפסנתרן ג׳ימי ג׳ונס, הבסיסט ריצ׳רד דייוויס והמתופף רוי היינס. ההקלטות מהערבים האלה הפכו לאלבום.''',
'''רק קול, פסנתר, בס ותופים, והאווירה של מועדון לילה אמיתי: כוסות, צחוקים וקהל שמגיב. ווהן משתמשת בטווח העצום של הקול שלה, מצלילים עמוקים כמו של זמרת אופרה ועד גבוהים וקלילים, ומשחקת עם המנגינות בחופש של נגנית ג׳אז. היא גם לא מפחדת לטעות: כשהיא מתבלבלת במילים, היא פשוט ממציאה חדשות, צוחקת על עצמה, וממשיכה לשיר.''',
'''האלבום נחשב לאחת ההקלטות החיות הטובות של זמרת ג׳אז, כי הוא תופס את ווהן רגועה ומשוחררת, בלי התזמורות הגדולות שליוו אותה באולפן. זה שיעור בשירת ג׳אז: איך לקחת שיר מוכר ולהפוך כל שורה בו להפתעה. וזה גם תיעוד של עולם שנעלם, של מועדוני לילה קטנים שבהם אפשר היה לשבת במרחק כמה מטרים מאחת הזמרות הגדולות בעולם.''',
'''חכו לסוף של Willow Weep for Me: השיר נגמר, אבל הלהקה ממשיכה לנגן, וווהן מאלתרת מילים על כך שהיא "הרסה את השיר הזה לגמרי", והקהל צוחק איתה. לא הייתם שומעים דבר כזה באולפן, וזה בדיוק מה שהופך את האלבום למיוחד.''',
], [
('September in the Rain', 'פתיחה קלילה שמראה מיד כמה בנוח ווהן מרגישה על הבמה הזאת.'),
('Willow Weep for Me', 'בלדה איטית שבה אפשר לשמוע את כל העומק והצבע של הקול, וגם את חוש ההומור שלה בסוף.'),
('How High the Moon', 'הסטנדרט שהפך להמנון של הביבופ, והזדמנות לשמוע את ווהן מאלתרת כמו כלי נגינה.'),
])

add(19, [
'''אלה פיצג׳רלד הייתה נערה יתומה ומחוסרת בית כשזכתה ב־1934 בתחרות כישרונות בתיאטרון אפולו בהארלם, ובתוך שנים ספורות הפכה לכוכבת. בשנות החמישים הקים המנהל שלה, נורמן גרנץ, את חברת Verve, במידה רבה כדי להקליט אותה, ויחד הם יצאו לפרויקט עצום: סדרה של "ספרי שירים", שבכל אחד מהם אלה שרה את המיטב של כותב אמריקאי גדול אחד. ספר השירים של האחים ג׳ורג׳ ואיירה גרשווין הוקלט במהלך 1959 ויצא בסוף השנה. זה הגדול והשאפתני שבהם: חמישה תקליטים, ויותר משלוש שעות של מוזיקה.''',
'''העיבודים של נלסון רידל, המעבד של סינטרה (אלבומים 1 ו־7), נעים בין תזמורת מלאה לבין רגעים אינטימיים עם כמה כלים בלבד. אלה שרה בבהירות מושלמת, בהגייה מדויקת ובחום, בלי להעמיס קישוטים ובלי לשכוח לסווינג. אפשר לשמוע כמה היא נהנית מהמילים המשעשעות והשנונות של איירה ומהמנגינות של ג׳ורג׳, שמת צעיר, ב־1937. לצד השירים המפורסמים יש כאן גם שירים נשכחים ממחזות זמר שכמעט אף אחד לא זוכר, והם מקבלים כאן יחס זהה. מהדורה מיוחדת שלו יצאה בקופסה מעץ, עם ציורים של הצייר הצרפתי ברנאר ביפה.''',
'''סדרת ספרי השירים קבעה לשירים האמריקאיים הגדולים גרסאות שנחשבות עד היום לקלאסיות. לאיירה גרשווין מיוחס המשפט "לא ידעתי כמה טובים השירים שלנו עד ששמעתי את אלה פיצג׳רלד שרה אותם". זה אולי המקום הטוב ביותר להתחיל בו להכיר את מה שנקרא "ספר השירים האמריקאי הגדול".''',
'''אל תנסו לשמוע את כל האלבום בבת אחת; הוא ארוך כמו שני סרטים. התחילו מ"האזנה ממוקדת" כאן באתר, שבוחרת כמה שירים מרכזיים, ואחר כך חזרו מדי פעם לאלבום המלא, כמו לספר שקוראים בו פרק בכל ערב.''',
], [
('Someone to Watch Over Me', 'בלדה עדינה שבה אלה מראה כמה מעט צריך כדי לרגש.'),
('’S Wonderful', 'גרשווין במיטבו: קליל, שנון ושמח, עם סווינג שמרים את כל החדר.'),
('They Can’t Take That Away from Me', 'שיר על זיכרונות אהבה שאף אחד לא יכול לקחת, בביצוע חם ובוגר.'),
])

add(20, [
'''ריי צ׳רלס איבד את הראייה בגיל שבע, למד מוזיקה בבית ספר לעיוורים בפלורידה, ועד גיל 15 איבד את שני הוריו. בשנות החמישים, בחברת Atlantic, הוא חיבר בשירים כמו I Got a Woman בין גוספל של כנסייה לבין ריתם אנד בלוז, ורבים רואים בזה את הלידה של הסול. ב־1959, השנה של הלהיט הענק What'd I Say, הוא רצה להוכיח שהוא יכול לשיר הכול, גם את השירים הקלאסיים של סינטרה ושל הזמרים הגדולים. The Genius of Ray Charles הוקלט בניו יורק באביב ובקיץ 1959, ויצא באוקטובר.''',
'''לאלבום שני פנים. בצד הראשון (ששת השירים הראשונים) להקה גדולה, עם נגנים שהגיעו מהתזמורות של קאונט בייסי ודיוק אלינגטון ועם עיבודים של קווינסי ג׳ונס הצעיר; היא שואגת ומסווינגת, וצ׳רלס צועק מעליה בהנאה. בצד השני (ששת האחרונים) בלדות עם תזמורת כלי מיתר, בעיבודים של ראלף ברנס, ושם צ׳רלס שר סטנדרטים ישנים לאט ובשקט, כאילו הוא ממציא אותם מחדש. מה שמחבר את שני הצדדים הוא הקול: צרוד, חם, ונשמע כמו כנסייה גם כשהוא שר שיר פופ ישן.''',
'''זו הייתה הפעם הראשונה שצ׳רלס הקליט אלבום שלם של סטנדרטים, צעד חשוב בדרך שבה אמן ריתם אנד בלוז שחור נכנס לעולם של שירת הפופ המבוגרת, בלי לוותר על הנשמה. זמן קצר אחר כך הוא עזב את Atlantic לחברה גדולה יותר, ובתוך שלוש שנים שבר גם את הגבול בין ריתם אנד בלוז לקאנטרי, באלבום 31.''',
'''שמעו את When Your Lover Has Gone כאן, ואחר כך את אותו שיר אצל סינטרה באלבום 1. אצל סינטרה זה לילה בודד ושקט; אצל צ׳רלס, עם להקה גדולה מאחוריו, כמעט אותן מילים נשמעות כמו מחאה.''',
], [
('Let the Good Times Roll', 'הפתיחה: להקה גדולה בכל הכוח, וצ׳רלס שמזמין את כולם למסיבה.'),
('Come Rain or Come Shine', 'בלדה ישנה שצ׳רלס שר בחום ובכאב, אחד הביצועים המוכרים ביותר שלה.'),
('Don’t Let the Sun Catch You Cryin’', 'בלוז איטי ועצוב, שמזכיר שצ׳רלס הוא גם זמר של שקט.'),
])

add(21, [
'''ב־1959 מיילס דייוויס כבר היה כוכב, עם להקה שהייתה אולי הטובה בעולם: ג׳ון קולטריין וקאנונבול אדרלי בסקסופונים, פול צ׳יימברס בבס וג׳ימי קוב בתופים. בפסנתר ישב ביל אוונס, שעזב את הלהקה כמה חודשים קודם אבל חזר במיוחד להקלטות, ובקטע אחד, Freddie Freeloader, מחליף אותו וינטון קלי. בשני מפגשים באולפן של Columbia בניו יורק, במרץ ובאפריל, הם הקליטו חמישה קטעים. הם הפכו לאלבום הג׳אז הנמכר בכל הזמנים.''',
'''דייוויס הביא לאולפן רק סקיצות, והנגנים כמעט לא ראו אותן לפני כן. במקום רצף מסובך של אקורדים שמתחלפים מהר, כמו בביבופ, הוא נתן להם סולמות ומצבי רוח. לזה קוראים ג׳אז מודאלי, והוא נותן לנגנים זמן לשהות בתוך צבע אחד ולבנות רעיון לאט. התוצאה שקטה, מרווחת ומלאה מתח עדין, וכל נגן נשמע כמו דמות אחרת באותו סיפור: דייוויס חסכוני ושקט, קולטריין סוער ומלא תווים, אדרלי שמח וחם. ביל אוונס כתב בעטיפה שהמוזיקה הזו דומה לציור יפני, שבו המכחול לא יכול לעצור ולא לתקן.''',
'''Kind of Blue שינה את הכיוון של הג׳אז: קולטריין, אוונס ודייוויס עצמו המשיכו ממנו כל אחד לדרך חדשה, והרעיון המודאלי השפיע גם על רוק, פולק ומוזיקה קלאסית. אבל יותר מכל, הוא דלת הכניסה הקלאסית לג׳אז: אלבום שאפשר לאהוב מההאזנה הראשונה, ולגלות בו עוד שכבות גם אחרי שנים.''',
'''זה אלבום שכדאי לתת לו תשומת לב מלאה, לפחות פעם אחת: בלי טלפון, בשקט, מהתחלה ועד הסוף. ואחר כך עברו לאלבום 30, של ביל אוונס עם השלישייה שלו, ותשמעו מאיפה הגיע חלק גדול מהשקט של Kind of Blue.''',
], [
('So What', 'שיחה בין הבס לשאר הלהקה, "So what?", ואז סולו של מיילס שכל נגן ג׳אז יודע לשיר.'),
('Blue in Green', 'בלדה קצרה ושברירית שבה הפסנתר של ביל אוונס קובע את מצב הרוח.'),
('All Blues', 'בלוז במשקל של שש, מתגלגל ורגוע, עם סולו יפהפה של כל אחד מהנגנים.'),
])

add(22, [
'''מרטי רובינס גדל במשפחה ענייה ליד פיניקס שבאריזונה. כילד קטן הוא ישב עם סבו, "טקסס" בוב הקל, שטען שהיה פעם ריינג׳ר בטקסס, והם עשו עסקה: הסבא מספר סיפור על המערב הפרוע, והנכד שר לו שיר. בשנות החמישים רובינס כבר היה כוכב קאנטרי, וב־1959, כשהמערבונים שלטו בטלוויזיה ובקולנוע, הוא נכנס לאולפן בנאשוויל והקליט ביום אחד, בסשן של שמונה שעות, אלבום שלם של בלדות קאובואים, חלקן שירים ישנים וחלקן שכתב בעצמו.''',
'''כל שיר הוא סרט קטן: אקדוחנים, סוסים, בתי סוהר ואהבות אסורות, מסופרים בקולו הנקי והחם של רובינס. הליווי צנוע ומדויק: גיטרות אקוסטיות, בס, תופים עדינים, והרמוניות קוליות של האחים גלייזר ברקע. את הגיטרה הספרדית המפורסמת של El Paso ניגן גריידי מרטין, מנגני האולפן הגדולים של נאשוויל. השירים לא ממהרים; הם נותנים לסיפור להתפתח עד הסוף, ולעתים קרובות הסוף הוא מוות.''',
'''El Paso הגיע למקום הראשון גם במצעד הפופ וגם במצעד הקאנטרי, למרות שאורכו כמעט חמש דקות, הרבה מעבר למקובל ברדיו אז, וזכה בפרס הגראמי. האלבום נחשב לקלאסיקה של שירי המערב, ולאחד האלבומים החשובים בקאנטרי. הוא השפיע על דורות של כותבי שירים שמספרים סיפורים, מג׳וני קאש ועד להקות אמריקנה של היום, ו־Big Iron זכה לחיים חדשים לגמרי אצל דור שגילה אותו דרך משחק מחשב.''',
'''זה אלבום של סיפורים, אז שווה לעקוב אחרי המילים. התחילו מ־El Paso: הקשיבו לו כמו לסרט קצר, עם התחלה, אמצע וסוף, ושימו לב איך הגיטרה הספרדית מספרת את הסיפור יחד עם הקול.''',
], [
('El Paso', 'קאובוי מתאהב ברקדנית מקסיקנית, הורג יריב ובורח, ואז חוזר. סיפור שלם, עם גיטרה ספרדית מופלאה.'),
('Big Iron', 'בלדה על ריינג׳ר עם אקדח ענק, שנכתבה בהשראת הסיפורים של הסבא, והפכה לאחד השירים המוכרים ביותר של רובינס.'),
('Cool Water', 'שיר ישן על מסע במדבר וצמא למים, בהרמוניה קולית שמרגישה כמו רוח חמה.'),
])

add(23, [
'''דייב ברובק, פסנתרן מקליפורניה שלמד מוזיקה קלאסית, היה אחד מכוכבי הג׳אז הפופולריים של שנות החמישים, בעיקר בקרב סטודנטים. ב־1958, בסיבוב הופעות מטעם משרד החוץ האמריקאי, הוא שמע באיסטנבול נגני רחוב מנגנים במשקל של תשע, והחליט להקליט אלבום שלם של קטעים במשקלים לא שגרתיים. Time Out הוקלט בקיץ 1959 בניו יורק, עם הרביעייה הקבועה שלו: פול דזמונד בסקסופון אלט, יוג׳ין רייט בבס וג׳ו מורלו בתופים. בחברת התקליטים חששו שאף אחד לא יקנה אותו.''',
'''במקום ה"אחת־שתיים־שלוש־ארבע" הרגיל של הג׳אז, יש כאן קטעים בחמש, בתשע, ובשילובים של שלוש וארבע. זה נשמע אולי מתמטי, אבל המוזיקה נגישה ומלודית מאוד, בזכות הסקסופון הרך והזורם של דזמונד, שנשמע כמו מישהו שמדבר בחצי חיוך, והתופים המדויקים של מורלו. ברובק עצמו מנגן באקורדים כבדים וגדולים, כמעט קלאסיים, שמעניקים לכל קטע משקל. גם העטיפה, ציור מופשט במקום תמונה של הלהקה, הייתה חריגה בזמנו.''',
'''הפחדים של חברת התקליטים התבדו: האלבום הגיע למקום השני במצעד הפופ, והיה אלבום הג׳אז הראשון שנמכר ביותר ממיליון עותקים. Take Five, שכתב דזמונד, הפך לתקליטון הג׳אז הנמכר בכל הזמנים, ואפשר לשמוע אותו עד היום בפרסומות, בסרטים ובמעליות. האלבום הוכיח שאפשר לשבור חוקים בלי לאבד את הקהל, ופתח את הג׳אז והרוק למשקלים חדשים.''',
'''נסו לספור עם Take Five: אחת־שתיים־שלוש־ארבע־חמש, שוב ושוב, עם הפסנתר שחוזר על אותו דפוס. אחרי כמה סיבובים זה מרגיש טבעי לגמרי. אחר כך נסו את Blue Rondo à la Turk, וספרו את התשע: אחת־שתיים, אחת־שתיים, אחת־שתיים, אחת־שתיים־שלוש.''',
], [
('Take Five', 'אחד מקטעי הג׳אז המפורסמים בעולם: מקצב של חמש, מנגינה שאי אפשר לשכוח, וסולו תופים באמצע.'),
('Blue Rondo à la Turk', 'נפתח בקצב הטורקי של תשע, ואז הופך בהפתעה לבלוז רגיל ומסווינג.'),
('Three to Get Ready', 'מתחיל כוואלס תמים, ואז מתחלף כל הזמן בין שלוש לארבע, בלי שזה מרגיש מסובך.'),
])

add(24, [
'''ג׳ואן באאז, בת לפיזיקאי ממוצא מקסיקני ולאם סקוטית, גדלה במקומות שונים בארצות הברית, והתחילה לשיר בבתי קפה בבוסטון כשהייתה סטודנטית. ב־1959, בגיל 18, היא הופיעה בפסטיבל הפולק הראשון של ניופורט והדהימה את הקהל. שנה אחר כך, בקיץ 1960, היא הקליטה את אלבום הבכורה שלה לחברת Vanguard. ההקלטות נעשו בארבעה לילות באולם נשפים של מלון בניו יורק (ביום רביעי אי אפשר היה, כי אז שיחקו שם בינגו), עם גיטרה אקוסטית, קול, ולפעמים גיטרה שנייה, וכמעט שום דבר אחר.''',
'''הקול של באאז הוא הכוכב: סופרן צלול, חזק ורועד, שנשמע כמעט על־זמני. השירים הם בלדות עממיות ישנות, רבות מהן מאנגליה ומסקוטלנד של לפני מאות שנים, על אהבה, בגידה ומוות, לצד שירים מאמריקה ומהקריביים, שיר מקסיקני, ואפילו שיר שמקורו ביידיש. היא לא מנסה להפוך אותם למודרניים או לקצביים; היא פשוט שרה אותם, בשקט ובכבוד, ונותנת לסיפור לעבוד.''',
'''האלבום הפך את באאז לכוכבת הראשונה של תחיית הפולק בתחילת שנות השישים, והראה שיש קהל גדול, ובעיקר צעיר, לשירים עתיקים שמושרים בפשטות. ב־1962 היא כבר הופיעה על שער המגזין Time. בשנים שאחר כך היא הזמינה זמר צעיר שעוד לא היה מוכר, בוב דילן, להופיע איתה, והשתמשה בפרסום שלה כדי להיאבק למען זכויות האזרח ונגד המלחמה בווייטנאם. גם היום, יותר משישים שנה אחר כך, היא נחשבת לאחד הקולות של הדור הזה.''',
'''שמעו את House of the Rising Sun כאן, ואחר כך באלבום 26, אצל מרים מקבה, שהקליטה אותו באותה שנה ממש. אותו שיר עם, שתי זמרות צעירות משני קצוות העולם, ושתי דרכים שונות לגמרי לספר אותו.''',
], [
('Donna Donna', 'שיר יידי ("דונה דונה") על עגל שמובל לשחיטה ועל סנונית שעפה חופשי, משל על חירות. שלום סקונדה ואהרן צייטלין כתבו אותו לתיאטרון היידי בניו יורק, ובאאז שרה אותו באנגלית.'),
('Silver Dagger', 'הפתיחה: אם מזהירה את בתה מפני גברים, בקול רועד ומלא אזהרה.'),
('House of the Rising Sun', 'שנים לפני הגרסה החשמלית של האנימלס, השיר הזה נשמע כאן כמו תפילה עגומה.'),
])

add(25, [
'''במרץ 1958 גויס אלביס פרסלי לצבא האמריקאי, ובמשך שנתיים שירת בעיקר בגרמניה. בזמן הזה אמו מתה, הרוקנרול התמתן, וכוכבים חדשים תפסו את מקומו ברדיו. רבים תהו אם מלך הרוקנרול יחזור להיות מה שהיה. בתחילת מרץ 1960 הוא השתחרר, ובתוך שבועיים כבר היה באולפן של RCA בנאשוויל, עם הלהקה הוותיקה שלו ועם כמה מנגני האולפן הטובים בעיר. בשני לילות ארוכים, במרץ ובאפריל, הוא הקליט את השירים שהפכו ל־Elvis Is Back!.''',
'''זה אלביס בוגר יותר: פחות צעקות ויותר שליטה, קול עמוק ובטוח, ובחירת שירים רחבה, מבלוז ודו־וופ ועד בלדות ורוקנרול. ברקע שרה קבוצת הקולות The Jordanaires, בוטס רנדולף מוסיף סקסופון, ופלויד קריימר מנגן בפסנתר. זה גם אחד האלבומים הראשונים של אלביס שהוקלטו בסטריאו, והטכנולוגיה החדשה נותנת לכל כלי מקום משלו. אפשר לשמוע כמה הוא נהנה: אחרי שנתיים של שתיקה, הוא שר כמו מי שחזר הביתה.''',
'''רבים מחשיבים את Elvis Is Back! לאלבום האולפן הטוב ביותר של אלביס, רגע שבו הראה כמה רחב הטווח שלו כזמר. אחריו הקריירה שלו פנתה בעיקר לסרטים ולפסקולים, והאלבומים הבאים שלו היו ברובם הרבה פחות מעניינים. לכן האלבום הזה נחשב לשיא האחרון של אלביס המוזיקאי לפני שנות הקולנוע, עד הקאמבק הגדול שלו בסוף שנות השישים.''',
'''שמעו את Reconsider Baby, ואחר כך חזרו לאלבום 2, שהוקלט ארבע שנים קודם. אותו זמר, אבל הנער המתגרה של 1956 הפך כאן לגבר ששר בלוז בנחת. ואם יש לכם אוזניות, הקשיבו איך הכלים מתפזרים בין שני הצדדים.''',
], [
('Fever', 'כמעט רק קול, בס ונקישות אצבעות. אלביס שר את השיר שפגי לי הפכה ללהיט, בפיתוי שקט.'),
('Reconsider Baby', 'בלוז אמיתי, עם סולו סקסופון של בוטס רנדולף. כאן שומעים כמה אלביס אהב בלוז.'),
('Such a Night', 'שיר של להקת The Drifters, שאלביס שר בהנאה גלויה ובמשחקי קול.'),
])

add(26, [
'''מרים מקבה נולדה ב־1932 ליד יוהנסבורג, וכבר בשנות החמישים הייתה כוכבת בדרום אפריקה, עם להקות קוליות כמו The Manhattan Brothers. ב־1959 הופיעה בסרט "חזרי, אפריקה", שצולם בחשאי ותיאר את החיים תחת משטר האפרטהייד. הסרט הוצג בפסטיבל ונציה, והביא אותה לאירופה ולאמריקה. שם הזמר הארי בלפונטה לקח אותה תחת חסותו, הופיע איתה, והפיק ב־1960 את אלבום הבכורה האמריקאי שלה.''',
'''מקבה שרה בקוסה, בזולו ובאנגלית, בקול עמוק וגמיש, שיכול להיות משחק ילדותי ורגע אחר כך קינה. השירים הם שירי עם, שירי חתונה ושירי ילדים מדרום אפריקה, לצד כמה שירים מערביים, בליווי קטן וחם של גיטרות, בס וכלי הקשה. בשירים בקוסה אפשר לשמוע את צלילי ההקלקה של השפה, צלילים שהקהל המערבי לא שמע כמעט אף פעם לפני כן. היא שרה אותם בשמחה, בגאווה, ובלי לנסות "לתרגם" אותם לאוזן האמריקאית.''',
'''זה היה אחד האלבומים הראשונים שהביאו מוזיקה דרום אפריקאית לקהל מערבי רחב. באותה שנה אמה מתה, וכשמקבה ניסתה לחזור הביתה להלוויה, התברר שממשלת האפרטהייד ביטלה את הדרכון שלה. היא חיה בגלות כשלושים שנה, זכתה בפרס הגראמי, נאמה באו״ם נגד האפרטהייד, והפכה ל"מאמא אפריקה", אחד הקולות החשובים במאבק. היא חזרה לדרום אפריקה רק ב־1990, אחרי שנלסון מנדלה שוחרר מהכלא.''',
'''שמעו את Mbube, ואחר כך את The Lion Sleeps Tonight, הלהיט האמריקאי שנולד ממנו. אותה מנגינה, אבל כאן תשמעו את השורשים. ואחרי House of the Rising Sun, עברו לגרסה של ג׳ואן באאז באלבום 24.''',
], [
('The Click Song', 'שיר חתונה בשפת הקוסה, מלא בצלילי ההקלקה של השפה, שהפך לסימן ההיכר של מקבה.'),
('Mbube', 'השיר של סולומון לינדה, שהעולם הכיר לימים בשם The Lion Sleeps Tonight.'),
('House of the Rising Sun', 'באותה שנה שבה ג׳ואן באאז שרה אותו (אלבום 24), מקבה נותנת לו צבע אחר לגמרי.'),
])

add(27, [
'''דון ופיל אוורלי, בנים למשפחת מוזיקאים מקנטקי, הופיעו כילדים בתוכנית הרדיו של הוריהם באיווה. בסוף שנות החמישים הם הפכו לצמד הגדול של הרוקנרול, עם להיטים כמו Bye Bye Love ו־Wake Up Little Susie. בתחילת 1960 הם חתמו על חוזה לעשר שנים עם חברת Warner Bros., שהוצג בעיתונות כחוזה של מיליון דולר, אחד הגדולים שנחתמו אז עם אמני רוקנרול. A Date With the Everly Brothers יצא בסוף אותה שנה, שבה שלטו במצעדים באמריקה ובבריטניה.''',
'''הלב הוא ההרמוניה: שני קולות קרובים כל כך שהם נשמעים כמו קול אחד. דון שר בדרך כלל את המנגינה, ופיל מעליו בקול גבוה ובהיר. זו מסורת שהגיעה ישר מצמדי האחים של הקאנטרי, ובראשם האחים לובין (אלבום 3). מסביב יש גיטרות רוקנרול, תופים חיים וצליל מלא ועשיר יותר מבעבר, ושירים שנעים בין רוק מהיר, בלדות שבורות לב ושירים ששואלים מהקאנטרי ומהבלוז. רוב השירים קצרים, בסביבות שתי דקות וחצי.''',
'''ההרמוניות של האחים אוורלי השפיעו ישירות על הביטלס, על סיימון וגרפונקל, על הביץ׳ בויז ועל אינספור להקות. ג׳ון לנון ופול מקרטני סיפרו שבתחילת הדרך רצו להישמע כמוהם. האלבום מראה אותם ברגע של מעבר, מרוקנרול של נערים אל פופ בוגר יותר, רגע לפני שהביטלס עצמם יתפסו את המקום שלהם.''',
'''שימו אוזניות, ונסו לעקוב בכל פעם אחרי קול אחד: פעם אחרי הקול הגבוה, פעם אחרי הנמוך. זה קשה יותר ממה שנשמע, וזה בדיוק הקסם. אחר כך חזרו לאלבום 3, של האחים לובין, ותשמעו מאיפה זה הגיע.''',
], [
('Cathy’s Clown', 'הלהיט הגדול ביותר שלהם, שהגיע למקום הראשון באמריקה ובבריטניה, עם תופים שמהדהדים כמו צעדים.'),
('Love Hurts', 'בלדה של בודלו בראיינט שהאחים אוורלי הקליטו ראשונים. לימים הקליטו אותה רוי אורביסון, גראם פרסונס ורבים אחרים.'),
('Lucille', 'השיר של ליטל ריצ׳רד (אלבום 14), בגרסה עם הרמוניה כפולה.'),
])

add(28, [
'''ג׳ימי סמית׳, מפנסילבניה, התחיל כפסנתרן, אבל באמצע שנות החמישים עבר לעוגב החשמלי של המונד, כלי שהיה שייך בעיקר לכנסיות, לתחנות רדיו ולמגרשי החלקה. הוא הפך אותו לכלי ג׳אז מוביל. כשהופיע לראשונה בניו יורק ב־1956, זה היה כמו פיצוץ, וחברת Blue Note החתימה אותו מיד. Back at the Chicken Shack הוקלט ב־1960, באותו יום כמו אלבום אחר שלו, ויצא רק ב־1963, בשיא הפופולריות של הסגנון שנקרא סול ג׳אז.''',
'''ארבעה נגנים בלבד: סמית׳ בעוגב, סטנלי טורנטיין בסקסופון טנור, קני בורל בגיטרה ודונלד ביילי בתופים. אין בסיסט, כי סמית׳ מנגן את הבס בעצמו, ברגליים על הדוושות של העוגב ובידו השמאלית, וביד ימין מנגן מנגינות וסולואים. ארבעה קטעים ארוכים ורגועים, מלאים בבלוז ובגרוב ובאווירה של בר שכונתי במוצאי שבת. הסקסופון של טורנטיין חם ועבה, והגיטרה של בורל נקייה ואלגנטית, וביחד הם נשמעים כמו חבורה שמנגנת בשביל הכיף.''',
'''האלבום מראה את הצד העממי של הג׳אז: מוזיקה לריקוד, לשתייה ולשיחה, לא רק להאזנה רצינית. סמית׳ מכר הרבה תקליטים, והעוגב נכנס לכל בר עם תיבת נגינה בשכונות השחורות של אמריקה. הצליל שלו השפיע על מוזיקת הסול, על Booker T. & the M.G.'s (אלבום 32), ועל נגני קלידים ברוק לאורך עשרות שנים.''',
'''זה אלבום לשעת ערב, עם משקה ביד, ולא אלבום לניתוח. אבל אם בא לכם לגלות משהו, הקשיבו לצלילים הנמוכים ביותר ב־Messy Bessie: זה הבס שסמית׳ מנגן ברגליים, בזמן שהידיים שלו עסוקות בכל השאר.''',
], [
('Back at the Chicken Shack', 'בלוז איטי ומתוק, שבו העוגב והסקסופון מדברים זה עם זה.'),
('Messy Bessie', 'הקטע הארוך והחופשי ביותר, עם סולואים של כל הלהקה. אפשר להרגיש את הזיעה.'),
('When I Grow Too Old to Dream', 'שיר ישן משנות השלושים, שמקבל כאן סווינג קליל וחם.'),
])

add(29, [
'''מקינלי מורגנפילד, שכונה מאדי ווטרס, גדל במטע כותנה במיסיסיפי, ושם הוקלט לראשונה ב־1941 בידי חוקר המוזיקה העממית אלן לומקס. ב־1943 הוא עבר לשיקגו, חיבר את הגיטרה שלו למגבר כדי שישמעו אותו בבארים הרועשים, ויצר את הבלוז החשמלי של שיקגו. ב־3 ביולי 1960 הוא עלה לבמה של פסטיבל הג׳אז של ניופורט, מול קהל לבן ברובו, בחליפה אלגנטית ועם להקה שהייתה אולי הטובה בעולם הבלוז. לילה קודם פרצו בעיר מהומות של צעירים שלא הצליחו להיכנס, והוחלט שהפסטיבל ייסגר מוקדם. ההופעה של מאדי הייתה בין האחרונות.''',
'''שומעים להקה חשמלית במלוא הכוח: הפסנתר של אוטיס ספאן, המפוחית של ג׳יימס קוטון, גיטרות, בס ותופים, ומעליהם מאדי, ששר בקול עמוק, בטוח ומלא הומור. זה לא בלוז עצוב ושקט של אדם יושב עם גיטרה; זה בלוז של עיר גדולה, מלא ביטחון עצמי וגאווה. בסוף ההופעה הם ניגנו את Got My Mojo Working, והקהל התלהב כל כך שהם ניגנו אותו שוב. על העטיפה מאדי מחזיק גיטרה שבכלל הייתה של ג׳ון לי הוקר, כי שלו לא הייתה בהישג יד לצילום.''',
'''זה נחשב לאחד מאלבומי הבלוז החיים הראשונים, והוא הביא את הבלוז החשמלי לקהל חדש, לבן וצעיר. באנגליה הוא השפיע ישירות על מוזיקאים צעירים כמו הרולינג סטונס, שלקחו את השם שלהם משיר של מאדי ווטרס. בלי הבלוז הזה קשה לדמיין את הרוק של שנות השישים.''',
'''שמעו את שתי הגרסאות של Got My Mojo Working זו אחרי זו, והקשיבו לקהל: אפשר לשמוע את הרגע שבו אנשים שבאו לפסטיבל ג׳אז מגלים משהו חדש. אחר כך עברו לאלבום 46, של הרולינג סטונס, ותשמעו מה נערים בלונדון עשו עם המוזיקה הזאת כמה שנים אחר כך.''',
], [
('Got My Mojo Working', 'הרגע שבו הקהל בניופורט יצא מדעתו. אפשר לשמוע אותו מוחא כפיים ומבקש עוד.'),
('I’m Your Hoochie Coochie Man', 'אחד משירי הבלוז המפורסמים בעולם: גאוותני, מאיים ומצחיק בבת אחת.'),
('Goodbye Newport Blues', 'כשהתברר שהפסטיבל נסגר, המשורר לנגסטון יוז כתב במקום מילים של פרידה, ואוטיס ספאן שר אותן.'),
])

add(30, [
'''ביל אוונס, הפסנתרן של Kind of Blue (אלבום 21), היה בחור שקט ומופנם מניו ג׳רזי, שלמד מוזיקה קלאסית לפני שעבר לג׳אז. ב־1959 הוא הקים שלישייה עם הבסיסט הצעיר סקוט לה פארו והמתופף פול מושן. ביום ראשון, 25 ביוני 1961, הם הופיעו חמש פעמים במועדון Village Vanguard בניו יורק, והכול הוקלט. פחות משבועיים אחר כך לה פארו נהרג בתאונת דרכים, בגיל 25. אוונס כמעט הפסיק לנגן בחודשים שאחרי.''',
'''בשלישיית ג׳אז רגילה הפסנתר מוביל, והבס והתופים מלווים. כאן שלושת הנגנים מדברים זה עם זה כשווים: הבס של לה פארו לא רק שומר על הקצב אלא שר מנגינות משלו, עונה לפסנתר ולפעמים מוביל אותו. התופים של מושן לוחשים, בעיקר במברשות, ואוונס מנגן בעדינות, בהרמוניות עשירות ובאיפוק. זה נשמע כמו שיחה אינטימית בין שלושה חברים. ברקע אפשר לשמוע את המועדון עצמו: כוסות, צחוק, ואנשים שמדברים בזמן שההיסטוריה קורית לידם.''',
'''ההופעות מאותו יום, שיצאו באלבום הזה ובאלבום נוסף בשם Waltz for Debby, נחשבות לאחת מהקלטות הג׳אז החיות הגדולות. הן שינו את הדרך שבה מנגנות שלישיות פסנתר עד היום. האלבום הזה יצא כמה חודשים אחרי מותו של לה פארו, כמעין מחווה לו, ובחרו לכלול בו שני קטעים שהוא עצמו כתב.''',
'''שמעו את האלבום פעם אחת רק דרך הבס: עקבו אחרי לה פארו, ותשמעו כמה הוא עושה מעבר ל"ליווי". ואחרי זה חזרו ל־Blue in Green באלבום 21, ותשמעו את אוונס שנתיים קודם, בתוך הלהקה של מיילס דייוויס.''',
], [
('Gloria’s Step', 'קטע שכתב לה פארו. הקשיבו איך הבס לא רק מלווה, אלא ממש משתתף בשיחה.'),
('My Man’s Gone Now', 'שיר מתוך האופרה "פורגי ובס" של גרשווין, בקריאה איטית ועצובה מאוד.'),
('Jade Visions', 'עוד יצירה של לה פארו: קצרה, חלומית ושקטה, כמעט כמו מוזיקה קאמרית.'),
])

add(31, [
'''ריי צ׳רלס, שהתעוור בילדותו וגדל בעוני בפלורידה, שמע בנעוריו לא רק בלוז וגוספל אלא גם את תוכניות הקאנטרי ברדיו, והאהבה הזאת נשארה איתו. ב־1959 הוא עבר מחברת Atlantic לחברת ABC-Paramount, בחוזה נדיר לאמן שחור באותם ימים: חופש אמנותי מלא ובעלות על ההקלטות שלו. בתחילת 1962 הוא השתמש בחופש הזה למשהו שאנשי החברה חששו ממנו מאוד: אלבום שלם של שירי קאנטרי, המוזיקה של אמריקה הלבנה והכפרית, בזמן שבדרום ארצות הברית עוד שלטה ההפרדה הגזעית. ההקלטות נעשו בפברואר 1962, בניו יורק ובהוליווד, והאלבום יצא כבר באפריל.''',
'''צ׳רלס לקח שירים של האנק וויליאמס, דון גיבסון, האחים אוורלי (אלבום 27) ואחרים, ושר אותם כמו שירי נשמה. בחלק מהשירים מנגנת להקה גדולה וסוחפת בעיבודים של ג׳רלד וילסון וגיל פולר, ובבלדות עוטפים אותו כלי מיתר ומקהלה בעיבודים של מרטי פייץ׳. הוא לא מחקה את הקאנטרי ולא לועג לו. הוא מגלה בו את אותו כאב, אותה כנות ואותו הומור שיש בבלוז ובגוספל, ומראה שאלה בעצם אותם סיפורים: אהבה שנגמרה, בדידות ושתייה.''',
'''החשש התברר כמיותר. I Can’t Stop Loving You הגיע למקום הראשון במצעד הסינגלים האמריקאי ונשאר שם חמישה שבועות, והאלבום עמד בראש מצעד האלבומים ארבעה־עשר שבועות ומכר יותר ממיליון עותקים. זה היה אחד הרגעים הגדולים שבהם מוזיקה חצתה את קווי הגזע באמריקה: זמר שחור הפך את המוזיקה של הדרום הלבן ללהיט הגדול של השנה, וקהלים שונים לגמרי גילו שהם אוהבים את אותם שירים. באותה שנה כבר יצא אלבום המשך, וזמרי קאנטרי רבים סיפרו מאז שצ׳רלס עשה למוזיקה שלהם כבוד שהיא לא קיבלה קודם.''',
'''שמעו קודם את Hey, Good Lookin’ ואת You Win Again, שני שירים של האנק וויליאמס, ונסו לדמיין אותם בגרסה הכפרית והפשוטה שלו. ואז עברו לאלבום 34, של ריי פרייס, כדי לשמוע איך נשמע קאנטרי של אותה שנה מבפנים.''',
], [
('I Can’t Stop Loving You', 'השיר של דון גיבסון, עם מקהלה שעונה לצ׳רלס שורה אחרי שורה. הלהיט הגדול של 1962.'),
('You Don’t Know Me', 'בלדה על אהבה שמעולם לא נאמרה בקול, מושרת ברוך שובר לב.'),
('Hey, Good Lookin’', 'השיר העליז של האנק וויליאמס הופך כאן למסיבת סווינג של להקה גדולה.'),
])

add(32, [
'''בממפיס של תחילת שנות השישים, בבית קולנוע ישן שהפך לאולפן של חברת Stax, ישבה להקת הבית: בוקר טי ג׳ונס, תלמיד תיכון בן 17 בעוגב, סטיב קרופר בגיטרה, לואי סטיינברג בבס ואל ג׳קסון ג׳וניור בתופים. ביוני 1962, בזמן שחיכו לזמר שהיו אמורים ללוות, הם התחילו לאלתר בלוז פשוט, ומישהו הקליט. כך נולד Green Onions. הקטע יצא כסינגל בקיץ, הגיע למקום הראשון במצעד הריתם אנד בלוז ולמקום השלישי במצעד הכללי, ואלבום שלם נבנה סביבו במהירות.''',
'''אין כאן שירה בכלל. שומעים עוגב המונד שמנגן ריף עקשני ומלא בטחון, גיטרה שמכה קצר וחד, כמעט כמו תוף, בס שהולך בצעדים יציבים, ותופים שמחזיקים גרוב בלי שום מאמץ. שאר האלבום מלא בגרסאות אינסטרומנטליות ללהיטים של אותה תקופה, כמו Twist and Shout ו־I Got a Woman, לצד כמה קטעים מקוריים. הכול נשמע רגוע, מדויק ומגניב: ארבעה נגנים שיודעים בדיוק מתי לנגן ומתי לשתוק, ולא מנסים להרשים איש.''',
'''בדרום של ההפרדה הגזעית, זו הייתה להקה מעורבת: שני נגנים שחורים ושני נגנים לבנים, שעבדו יחד כל יום באולפן. בשנים הבאות, כשדונלד "דאק" דאן החליף את סטיינברג בבס, הם ליוו כמעט את כל כוכבי הסול של Stax, מאוטיס רדינג ועד סאם אנד דייב, ובעצם בנו את הצליל של הסול של ממפיס: חסכוני, חם ומדויק. Green Onions עצמו מופיע עד היום בסרטים, בפרסומות ובאירועי ספורט, ורבים שמכירים את הריף לא יודעים מי ניגן אותו.''',
'''השוו את I Got a Woman כאן לגרסה של אלביס באלבום 2, ותשמעו שתי דרכים שונות לגמרי לקחת את אותו שיר של ריי צ׳רלס. ואחר כך עברו לאלבום 51, של אוטיס רדינג: אותם נגנים, שלוש שנים אחר כך, מאחורי אחד הזמרים הגדולים של הסול.''',
], [
('Green Onions', 'אחד הריפים המוכרים במוזיקה הפופולרית. הקשיבו לגיטרה של קרופר, שנכנסת בכל פעם כמו סכין.'),
('Behave Yourself', 'הצד השני של התקליטון: בלוז איטי שבו העוגב של בוקר טי מתחמם לאט לאט.'),
('Comin’ Home Baby', 'גרוב קליל של ג׳אז וסול שמסיים את האלבום בחיוך.'),
])

add(33, [
'''ב־1961 יצא הגיטריסט האמריקאי צ׳רלי בירד לסיבוב הופעות בדרום אמריקה מטעם משרד החוץ האמריקאי, ובברזיל גילה סגנון חדש שנולד בריו דה ז׳ניירו כמה שנים קודם: בוסה נובה. הוא חזר הביתה עם תקליטים, ושכנע את הסקסופוניסט סטן גץ, מהכוכבים הגדולים של הג׳אז, לנסות אותו. ב־13 בפברואר 1962 הם נפגשו באולם של כנסייה בוושינגטון, עם שני בסיסטים ושני מתופפים, והקליטו את כל האלבום ביום אחד.''',
'''הבוסה נובה, "הגל החדש", היא סמבה שהורידה את הקול: במקום תופי קרנבל רועשים, מקצב עדין ומתנדנד של גיטרה ותופים עם מברשות, ומעליו מנגינות רכות והרמוניות עשירות שמזכירות ג׳אז. גץ, שכונה "הצליל" בגלל הטון הרך והנקי של הסקסופון שלו, מנגן את המנגינות של אנטוניו קרלוס ז׳ובים ושל כותבים ברזילאים אחרים כאילו נולד בריו, ובירד מנגן על גיטרה קלאסית, עם מיתרי ניילון, בנגיעות קטנות ומדויקות. הכול שקט, נינוח ושמשי.''',
'''Desafinado ("לא מכוון"), שיר שז׳ובים כתב בחיוך כתשובה למבקרים שטענו שזמרי הבוסה נובה שרים מזויף, הפך ללהיט. האלבום הגיע ב־1963 למקום הראשון במצעד האלבומים האמריקאי, הישג כמעט חסר תקדים לאלבום ג׳אז, ונשאר במצעד יותר משנה. הוא פתח את בהלת הבוסה נובה בארצות הברית ובעולם: פתאום כל נגן ג׳אז רצה להקליט "סמבה". הגל הזה הגיע לשיאו שנתיים אחר כך, כשגץ נפגש עם הברזילאים עצמם באלבום 41.''',
'''שמעו את Desafinado כאן, ומיד אחריו את הגרסה באלבום 41, עם ז׳ואאו ז׳ילברטו בשירה ובגיטרה. זה אותו שיר ואותו סקסופון, אבל אפשר לשמוע מה קורה כשהמקצב מגיע ישר מברזיל.''',
], [
('Desafinado', 'השיר של ז׳ובים שהפך ללהיט ופתח את כל הגל. הקשיבו איך המנגינה נשמעת כמעט "מזויפת" בכוונה.'),
('Samba de Uma Nota Só', '"סמבה של תו אחד": המנגינה חוזרת שוב ושוב על אותו תו, בזמן שההרמוניה משתנה מתחתיה.'),
('É Luxo Só', 'שיר של ארי בארוזו, מגדולי הכותבים של ברזיל, בסווינג קליל ושמח.'),
])

add(34, [
'''ריי פרייס מטקסס התחיל את דרכו בנאשוויל בתחילת שנות החמישים כחבר קרוב של האנק וויליאמס, שאפילו גר איתו זמן מה. אחרי מותו של וויליאמס פרייס מצא קול משלו, ומ־1956, עם הלהיט Crazy Arms, הוא הפך לאחד מכוכבי ההונקי טונק, הקאנטרי של הברים. בלהקה שלו, The Cherokee Cowboys, עברו לאורך השנים נגנים שהפכו אחר כך לכוכבים, ובתחילת שנות השישים ניגן בה גם כותב שירים צעיר ורעב מטקסס בשם ווילי נלסון. ב־1963 הקליט פרייס אלבום שלם סביב שיר שנלסון כתב: Night Life.''',
'''הצליל הוא של בר טקסני בשעה מאוחרת: גיטרת פדל סטיל מייללת, כינור, פסנתר, ומקצב השאפל המתנדנד שפרייס עצמו הפך לסימן ההיכר של הקאנטרי הטקסני. האלבום נפתח כמו ערב במועדון, עם הצגה קצרה של הלהקה, ומשם עובר משיר לשיר על אורות הבר, על בדידות ועל אהבות שנכשלו. בשיר הנושא נגן הסטיל באדי אמונס מנגן פתיחה בלוזית שהפכה לאחד הצלילים המפורסמים בקאנטרי, והקול של פרייס, חלק, עמוק ורגוע, מחזיק את הכול.''',
'''Night Life הוא אחד מאלבומי הקונספט המוקדמים בקאנטרי, והוא מראה את הז׳אנר במיטבו: עצוב, בוגר ואלגנטי, בלי להתייפייף. השאפל של פרייס השפיע על דור שלם של זמרי קאנטרי, והשיר Night Life, שנלסון כתב כשהיה עוד אלמוני, הפך לאחד השירים המוקלטים ביותר שלו, מזמרי קאנטרי ועד זמרי בלוז. כמה שנים אחר כך פרייס עצמו עבר לסגנון רך יותר, עם כלי מיתר, אבל רבים רואים באלבום הזה את השיא שלו.''',
'''זה אלבום ללילה, כמו אלבום 1 של סינטרה: מאוחר, ברצף ובלי לדלג. ואם תרצו לשמוע את אותה מסורת הונקי טונק מתפתחת לכיוונים אחרים, עברו לבאק אוונס באלבום 47 ולמרל הגארד באלבום 99.''',
], [
('Introduction and Theme / Night Life', 'הצגת הלהקה, ואחריה שיר הנושא של ווילי נלסון. הקשיבו לגיטרת הסטיל בפתיחה.'),
('The Wild Side of Life', 'להיט הונקי טונק קלאסי מתחילת שנות החמישים, על אישה שבחרה בחיי הלילה.'),
('Let Me Talk to You', 'בלדה שמראה את הקול העשיר והרגוע של פרייס במיטבו.'),
])

add(35, [
'''בשנת 1963 הביטלס הפכו מלהקה מליברפול לתופעה, ובריטניה נכנסה ל"ביטלמניה". האלבום השני שלהם הוקלט בין יולי לאוקטובר, בימים ספורים שנגנבו בין הופעות, שידורי רדיו ותוכניות טלוויזיה. הוא יצא ב־22 בנובמבר 1963, היום שבו נרצח הנשיא קנדי (ובאותו יום יצא גם אלבום 37), עם מאות אלפי הזמנות מראש, והחליף בראש המצעד הבריטי את אלבום הבכורה שלהם. את העטיפה צילם רוברט פרימן: ארבעה פרצופים בשחור־לבן בחצי צל, בהשראת תמונות שצילמה חברה שלהם בהמבורג. היא הפכה לאחת המפורסמות בעולם.''',
'''זה רוקנרול צעיר, מהיר ומלא אנרגיה: שתי גיטרות, בס, תופים והרמוניות קוליות צפופות של ג׳ון, פול וג׳ורג׳. יש כאן שמונה שירים מקוריים, ביניהם Don’t Bother Me, השיר הראשון שכתב ג׳ורג׳ הריסון, לצד שישה שירים של אחרים שהם אהבו וניגנו על הבמות: להיטים של חברת מוטאון, רוקנרול של צ׳אק ברי, ואפילו שיר ממחזמר בברודווי, Till There Was You. השיר I Wanna Be Your Man נמסר באותם ימים גם לרולינג סטונס, שהפכו אותו לסינגל השני שלהם.''',
'''With the Beatles הראה שהביטלס הם לא רק להקה של סינגלים. הכתיבה של לנון ומקרטני כבר מלוטשת, והשילוב בין ריתם אנד בלוז אמריקאי שחור לבין מלודיות בריטיות קבע את הצליל של "הפלישה הבריטית", שהגיעה לאמריקה חודשים ספורים אחר כך. בארצות הברית רוב השירים יצאו בינואר 1964 באלבום אחר, Meet the Beatles!, שהיה חלק מהפיצוץ הגדול של הלהקה שם.''',
'''שמעו את Please Mr. Postman ואת You Really Got a Hold on Me, שני שירים של מוטאון, ותשמעו מה הביטלס למדו מהמוזיקה השחורה האמריקאית. ואז עברו לאלבום 42, שיצא פחות משנה אחר כך, וכל השירים בו כבר של לנון ומקרטני.''',
], [
('All My Loving', 'אחד השירים הראשונים שבהם מקרטני הראה איזה כותב מלודיות הוא. הקשיבו לגיטרה המהירה של לנון ברקע.'),
('Don’t Bother Me', 'השיר הראשון של ג׳ורג׳ הריסון: קודר, מפתיע ושונה מכל השאר.'),
('Money (That’s What I Want)', 'סיום צועק ופרוע של ג׳ון לנון, בגרסה לשיר של מוטאון.'),
])

add(36, [
'''בוב דילן הגיע לניו יורק בינואר 1961, צעיר בן 19 ממינסוטה שחלם להיות וודי גאת׳רי, זמר העם הגדול. המפיק ג׳ון המונד מחברת Columbia החתים אותו, ואלבום הבכורה שלו היה בעיקר שירי עם של אחרים ומכר מעט. אבל באלבום השני, שיצא במאי 1963, דילן כבר כותב כמעט הכול בעצמו, והעולם מגלה כותב שירים מסוג חדש. על העטיפה הוא מתהלך ברחוב מושלג בגריניץ׳ וילג׳, צמוד לחברתו סוזי רוטולו, שהשפיעה מאוד על ההשכלה הפוליטית והאמנותית שלו.''',
'''רוב הזמן זה רק דילן: גיטרה אקוסטית, מפוחית וקול צרוד ולא מלוטש. הוא שר על מלחמה, על הפחד מהפצצה הגרעינית, על גזענות ועל אהבה שנגמרה, לפעמים בכעס, לפעמים בהומור ולפעמים ברוך גדול. המנגינות לקוחות לעתים קרובות ממסורת העם: את Girl from the North Country הוא בנה על מנגינה של שיר עם אנגלי ששמע בביקור בלונדון. אבל המילים מודרניות ושירתיות. A Hard Rain’s a-Gonna Fall נחשב הרבה פעמים לתגובה למשבר הטילים בקובה, אבל דילן שר אותו כבר בספטמבר 1962, כמה שבועות לפני המשבר.''',
'''Blowin’ in the Wind הפך ללהיט בביצוע של הלהקה Peter, Paul and Mary ולהמנון של התנועה לזכויות האזרח, והאלבום הפך את דילן בן ה־22 ל"קול של דור", תואר שהוא עצמו שנא. הוא שינה את מה ששיר פופולרי יכול להגיד, והשפיע על הביטלס, על כותבי השירים של שנות השישים ועל כל מי שכתב שיר מחאה מאז.''',
'''שמעו את Girl from the North Country, ואחר כך את Scarborough Fair שפותח את אלבום 71 של סיימון וגרפונקל: שניהם צמחו מאותו שיר עם אנגלי. ואם תרצו לשמוע לאן דילן הגיע שנתיים אחר כך, קפצו לאלבום 50, עם הגיטרה החשמלית.''',
], [
('Blowin’ in the Wind', 'שאלות פשוטות על מלחמה וחירות, בלי תשובות. אחד השירים המוכרים בעולם.'),
('A Hard Rain’s a-Gonna Fall', 'שיר ארוך של דימויים אפוקליפטיים, כמו נבואה. כל שורה יכולה להיות שיר בפני עצמו.'),
('Don’t Think Twice, It’s All Right', 'שיר פרידה מר־מתוק, עם נגינת אצבעות מהירה ויפה בגיטרה.'),
])

add(37, [
'''פיל ספקטור היה המפיק החם ביותר בפופ של תחילת שנות השישים. באולפן Gold Star בלוס אנג׳לס הוא בנה את מה שכונה "חומת הצליל": עשרות נגנים, כמה גיטרות, כמה פסנתרים, כלי הקשה ותופים שמנגנים יחד, והכול מהדהד בתוך חדר הדהוד עד שכבר אי אפשר להפריד כלי מכלי. ב־1963 הוא לקח את הזמרות של חברת התקליטים שלו, The Ronettes, The Crystals ודרלין לאב, יחד עם הלהקה Bob B. Soxx & the Blue Jeans, ויצר אלבום של שירי חג המולד, עם המתופף האל בליין ונגני האולפן הטובים בעיר.''',
'''שירי חג מולד מוכרים, כמו Frosty the Snowman ו־Winter Wonderland, מקבלים טיפול של פופ־רוק מתפוצץ: פעמונים, מקהלות, תופים עוצמתיים וקולות נשיים חזקים. זה נשמע כמו חג המולד בגרסת רוקנרול, מבריק ורועש. יש כאן רק שיר מקורי אחד, Christmas (Baby Please Come Home), שספקטור כתב עם זוג הכותבים אלי גריניץ׳ וג׳ף בארי. ובסוף, על רקע Silent Night, ספקטור עצמו מדבר ומודה למאזינים, כמו כתוביות הסיום של סרט.''',
'''האלבום יצא ב־22 בנובמבר 1963, היום שבו נרצח הנשיא קנדי, ואמריקה לא הייתה במצב רוח לחגוג. הוא נכשל, ורק כשיצא מחדש ב־1972 התחיל להפוך לקלאסיקה, ומאז הוא נחשב לאחד מאלבומי חג המולד הגדולים של הפופ. דרלין לאב שרה את Christmas (Baby Please Come Home) בטלוויזיה האמריקאית שנה אחרי שנה, והשיר הפך למסורת. הסאונד של ספקטור השפיע על הביץ׳ בויז, על ברוס ספרינגסטין ועל כל מי שרצה פופ גדול מהחיים. לסיפור יש גם צד אפל: ספקטור עצמו הורשע ב־2009 ברצח, ומת בכלא.''',
'''אחרי האלבום הזה עברו לאלבום 61, Pet Sounds: בריאן וילסון מהביץ׳ בויז העריץ את ספקטור, עבד עם חלק מאותם נגנים, ולקח את חומת הצליל למקום אישי ושקט הרבה יותר.''',
], [
('Christmas (Baby Please Come Home)', 'השיר המקורי היחיד באלבום, ודרלין לאב שרה אותו בכל הלב. הפך לאחד משירי חג המולד האהובים.'),
('Sleigh Ride', 'הרונטס עם פעמונים, סוסים וקריאות "רינג־א־לינג": פופ חורפי מושלם.'),
('Frosty the Snowman', 'שיר ילדים שהופך ללהיט של הרונטס, עם כל העוצמה של חומת הצליל.'),
])

add(38, [
'''סאם קוק התחיל כזמר גוספל מהולל בלהקה The Soul Stirrers, עבר לפופ ב־1957 עם You Send Me, והפך לאחד הזמרים השחורים המצליחים באמריקה, עם קול מתוק ותדמית חלקה ומלוטשת. הוא גם היה איש עסקים חריף, עם חברת תקליטים משלו. ב־12 בינואר 1963 הוא הופיע במועדון Harlem Square בצפון מיאמי, מול קהל שחור, עם להקת הסקסופוניסט קינג קרטיס, וההופעה הוקלטה. חברת התקליטים RCA שמעה את התוצאה, חשבה שהיא פראית מדי ועלולה לפגוע בתדמית שלו בקרב הקהל הלבן, ושמה אותה במגירה. היא יצאה רק ב־1985, יותר מעשרים שנה אחר כך.''',
'''זה סאם קוק אחר לגמרי: צרוד, מזיע, צועק ומטיף, כמו בכנסייה של ילדותו. הלהקה מנגנת חזק ומהר, בלי הפסקות, והקהל שר, צועק ועונה לו. הלהיטים המתוקים שלו, כמו Cupid ו־Chain Gang, הופכים לחגיגות רועשות, והוא מדבר עם הקהל, מעודד אותו ומוביל אותו כמו מטיף. כבר בדקה הראשונה, ב־Feel It, ברור שזה לא ערב של זמר נעים עם חליפה.''',
'''RCA העדיפה להוציא ב־1964 הופעה אחרת, במועדון Copacabana היוקרתי בניו יורק, מול קהל לבן: מלוטשת, מנומסת ומלאה בשירי ברודווי. כשההופעה ממיאמי יצאה סוף סוף, היא שינתה את הדרך שבה חושבים על קוק: לא רק זמר פופ נעים, אלא אחד מאבות הסול. רבים רואים בה היום את אחד מאלבומי ההופעה החיה הגדולים שהוקלטו אי פעם. קוק עצמו לא זכה לראות את זה: הוא נורה ונהרג בדצמבר 1964, בגיל 33.''',
'''השוו לאלבום 40, ההופעה של ג׳יימס בראון באפולו, שהוקלטה שלושה חודשים קודם: שני מופעים גדולים של המוזיקה השחורה באותה תקופה, ושתי דרכים שונות לגמרי לשלוט בקהל. ושמעו את Bring It On Home to Me בסוף, בווליום גבוה.''',
], [
('Bring It On Home to Me', 'הרגע המרגש ביותר: קוק והקהל שרים יחד, שואלים ועונים, כמו בכנסייה.'),
('Somebody Have Mercy', 'בלוז סוחף שבו קוק מטיף, צועק ומוביל את הקהל לאן שהוא רוצה.'),
('Having a Party', 'סיום של מסיבה אמיתית, עם הקהל ששר יחד את הפזמון ולא רוצה ללכת הביתה.'),
])

add(39, [
'''צ׳רלס מינגוס היה בסיסט ומלחין מבריק, סוער ורגזן, שחלם לכתוב מוזיקה גדולה כמו של גיבורו דיוק אלינגטון (אלבום 6). ב־20 בינואר 1963 הוא נכנס לאולפן עם תזמורת של אחד־עשר נגנים, והקליט לחברת Impulse! יצירה אחת ארוכה בשם "הקדוש השחור והגברת החוטאת", שנכתבה כמוזיקה לבלט. הוא התייחס אליה כל כך ברצינות שאת דברי ההסבר על העטיפה כתב, בין השאר, הפסיכולוג שטיפל בו באותה תקופה.''',
'''המוזיקה עוברת בין בלוז כבד ואיטי, קטעים סוערים וכמעט כאוטיים, צלילים של תזמורת ג׳אז גדולה ואפילו גיטרה קלאסית בנוסח ספרדי, שמנגן ג׳יי ברלינר. הטרומבון נאנח, כלי הנשיפה צועקים יחד, והסקסופון האלט של צ׳רלי מריאנו בוכה, צוחק ומתחנן כמעט כמו קול אנושי. מינגוס גם השתמש באולפן בדרך שכמעט לא הייתה מקובלת בג׳אז של אז: הוא ערך את ההקלטות והוסיף אחר כך קטעי סולו של מריאנו מעל התזמורת. התוצאה נשמעת כמו פסקול של סרט שלא צולם.''',
'''זו אחת היצירות השאפתניות בתולדות הג׳אז, והיא מראה שג׳אז יכול להיות יצירה ארוכה, מתוכננת ומורכבת, ועדיין מלאה ברגש ובאלתור. רבים מחשיבים אותה ליצירה הטובה ביותר של מינגוס ולאחת היצירות החשובות של הג׳אז בכלל. היא השפיעה על מלחיני ג׳אז, על הרוק המתקדם של שנות השבעים ועל כל מי שחיפש לכתוב יצירה שלמה ולא רק שירים קצרים.''',
'''הקשיבו לאלבום ברצף, בפעם אחת ובקול רם, כמו לסרט. ואם אתם רוצים לשמוע עוד יצירה גדולה ושלמה מאותה חברת תקליטים, עברו לאלבום 53, של ג׳ון קולטריין, שיצא שנתיים אחר כך.''',
], [
('Track A – Solo Dancer', 'הפתיחה: נושא איטי ומאיים שמתפתח לתזמורת שלמה, כמו מסך שעולה.'),
('Track B – Duet Solo Dancers', 'דו־שיח בין כלים, רומנטי ועצוב, עם הסקסופון של מריאנו במרכז.'),
('Mode D / E / F – Trio and Group Dancers, Single Solos, Group and Solo Dance', 'החלק הארוך, עם הגיטרה הספרדית, שבו כל הסיפור מגיע לשיא.'),
])

add(40, [
'''ב־1962 ג׳יימס בראון כבר היה כוכב גדול במועדונים של אמריקה השחורה, עם להקה מאומנת כמו צבא וקבוצת הזמרים The Famous Flames. הוא האמין שהקסם שלו נמצא על הבמה, ורצה להקליט אותו. סיד ניית׳ן, הבעלים של חברת King, סירב: מי כבר יקנה תקליט של הופעה, עם שירים שכבר יצאו? בראון לא ויתר, ומימן את ההקלטה מכספו. ב־24 באוקטובר 1962 הוקלטה ההופעה בתיאטרון אפולו בהארלם, הבמה החשובה ביותר של המוזיקה השחורה.''',
'''אין שנייה של מנוחה. אחרי ההצגה של המנחה, "זה זמן הכוכב!", שיר עובר לשיר בלי הפסקה, הלהקה עוצרת ומתחילה לפי תנועת יד של בראון, והקהל, בעיקר הנשים, צועק בכל פעם שהוא מושך מילה או משתתק לרגע. בלב האלבום יש בלדה ארוכה, Lost Someone, שבה בראון מותח את הרגע עוד ועוד, עד שהאולם כולו רותח. זה מופע של שליטה מוחלטת, עם צרחות, דרמה וזיעה, והכול נגמר בפחות מארבעים דקות.''',
'''ניית׳ן טעה. האלבום יצא במאי 1963, התפשט מפה לאוזן, הגיע למקום השני במצעד האלבומים האמריקאי ונשאר בו יותר משנה, ותחנות רדיו השמיעו צד שלם ברצף. הוא הפך את בראון מכוכב של הקהל השחור לכוכב של כל אמריקה, והוא נחשב עד היום לאחד מאלבומי ההופעה החיה הגדולים. המשמעת והקצב של הלהקה כאן הם גם הזרעים של הפאנק, שבראון המציא בשנים שאחרי.''',
'''שמעו את האלבום ברצף, מההצגה ועד Night Train, כמו כרטיס להופעה. ואז השוו לאלבום 38, של סאם קוק, שהוקלט שלושה חודשים אחר כך במיאמי, ולאלבום 54, של בי. בי. קינג, מ־1964.''',
], [
('Introduction to James Brown and The Famous Flames', 'המנחה מציג את "האיש שעובד הכי קשה בשואו ביזנס", והלהקה מתפרצת.'),
('Lost Someone', 'יותר מעשר דקות של בלדה, שבהן בראון והקהל מגיעים יחד לטירוף.'),
('Night Train', 'סיום אינסטרומנטלי מהיר, שבו בראון צועק שמות של ערים ומריץ את הלהקה עד הסוף.'),
])

add(41, [
'''שנה אחרי Jazz Samba (אלבום 33), המפיק קריד טיילור הפגיש באולפן בניו יורק, ב־18 וב־19 במרץ 1963, את סטן גץ עם שניים מהאנשים שהמציאו את הבוסה נובה: הזמר והגיטריסט ז׳ואאו ז׳ילברטו, שהמציא את מקצב הגיטרה המיוחד של הסגנון, והמלחין והפסנתרן אנטוניו קרלוס ז׳ובים, שכתב את רוב השירים. באולפן הייתה גם אשתו של ז׳ילברטו, אסטרוד, שמעולם לא שרה באופן מקצועי. היא ידעה אנגלית, והוחלט לתת לה לשיר בית אחד באנגלית בשני שירים.''',
'''הכול כאן שקט ואינטימי: הגיטרה של ז׳ילברטו בקצב הבוסה נובה, רכה ומתנדנדת, הקול שלו שכמעט לוחש בפורטוגזית, הפסנתר העדין והחסכוני של ז׳ובים, והסקסופון החם של גץ, שעונה להם ומדי פעם תופס את המנגינה. אסטרוד שרה באנגלית בקול פשוט, קצת תמים ובלי שום קישוט, וזה בדיוק הקסם. אין כאן רגע אחד שמרים את הקול: זה אלבום שמדבר בשקט, ובגלל זה מקשיבים לו.''',
'''The Girl from Ipanema, שיר שכתבו ז׳ובים והמשורר ויניסיוס די מוראייס על נערה שעוברת בדרך לים, יצא כסינגל מקוצר, בלי הבית של ז׳ואאו בפורטוגזית, והפך ללהיט עולמי ולאחד השירים המושמעים בהיסטוריה. אסטרוד הפכה בן לילה לכוכבת. האלבום זכה ב־1965 בפרס הגראמי לאלבום השנה, אלבום הג׳אז הראשון שזכה בו, והפך את הבוסה נובה לשפה בינלאומית. עד היום הוא מאלבומי הג׳אז הנמכרים והאהובים ביותר.''',
'''שמעו את Desafinado כאן ואז באלבום 33, ותשמעו מה ההבדל כשהמקצב מגיע ישר מברזיל. ואם התאהבתם בקול של אסטרוד, חכה לכם אלבום משלה, אלבום 76. ז׳ובים חוזר גם באלבום 92, עם פרנק סינטרה.''',
], [
('The Girl from Ipanema', 'השיר על הנערה שהולכת לים, קודם בפורטוגזית של ז׳ואאו ואז באנגלית של אסטרוד. אחד השירים המושמעים בעולם.'),
('Corcovado (Quiet Nights of Quiet Stars)', 'בלדה לילית ושקטה על ריו דה ז׳ניירו, ששמה לקוח מההר שמעל העיר.'),
('Doralice', 'שיר קצבי ושובב, שבו אפשר לשמוע היטב את מקצב הגיטרה של ז׳ילברטו.'),
])

add(42, [
'''באמצע 1964 הביטלס כבר כבשו את אמריקה, ובאביב של אותה שנה הם צילמו את סרטם הראשון, "לילה של יום מפרך", קומדיה בשחור־לבן על יום מטורף בחייהם, בין רכבות, מלונות ומעריצות צורחות. האלבום יצא ביולי 1964, כמה ימים אחרי הבכורה של הסרט. בצד הראשון השירים מהסרט, ובצד השני שירים חדשים שלא נכנסו אליו. ובפעם הראשונה כל השירים באלבום נכתבו בידי לנון ומקרטני, בלי אף שיר של אחרים. לנון כתב את רובם ושר בחלק גדול מהם.''',
'''האלבום נפתח באקורד אחד, מצלצל ומסתורי, שמוזיקאים מתווכחים עליו עד היום: אילו צלילים בדיוק מנגנים בו? ומשם זה רק ממשיך. ג׳ורג׳ הריסון מנגן כאן בגיטרה חשמלית של שנים־עשר מיתרים, והצליל הבהיר והמצלצל שלה נמצא כמעט בכל שיר. לצד רוקנרול מהיר יש בלדות אקוסטיות עדינות, כמו And I Love Her, והרמוניות מתוחכמות של לנון ומקרטני, כמו ב־If I Fell. הכול קצר, חד ומלא ביטחון.''',
'''A Hard Day’s Night הראה שהביטלס הם כותבי שירים מהשורה הראשונה, ולא רק תופעה של מעריצות צורחות. הוא קבע את הסטנדרט לאלבום פופ שכולו נכתב בידי הלהקה עצמה, רעיון שנשמע מובן מאליו היום אבל היה חדש אז. והגיטרה של הריסון? צעיר אמריקאי בשם רוג׳ר מקגווין ראה את הסרט, קנה גיטרה דומה, והקים את The Byrds (אלבום 57).''',
'''השוו לאלבום 35: פחות משנה עברה, ואין כבר צורך בשירים של אחרים. ואחר כך שמעו את Mr. Tambourine Man של הבירדס באלבום 57, ונסו לזהות איפה הגיטרה של הריסון ממשיכה לצלצל.''',
], [
('A Hard Day’s Night', 'האקורד הפותח הוא אולי המפורסם ברוק. אחריו שיר מלא אנרגיה על עבודה קשה ואהבה שמחכה בבית.'),
('If I Fell', 'בלדה עם הרמוניה צמודה של לנון ומקרטני, עדינה ומורכבת יותר ממה שנשמע בהתחלה.'),
('Things We Said Today', 'שיר של מקרטני, מינורי ומלנכולי, על אהבה שחושבת כבר עכשיו איך תיזכר בעתיד.'),
])

add(43, [
'''ז׳אק ברל, זמר וכותב מבלגיה, היה אחד מגדולי השאנסון, השיר הצרפתי שבו המילים חשובות לא פחות מהמנגינה. הוא עבר לפריז בשנות החמישים, התחיל מהופעות במועדונים קטנים, ועד אמצע שנות השישים הפך לכוכב ענק. ב־16 וב־17 באוקטובר 1964 הוא הופיע באולם אולימפיה בפריז, הבמה החשובה ביותר לזמרים דוברי צרפתית, וההופעות הוקלטו. התקליט יצא כמה ימים אחר כך. כעבור שנתיים ברל הודיע שהוא מפסיק להופיע, בשיא הצלחתו, ועבר לתיאטרון ולקולנוע.''',
'''ברל לא רק שר. הוא משחק כל שיר כמו מחזה קצר: מזיע, צועק, לוחש, מחקה דמויות ומשנה את הקול. התזמורת מלווה אותו בדרמה, והשירים עוברים בין אירוניה, כעס, הומור ועצב עמוק: מלחים שיכורים בנמל, זקנים שמחכים למוות, בורגנים זחוחים, בחור ביישן עם ממתקים. גם בלי להבין מילה בצרפתית, אפשר להרגיש כל רגע, ובעיקר לשמוע את הקהל, שנשבה בקסם שלו.''',
'''Amsterdam, אחד משיריו המפורסמים, מעולם לא הוקלט על ידו באולפן, וההקלטה הזאת היא הגרסה היחידה שלו. ברל השפיע על זמרים רבים מחוץ לעולם הצרפתי: סקוט ווקר ודייוויד בואי שרו את Amsterdam באנגלית, ושירים אחרים שלו תורגמו לעשרות שפות, גם לעברית. הוא הראה שזמר יכול להיות גם משורר וגם שחקן, ושהופעה חיה יכולה להיות תיאטרון שלם.''',
'''אם אפשר, חפשו את ההופעות של ברל בווידאו: לראות אותו שר חשוב כמעט כמו לשמוע. ואם לא, קראו תרגום של שיר אחד או שניים לפני ההאזנה, והתחילו מ־Amsterdam.''',
], [
('Amsterdam', 'שיר על מלחים בנמל של אמסטרדם, שנבנה לאט עד לסערה. אחד מרגעי ההופעה הגדולים.'),
('Le Plat Pays', '"הארץ השטוחה", שיר אהבה שקט ויפה לבלגיה, ארץ הגשם, הרוח והשמיים הנמוכים.'),
('Les Bonbons', 'שיר קומי על בחור ביישן שמביא ממתקים לאהובתו. הקהל צוחק לאורך כל הדרך.'),
])

add(44, [
'''סולומון בורק מפילדלפיה היה מטיף בכנסייה כבר כילד, וכונה "הילד המטיף". כנער הקליט שירי גוספל, וב־1960, זמן קצר אחרי שריי צ׳רלס עזב את חברת Atlantic, חתם בה בורק. שם התחיל לשלב גוספל, ריתם אנד בלוז וקאנטרי, והלהיט הראשון שלו, ב־1961, היה בכלל שיר קאנטרי. Rock ’n Soul, שיצא ביולי 1964, אוסף את הלהיטים שלו מהשנים ההן, ושמו לקוח מהתואר שהוא עצמו אימץ בגאווה: "מלך הרוק והסול".''',
'''הקול של בורק עצום, חם ועמוק, והוא שר כל שיר כמו דרשה: לפעמים מדבר אל המאזין, לפעמים מתחנן, ולפעמים פשוט פורץ. יש כאן בלדות קורעות לב, שירי קאנטרי שהופכים לסול, כמו He’ll Have to Go של ג׳ים ריבס, וקטעים קצביים עם מקהלה, כלי נשיפה ופסנתר. המפיק ברט ברנס, שגם כתב חלק מהשירים, נתן לכל אחד מהם צליל עשיר ודרמטי, בלי לכסות את הקול.''',
'''שבעה מהשירים באלבום נכנסו למצעד הסינגלים האמריקאי. בורק היה מהאמנים שהמציאו את הסול בתחילת שנות השישים, לצד ריי צ׳רלס וסאם קוק, אבל הוא אף פעם לא הפך לכוכב גדול כמותם, ולכן שמו פחות מוכר. מוזיקאים דווקא הכירו אותו היטב: הרולינג סטונס הקליטו כמה משיריו, וזמרי סול רבים למדו ממנו איך לשיר בלדה. Cry to Me זכה לחיים חדשים ב־1987, בסרט "ריקוד מושחת".''',
'''השוו את Just Out of Reach ואת He’ll Have to Go לריי צ׳רלס באלבום 31: שני זמרים שחורים שלקחו קאנטרי לבן והפכו אותו לסול, כל אחד בדרכו.''',
], [
('Cry to Me', 'בלדה שכתב ברט ברנס, מלאה בכאב ובתקווה. הקשיבו לרגע שבו בורק מרים את הקול.'),
('Just Out of Reach (Of My Two Empty Arms)', 'שיר קאנטרי שבורק הפך לסול, והלהיט הראשון שלו.'),
('If You Need Me', 'בלדת נשמה איטית שבה בורק מדבר ושר כמו מטיף.'),
])

add(45, [
'''מרי או׳בריאן מלונדון גדלה בבית אוהב מוזיקה, ובתחילת שנות השישים שרה עם אחיה בשלישיית פולק־פופ מצליחה בשם The Springfields. היא אימצה את השם דאסטי ספרינגפילד, ובסוף 1963 יצאה לקריירת סולו עם הלהיט I Only Want to Be with You. באביב 1964 יצא אלבום הבכורה שלה, שהגיע למקום השישי במצעד הבריטי. באותה תקופה היא גם הפכה לדמות המוכרת עם השיער הבלונדיני הנפוח והאיפור הכבד סביב העיניים.''',
'''דאסטי שרה בקול עמוק, חם וקצת עצוב, עם הרבה נשמה, והיא אהבה בעיקר מוזיקה אמריקאית. האלבום מלא בשירים של הכותבים האמריקאים הגדולים של אז, כמו ברט בכרך והאל דייוויד וקרול קינג, ובגרסאות ללהיטים של להקות בנות אמריקאיות, כמו The Shirelles. העיבודים גדולים, עם כלי מיתר, כלי נשיפה ומקהלות, אבל הקול תמיד במרכז: לפעמים לוחש ושבור, ולפעמים מתפוצץ.''',
'''ספרינגפילד הייתה מהזמרות הלבנות הראשונות בבריטניה ששרו סול באמת, והיא ניצלה את הפרסום שלה כדי לקדם את המוזיקה השחורה האמריקאית: ב־1965 היא הגישה בטלוויזיה הבריטית תוכנית מיוחדת לאמני מוטאון, שרבים מהם היו אז כמעט לא מוכרים שם. בסוף 1964 היא גם גורשה מדרום אפריקה, אחרי שהתעקשה להופיע רק מול קהל מעורב, שחורים ולבנים יחד. האלבום הזה הוא הצעד הראשון בדרך שהובילה אותה, חמש שנים אחר כך, לאלבום המופת שלה Dusty in Memphis.''',
'''הרבה מהשירים כאן הם גרסאות ללהיטים אמריקאיים. נסו לשמוע את Will You Love Me Tomorrow ואת Anyone Who Had a Heart גם בגרסאות המקוריות, של The Shirelles ושל דיון וורוויק, ותשמעו מה דאסטי הוסיפה משלה.''',
], [
('Anyone Who Had a Heart', 'שיר של בכרך ודייוויד, מלא בעצב ובמעברים הרמוניים מפתיעים.'),
('You Don’t Own Me', 'שיר על אישה שמסרבת להיות רכוש של אף אחד, מושר בגאווה ובשקט.'),
('Will You Love Me Tomorrow', 'השיר של קרול קינג: שאלה כנה ושבירה על הבוקר שאחרי.'),
])

add(46, [
'''הרולינג סטונס התחילו ב־1962 כחבורה של צעירים מלונדון שהיו מאוהבים בבלוז אמריקאי. את השם הם לקחו משיר של מאדי ווטרס (אלבום 29), והמייסד שלהם, בריאן ג׳ונס, היה אולי המעריץ המושבע מכולם. המנהל הצעיר שלהם, אנדרו לוג אולדהם, החליט להציג אותם כ"ילדים הרעים", ההפך הגמור מהביטלס המחייכים. אלבום הבכורה שלהם יצא בבריטניה באפריל 1964, הדיח את With the Beatles (אלבום 35) מהמקום הראשון, ונשאר שם שנים־עשר שבועות. באמריקה הוא יצא חודש אחר כך, עם שם משנה: England’s Newest Hit Makers.''',
'''רוב האלבום הוא גרסאות לשירי בלוז, ריתם אנד בלוז ורוקנרול של האמנים שהם הכי אהבו: מאדי ווטרס, צ׳אק ברי, סלים הרפו, באדי הולי ואפילו מרווין גיי. זה נשמע מחוספס, מהיר ומלוכלך, עם גיטרות חשמליות, המפוחית של בריאן ג׳ונס, התופים היבשים של צ׳רלי ווטס והקול המתגרה של מיק ג׳אגר. הכול הוקלט מהר ובזול, וזה בדיוק מה שנותן לו את האנרגיה.''',
'''הסטונס החזירו לאמריקה הלבנה את הבלוז השחור שלה, בגרסה צעירה ומרדנית, והרבה צעירים אמריקאים שמעו דרכם לראשונה את שמות המוזיקאים שהם העריצו. באלבום הזה יש רק שיר אחד שכתבו ג׳אגר וקית׳ ריצ׳רדס, Tell Me, אבל מכאן הם התחילו לכתוב שירים משלהם, והפכו לאחת מלהקות הרוק הגדולות בהיסטוריה. כאן אפשר לשמוע את השורשים שלהם בבירור.''',
'''שמעו את I Just Want to Make Love to You כאן, ואז חזרו לאלבום 29 ושמעו את מאדי ווטרס שר שירים מאותו עולם, ארבע שנים קודם. ואחר כך קפצו לאלבום 70, ותשמעו איך נשמעים הסטונס כשכל השירים כבר שלהם.''',
], [
('Not Fade Away', 'השיר של באדי הולי (אלבום 8) בגרסה עם מקצב של בו דידלי ומפוחית, מחוספס הרבה יותר.'),
('I’m a King Bee', 'בלוז של סלים הרפו, איטי וחושני, שהסטונס מנגנים בכבוד רב.'),
('Tell Me', 'השיר היחיד באלבום שכתבו ג׳אגר וריצ׳רדס. בלדה שמרמזת על מה שיבוא.'),
])

add(47, [
'''באק אוונס נולד בטקסס למשפחה של עובדי חקלאות עניים, והגיע בתחילת שנות החמישים לבייקרספילד שבקליפורניה, עיר של שדות נפט ושל מהגרים שברחו מהבצורת באוקלהומה ובטקסס. בבארים הרועשים של העיר הוא ניגן כל לילה, ושם, עם הלהקה שלו, The Buckaroos, הוא פיתח סגנון קאנטרי משלו, חשמלי וקשוח. באמצע שנות השישים הוא כבר היה אחד מכוכבי הקאנטרי הגדולים באמריקה, עם להיט אחרי להיט במקום הראשון. I’ve Got a Tiger by the Tail יצא ב־1965, ושיר הנושא שלו היה עוד להיט כזה.''',
'''"הצליל של בייקרספילד" הוא ההפך מהקאנטרי המלוטש של נאשוויל באותן שנים, עם כלי מיתר ומקהלות רכות. כאן יש גיטרות חשמליות חדות ומצלצלות, תופים חזקים, גיטרת פדל סטיל, והרמוניות צמודות של אוונס עם הגיטריסט והכנר דון ריץ׳, יד ימינו. השירים קצרים, קצביים ולפעמים מצחיקים, והכול נשמע כאילו נוגן בבר מלא אנשים שרוצים לרקוד. זה קאנטרי עם אנרגיה של רוקנרול.''',
'''אוונס הוכיח שהקאנטרי יכול להישאר גולמי ופשוט, ועדיין להצליח. הוא השפיע על מרל הגארד (אלבום 99), על הקאנטרי־רוק של סוף שנות השישים ושנות השבעים, ועל זמרים כמו דווייט יואקם, שעבד איתו שנים אחר כך. הביטלס הקליטו ב־1965 את השיר שלו Act Naturally, ורינגו שר אותו. מאוחר יותר הוא הפך לפנים מוכרות בטלוויזיה האמריקאית, אבל רבים זוכרים אותו בעיקר בזכות התקליטים מהתקופה הזאת.''',
'''שמעו את Cryin’ Time כאן, ואחר כך את הגרסה של ריי צ׳רלס, שהפך אותו ללהיט זמן קצר אחר כך. ואם תרצו להבין מה בייקרספילד מרד בו, חזרו לריי פרייס באלבום 34.''',
], [
('I’ve Got a Tiger by the Tail', 'שיר הנושא, להיט שהגיע למקום הראשון, עם קצב קופצני ומילים מצחיקות על אהבה שקשה להחזיק.'),
('Cryin’ Time', 'בלדה עצובה של אוונס, שריי צ׳רלס הפך בעצמו ללהיט.'),
('Memphis', 'השיר של צ׳אק ברי בגרסת בייקרספילד, עם הגיטרה החדה של דון ריץ׳.'),
])

add(48, [
'''ג׳רי לי לואיס מלואיזיאנה היה אחד מכוכבי הרוקנרול הגדולים של שנות החמישים, עם Whole Lotta Shakin’ Goin’ On ו־Great Balls of Fire, והופעות פרועות שבהן בעט בכיסא ודפק על הפסנתר בידיים וברגליים. ב־1958, בסיבוב הופעות באנגליה, התגלה שהתחתן עם בת דודתו בת ה־13, והקריירה שלו קרסה בבת אחת. שש שנים אחר כך הוא עדיין הופיע בכל מקום שהסכים לקבל אותו. ב־5 באפריל 1964 הוא עלה לבמה במועדון Star-Club בהמבורג, שבו הביטלס ניגנו לילות שלמים כמה שנים קודם, וההופעה הוקלטה.''',
'''זה רוקנרול במהירות מטורפת. ג׳רי לי דופק על הפסנתר, צועק, מאיץ את הקצב, ומושך אחריו את הלהקה הבריטית שליוותה אותו, The Nashville Teens, שבקושי עומדת בקצב. הקהל הגרמני צועק את שמו בין השירים. הוא שר גם להיטים של אחרים, כמו What’d I Say של ריי צ׳רלס ו־Long Tall Sally של ליטל ריצ׳רד, ומשאיר אותם מתנשפים. אין כאן רגע של מנוחה או של זהירות, ואפילו הבלדה Your Cheatin’ Heart נשמעת כמו אתגר.''',
'''האלבום יצא ב־1964 באירופה בלבד, ובארצות הברית הוא יצא רשמית רק ב־1980. בינתיים הוא עבר מיד ליד בין אספנים, והמוניטין שלו רק גדל. רבים מחשיבים אותו לאלבום הרוקנרול החי הגדול ביותר, ויש מבקרים שקראו לו "הפראי ביותר". הוא מראה את כל העוצמה של הרוקנרול המקורי, ומוכיח שהזעם והשמחה של שנות החמישים לא נעלמו, גם כשהאופנה כבר עברה לביטלס.''',
'''שמעו את Good Golly, Miss Molly ואת Long Tall Sally כאן, ואז את המקור של ליטל ריצ׳רד באלבום 14. ותנו לזה ווליום גבוה: זה לא אלבום לרקע.''',
], [
('Whole Lotta Shakin’ Goin’ On', 'הלהיט הגדול, בגרסה ארוכה ופרועה עוד יותר מהמקור.'),
('Great Balls of Fire', 'פחות משלוש דקות של אש על הפסנתר, מהיר מכדי להאמין.'),
('What’d I Say, Part 1', 'השיר של ריי צ׳רלס הופך כאן לחגיגה, והקהל עונה לכל קריאה.'),
])

add(49, [
'''הסוניקס היו חמישה נערים מטקומה, עיר נמל ליד סיאטל, שניגנו רוקנרול באולמות ריקודים ובמסיבות של תיכונים. הזמר והקלידן ג׳רי רוזלי, האחים לארי ואנדי פאריפה בגיטרה ובבס, רוב לינד בסקסופון ובוב בנט בתופים. ב־1965 הם הקליטו את אלבום הבכורה שלהם לחברת תקליטים מקומית וקטנה, באולפן בסיאטל, על מכשיר הקלטה של שני ערוצים ועם מיקרופון אחד בלבד מעל כל ערכת התופים.''',
'''זה נשמע כאילו הרמקולים עומדים להתפוצץ: גיטרות מעוותות, תופים שמכים חזק מדי, סקסופון צורח, ורוזלי שצורח במלוא הגרון, כאילו הוא לא יצטרך את הקול שלו מחר. השירים המקוריים עוסקים במכשפות, במטורפים ובשתיית רעל, ובגרסאות לשירי רוקנרול מוכרים, כמו Roll Over Beethoven ו־Money, הם נשמעים זועמים ומצחיקים בו בזמן. אין כאן שום עדינות, וזה בדיוק העניין.''',
'''באותה תקופה הסוניקס היו מוכרים בעיקר בצפון־מערב ארצות הברית, ולא הפכו לכוכבים. אבל כיום רבים רואים בהם מאבות הפאנק: הסאונד הגולמי שלהם, שנוצר בלי כסף ובלי נימוס, השפיע על להקות פאנק בשנות השבעים ועל להקות הגראנג׳ של סיאטל עשרים שנה אחר כך. הם גם הוכיחו שאפשר להקליט אלבום חשוב בלי אולפן גדול ובלי מפיק מפורסם.''',
'''שמעו את Money כאן, ואז את הגרסה של הביטלס באלבום 35: אותו שיר, שתי להקות צעירות וצועקות, ותוצאות שונות מאוד. ואם אהבתם את הרעש, המשיכו לאלבום 72, של 13th Floor Elevators.''',
], [
('The Witch', 'השיר המפורסם שלהם, על בחורה מסוכנת, עם צעקות וגיטרה מרוסקת.'),
('Psycho', 'אחד השירים הפרועים ביותר של אמצע שנות השישים. אפשר לשמוע פה את הפאנק מתחיל.'),
('Strychnine', 'שיר על שתיית רעל, מושר בחיוך מרושע. כמה להקות פאנק הקליטו אותו מחדש.'),
])

add(50, [
'''בתחילת 1965 בוב דילן כבר היה גיבור הפולק והמחאה, "הקול של דור" (אלבום 36), אבל הוא התחיל להרגיש כלוא בתדמית הזאת. הוא שמע את הביטלס, קרא הרבה שירה, ורצה לכתוב אחרת. באמצע ינואר 1965, בשלושה ימים בלבד, הוא הקליט את האלבום החמישי שלו, שיצא במרץ. בו הוא עשה את הצעד שעורר סערה: בצד אחד של התקליט הוא מנגן עם להקה חשמלית, ובצד השני הוא כמעט לבד עם גיטרה אקוסטית.''',
'''הצד החשמלי קופצני, מצחיק ומלא אנרגיה של רוקנרול ובלוז, עם מילים סוריאליסטיות שנשפכות מהר: שוטרים, חוואים, חלומות מטורפים על גילוי אמריקה. הצד האקוסטי הוא שירה של ממש: ארוכה, חלומית וחשוכה, עם שירים שנשמעים כמו מסע בתוך הראש של אדם אחר. It’s Alright, Ma הוא ביקורת חריפה על חברה שלמה, ו־It’s All Over Now, Baby Blue הוא פרידה, אולי גם מהקהל הישן שלו.''',
'''Bringing It All Back Home פתח את עידן הפולק־רוק. גרסת הבירדס ל־Mr. Tambourine Man (אלבום 57) הגיעה למקום הראשון בתוך חודשים, ובקיץ דילן עלה עם להקה חשמלית בפסטיבל הפולק של ניופורט ועורר שערורייה בקרב מעריצים שהרגישו נבגדים. המילים שלו שינו את מה ששיר רוק יכול להיות: פתאום מותר היה לכתוב בו שירה.''',
'''שמעו את Mr. Tambourine Man כאן, ארוך, אקוסטי ומלא בתים, ואז את הגרסה הקצרה והחשמלית של הבירדס באלבום 57. אחר כך המשיכו לאלבום 58, שיצא חמישה חודשים בלבד אחרי זה.''',
], [
('Subterranean Homesick Blues', 'זרם מהיר של מילים על קצב רוקנרול, כמעט כמו ראפ לפני הראפ.'),
('Mr. Tambourine Man', 'שיר על חלום, על מוזיקה ועל חופש, שהבירדס הפכו ללהיט של פולק־רוק.'),
('It’s Alright, Ma (I’m Only Bleeding)', 'אחד השירים הארוכים והחריפים של דילן, ביקורת על חברה שלמה.'),
])

add(51, [
'''אוטיס רדינג גדל במייקון שבג׳ורג׳יה, והגיע לחברת Stax בממפיס כמעט במקרה: ב־1962 הוא הסיע לאולפן זמר אחר, ובסוף היום, כשנשארו כמה דקות, ביקש לשיר שיר משלו. תוך שלוש שנים הוא כבר היה אחד מכוכבי הסול הגדולים. את Otis Blue הקליט בקיץ 1965, בתוך יממה אחת: מהבוקר של 9 ביולי ועד הצהריים של למחרת, עם הפסקה בלילה, כי נגני הלהקה היו צריכים ללכת לנגן בהופעות שלהם במועדונים של ממפיס. הם חזרו לאולפן וסיימו את האלבום.''',
'''מאחוריו מנגנת להקת הבית של Stax, בוקר טי והאם.ג׳י.ס (אלבום 32), עם אייזק הייז בפסנתר וקבוצת כלי נשיפה חזקה. רדינג שר סול שנשמע כמו שיחה עם הלב, מלא בבטן ובזיעה. יש כאן שלושה שירים של סאם קוק (אלבום 38), שנהרג כמה חודשים קודם, שירים משלו, ושירים של אחרים שהוא הופך לשלו לגמרי: Rock Me Baby של בי. בי. קינג, My Girl של הטמפטיישנס, ואפילו Satisfaction של הרולינג סטונס, שהוא שר בפראות ובחופש גמור, בלי להקפיד על המילים.''',
'''Otis Blue נחשב לאחד מאלבומי הסול הגדולים, ולאחד מאלבומי הסול הראשונים שעובדים כיצירה שלמה, ולא רק כאוסף סינגלים. כאן נולד Respect, שיר שאריתה פרנקלין תהפוך ב־1967 להמנון. רדינג עצמו לא זכה לראות את כל מה שבא אחרי: בדצמבר 1967 הוא נהרג בהתרסקות מטוס, בגיל 26.''',
'''השוו את A Change Is Gonna Come כאן לסאם קוק באלבום 38, ואת Down in the Valley, שיר שהקליט קודם סולומון בורק (אלבום 44), לבלדות של בורק שם. שלושה זמרים, ושלושה סוגים של סול.''',
], [
('Respect', 'השיר המקורי, שלימים אריתה פרנקלין הפכה להמנון. כאן הוא קצבי, דוחק ומלא כלי נשיפה.'),
('A Change Is Gonna Come', 'הגרסה של רדינג לשיר של סאם קוק, איטית ורוויית כאב.'),
("I've Been Loving You Too Long (To Stop Now)", 'אחת הבלדות הגדולות של הסול. הקשיבו איך הקול שלו נשבר בכוונה לקראת הסוף.'),
])

add(52, [
'''בסוף 1964 הביץ׳ בויז היו להקת הפופ האמריקאית הגדולה ביותר, עם שירים על גלישה, מכוניות וקיץ. אבל בריאן וילסון, הבכור בין שלושת האחים בלהקה, שכתב, עיבד והפיק כמעט הכול, קרס תחת העומס. בדצמבר 1964 הוא עבר התקף חרדה בטיסה להופעה, והחליט להפסיק להופיע. מעכשיו הלהקה יוצאת לסיבובים בלעדיו, והוא נשאר בלוס אנג׳לס, באולפן, לכתוב ולהקליט. The Beach Boys Today!, שיצא במרץ 1965, הוא האלבום הראשון שנולד מההחלטה הזאת.''',
'''הצד הראשון של התקליט מלא קצב ושמחה, עם הרמוניות קוליות מושלמות, כולל Help Me, Rhonda, שבגרסה אחרת, מוקלטת מחדש, הגיע למקום הראשון במצעד האמריקאי. הצד השני שקט ואישי בהרבה: סדרה של בלדות על אהבה, ספקות וגעגוע, כמו Please Let Me Wonder ו־She Knows Me Too Well, עם עיבודים עשירים שבריאן בנה בהשראת פיל ספקטור (אלבום 37). ובסוף, כבדיחה, יש קטע של שיחה מוקלטת באולפן.''',
'''זה המקום שבו אפשר לשמוע את המעבר מלהקת פופ עליזה ליוצרים רציניים. השירים בצד השני מדברים על חרדה, על התבגרות ועל רגשות מסובכים, דברים שלא ציפו לשמוע מהביץ׳ בויז. רבים רואים בו את הצעד הראשון בדרך אל Pet Sounds (אלבום 61), שיצא שנה אחר כך.''',
'''שמעו את הצד השני ברצף, מ־Please Let Me Wonder ועד In the Back of My Mind, כמו יצירה אחת קצרה. ואז עברו ישר לאלבום 61, ותשמעו לאן זה הוביל.''',
], [
('Help Me, Rhonda', 'הלהיט הגדול של האלבום, עם הרמוניות קוליות ששווה להקשיב להן בקשב.'),
('Please Let Me Wonder', 'בלדה רכה ומדויקת שכבר נשמעת כמו Pet Sounds.'),
('When I Grow Up (To Be a Man)', 'שיר על החשש מלהתבגר, כתוב בכנות מפתיעה, עם צ׳מבלו מקפץ.'),
])

add(53, [
'''ב־1957 ג׳ון קולטריין נגמל מהרואין ומאלכוהול, ולדבריו עבר באותה שנה התעוררות רוחנית. באותן שנים הוא הפך לאחד מהסקסופוניסטים החשובים בעולם, בין השאר בלהקה של מיילס דייוויס (אלבום 21). שבע שנים אחר כך, ב־9 בדצמבר 1964, הוא נכנס לאולפן בניו ג׳רזי עם הרביעייה הקלאסית שלו, מקוי טיינר בפסנתר, ג׳ימי גאריסון בבס ואלווין ג׳ונס בתופים, והקליט בערב אחד יצירה בארבעה חלקים שהקדיש לאלוהים. בחוברת האלבום הוא כתב מכתב אישי לקוראים, ושיר תפילה משלו.''',
'''A Love Supreme היא תפילה במוזיקה. היא נפתחת בגונג, והבס מנגן מוטיב קצר של ארבעה צלילים שחוזר שוב ושוב, כמו מנטרה, עד שקולטריין מתחיל לשיר אותו במילים "A love supreme". משם היא עוברת לקטעים סוערים ואינטנסיביים, עם סולו תופים וסקסופון שבוער, ונגמרת ב־Psalm, שבו קולטריין "קורא" בסקסופון את שיר התפילה שכתב, הברה אחרי הברה, בלי מילים.''',
'''האלבום יצא בתחילת 1965 ומכר עד 1970 בערך חצי מיליון עותקים, פי כמה מאלבומי ג׳אז רגילים של אותה תקופה. זה אחד הרגעים שבהם הג׳אז הפך במפורש למוזיקה רוחנית, והוא השפיע על דורות של מוזיקאים בג׳אז, ברוק ובמוזיקת העולם, מקרלוס סנטנה ועד להקות רוק ניסיוניות. קולטריין נפטר ביולי 1967, בגיל 40.''',
'''הקשיבו ברצף, בפעם אחת ובשקט, כמו לתפילה. ואחר כך חזרו ל־So What באלבום 21 ושמעו את קולטריין שש שנים קודם, עוד לפני שהסקסופון שלו התחיל "לדבר".''',
], [
('Part I — Acknowledgement', 'המוטיב של ארבעה צלילים שעובר בין המפתחות, עד שהוא הופך לשירה.'),
('Part III — Pursuance', 'החלק המהיר והסוער, עם סולו תופים של אלווין ג׳ונס ונגינה בוערת של קולטריין.'),
('Part IV — Psalm', 'סיום איטי ומדיטטיבי: הסקסופון "שר" את מילות התפילה שקולטריין כתב.'),
])

add(54, [
'''ריילי בי. קינג נולד במיסיסיפי למשפחה של עובדי כותנה, והתחיל לנגן ברחובות. בסוף שנות הארבעים הגיע לממפיס, עבד כתקליטן ברדיו וכונה "Blues Boy", ומכאן השם בי. בי. הגיטרה שלו נקראת לוסיל: לפי הסיפור שאהב לספר, פעם פרצה שריפה באולם ריקודים שבו ניגן, אחרי שני גברים רבו על אישה בשם לוסיל, והוא רץ חזרה לתוך הבניין הבוער כדי להציל את הגיטרה. ב־21 בנובמבר 1964 הוא הופיע בתיאטרון ריגל בשיקגו, מול קהל שחור שהכיר כל מילה, וההופעה הוקלטה.''',
'''מהרגע הראשון הקהל צועק, מוחא כפיים ומגיב לכל תו. קינג כמעט אף פעם לא שר ומנגן בו זמנית: הוא שר שורה, ואז לוסיל עונה לו, בכמה צלילים מדויקים עם רטט עדין, כמו קול שני. מאחוריו מנגנת להקה עם כלי נשיפה, והוא מדבר עם הקהל, מתלוצץ ומספר סיפורים בין השירים. התקליט קצר וחם, וכל שיר בו נשמע כמו שיחה בין חברים ותיקים.''',
'''באותה תקופה קינג הופיע מאות פעמים בשנה, כמעט רק מול קהל שחור. Live at the Regal נחשב לאחד מתקליטי ההופעה החיה הגדולים ביותר, והוא השפיע על דור שלם של גיטריסטים צעירים, ביניהם אריק קלפטון, שלמדו ממנו שלפעמים תו אחד נכון שווה יותר מעשרה מהירים. כמה שנים אחר כך הם החזירו את הטובה: הם סיפרו עליו לקהל הלבן והצעיר, וקינג התחיל להופיע גם באולמות רוק גדולים.''',
'''הקשיבו רק לגיטרה בשיר אחד, למשל Sweet Little Angel, וספרו כמה מעט צלילים הוא מנגן. ואחר כך עברו לאלבום 73, ותשמעו את אריק קלפטון הצעיר מנסה ללכת בדרך הזאת.''',
], [
('Everyday I Have the Blues', 'הפתיחה החמה, והלהקה נכנסת בתנופה ובי. בי. מתחיל לשיר.'),
('How Blue Can You Get?', 'שיר על אהבה מאכזבת, עם שורה מצחיקה שהקהל מחכה לה ומתפוצץ כשהיא מגיעה.'),
('Sweet Little Angel', 'סולו גיטרה שמתכתב עם הקול, והקהל מתלהב מכל תו.'),
])

add(55, [
'''בסוף 1965 הביטלס היו בשיא הפופולריות, אבל כבר נמאס להם להיות להקת להיטים. חברת התקליטים רצתה אלבום חדש לחג המולד, והם הקליטו את Rubber Soul בפחות מחודש, בין אמצע אוקטובר לאמצע נובמבר, ובכל זאת הוא נשמע כמו להקה שיש לה פתאום משהו אישי לספר. הוא יצא ב־3 בדצמבר 1965, באותו יום שבו יצא גם אלבום הבכורה של The Who (אלבום 59). השם הוא בדיחה: "נשמה מגומי", בהשראת מה שאמרו מוזיקאים שחורים על זמרי סול לבנים.''',
'''הגיטרות כאן אקוסטיות יותר, והצלילים מפתיעים: הסיטאר ההודי של ג׳ורג׳ הריסון ב־Norwegian Wood, מהפעמים הראשונות שהכלי הזה נשמע בשיר פופ מערבי, סולו "צ׳מבלו" ב־In My Life, שהוא בעצם פסנתר שהמפיק ג׳ורג׳ מרטין ניגן לאט והאיץ אחר כך, ושיר בצרפתית, Michelle. גם המילים השתנו: לנון כותב על עצמו ב־Nowhere Man, ומסתכל אחורה על החיים שלו ב־In My Life. בגרסה הבריטית, שאותה תשמעו כאן, יש ארבעה־עשר שירים.''',
'''האלבום סימן את המעבר של הביטלס מלהקת סינגלים ליוצרים שמתייחסים לאלבום כאל יצירה שלמה. בריאן וילסון מהביץ׳ בויז שמע אותו, התרגש, והחליט לעשות אלבום שיהיה טוב עוד יותר. התוצאה הייתה Pet Sounds (אלבום 61), והביטלס מצדם המשיכו משם ל־Revolver (אלבום 60).''',
'''שמעו את In My Life, ואז חזרו לשיר הראשון באלבום 42, שיצא שנה וחצי קודם: אותה להקה, אבל עכשיו היא מסתכלת פנימה. והמשיכו ברצף: 55, 61, 60.''',
], [
('Norwegian Wood (This Bird Has Flown)', 'סיטאר בשיר פופ, וסיפור מסתורי על רומן שלא קרה.'),
('In My Life', 'נוסטלגיה בלי סנטימנטליות, ואחד השירים האהובים של הלהקה. הקשיבו לסולו באמצע.'),
('Nowhere Man', 'שיר על אדם בלי כיוון, שלנון כתב, לדבריו, על עצמו, אחרי לילה שבו לא הצליח לכתוב.'),
])

add(56, [
'''ברט ג׳אנש גדל באדינבורו שבסקוטלנד, ובתחילת שנות השישים נדד בין מועדוני פולק, ישן על ספות של חברים ולמד גיטרה מכל מי שהסכים ללמד. ב־1964 הגיע ללונדון. את אלבום הבכורה שלו הקליט בדירה של המפיק ביל לידר, יושב על קצה המיטה עם גיטרה שאולה, מול מכשיר הקלטה ביתי. ההקלטות נמכרו לחברת תקליטים קטנה תמורת מאה לירות שטרלינג, והאלבום, שיצא באפריל 1965, מכר בסוף יותר ממאה אלף עותקים.''',
'''רק גיטרה אקוסטית וקול שקט, עם מבטא סקוטי. אבל הנגינה של ג׳אנש מורכבת להפליא: הוא מנגן בס, מנגינה וקצב בו זמנית, בשילוב של פולק בריטי, בלוז אמריקאי ומעט ג׳אז, וזה נשמע קליל. בין השירים יש Needle of Death, שיר על חבר שמת ממנת יתר של הרואין, שנכתב בלי שום הטפה, רק בעצב. ויש קטעים אינסטרומנטליים כמו Angie, יצירה של הגיטריסט דייבי גרהם שכל נגן פולק בבריטניה ניסה אז ללמוד.''',
'''הנגינה של ג׳אנש השפיעה על גיטריסטים רבים: ג׳ימי פייג׳ מלד זפלין, ניל יאנג, ג׳וני מאר מהסמית׳ס ורבים אחרים סיפרו כמה למדו ממנו. הוא המשיך ללהקת הפולק Pentangle, והפך לאחד מאבות הגיטרה האקוסטית המודרנית. זה אלבום שקט ולא ראוותני, שאפשר לשים ברקע ולגלות אחרי כמה שירים שהפסקתם לעשות כל דבר אחר.''',
'''הקשיבו עם אוזניות, ונסו לעקוב אחרי הבס שהאגודל שלו מנגן, בזמן ששאר האצבעות מנגנות את המנגינה. ואם Angie מוכר לכם, אולי שמעתם אותו אצל פול סיימון, שהופיע באותן שנים במועדוני הפולק של אנגליה והקליט אותו בעצמו.''',
], [
('Needle of Death', 'שיר עצוב וקצר על חבר שמת, שנשמע כמעט כמו תפילה.'),
('Angie', 'קטע גיטרה אינסטרומנטלי מפורסם, מהיר ועדין, שכל גיטריסט פולק רצה לנגן.'),
('Strolling Down the Highway', 'פתיחה קצבית ומלאת חיים, עם נגינת גיטרה שלא נחה לרגע.'),
])

add(57, [
'''הבירדס התחילו ב־1964 בלוס אנג׳לס: חמישה צעירים שהגיעו מהפולק והתאהבו בביטלס. רוג׳ר מקגווין ראה את הסרט A Hard Day’s Night (אלבום 42), וקנה גיטרה חשמלית של שנים־עשר מיתרים כמו של ג׳ורג׳ הריסון. בינואר 1965 הם הקליטו גרסה חשמלית ל־Mr. Tambourine Man של בוב דילן, עוד לפני שהמקור של דילן יצא. המפיק לא סמך עדיין על הלהקה, ולכן בשיר עצמו מנגנים נגני אולפן מקצועיים, ורק מקגווין מנגן מחברי הלהקה. השיר עלה למקום הראשון באמריקה ובבריטניה, והאלבום יצא ביוני.''',
'''הגיטרה של מקגווין פותחת את השיר בצליל צלצלני ובהיר, כמו פעמונים, ומעליה ההרמוניות של מקגווין, ג׳ין קלארק ודייוויד קרוסבי. באלבום יש ארבעה שירים של דילן, שירים שכתב בעיקר קלארק, ו־The Bells of Rhymney, שיר על כורי הפחם בוויילס, שמילותיו לקוחות משיר של המשורר הוולשי אידריס דייוויס, ופיט סיגר הלחין אותן. האלבום נגמר בבדיחה: We’ll Meet Again, שיר נוסטלגי מימי מלחמת העולם השנייה.''',
'''האלבום הראה שאפשר לחבר בין מילים חכמות של פולק לבין קצב של רוק, ונתן לסגנון החדש את שמו: פולק־רוק. דילן עצמו שמע את הגרסה ואהב אותה. הצליל של הבירדס השפיע על להקות רבות, מההיפים של סן פרנסיסקו ועד להקות האינדי של שנות השמונים.''',
'''השוו את Mr. Tambourine Man כאן למקור של דילן באלבום 50. הבירדס קיצרו אותו מאוד: נסו לשמוע מה נשאר ומה נעלם. ואחר כך המשיכו עם הבירדס לאלבומים 63 ו־94.''',
], [
('Mr. Tambourine Man', 'הגרסה שהפכה שיר של דילן ללהיט פופ. הקשיבו לגיטרה בפתיחה.'),
('The Bells of Rhymney', 'שיר עצוב על מכרות פחם בוויילס, עם גיטרות מצלצלות כמו פעמוני כנסייה.'),
('I’ll Feel a Whole Lot Better', 'שיר של ג׳ין קלארק, קצבי ושמח, על פרידה שאולי היא דווקא הקלה.'),
])

add(58, [
'''ב־25 ביולי 1965 עלה בוב דילן לבמה בפסטיבל הפולק של ניופורט עם להקה חשמלית, וחלק מהקהל שרק ומחה, בזמן שאחרים הריעו. לפני כן, ביוני, הוא כבר הקליט את Like a Rolling Stone, שיר של יותר משש דקות, ארוך בהרבה ממה שהרדיו השמיע אז. הוא הגיע למקום השני במצעד האמריקאי. באוגוסט יצא Highway 61 Revisited, שנקרא על שם הכביש שעובר מהעיר שבה דילן נולד, במינסוטה, ועד ניו אורלינס, דרך ארץ הבלוז של מיסיסיפי.''',
'''הצליל גס וחי: גיטרת בלוז של מייק בלומפילד, פסנתר, תופים, ועוגב של אל קופר, צעיר שהגיע לאולפן כאורח, התיישב ליד העוגב אף שלא ממש ידע לנגן בו, ונתן ל־Like a Rolling Stone את אחד הצלילים המפורסמים שלו. מעל כל זה דילן שר, מתגרה ולועג, מילים מלאות דמויות מוזרות, סצנות סוריאליסטיות ובדיחות אפלות. האלבום מסתיים ב־Desolation Row, שיר אקוסטי של יותר מאחת־עשרה דקות, כמו תהלוכה של דמויות מהתנ״ך, מהספרות ומהקרקס.''',
'''זה אחד האלבומים החשובים בתולדות הרוק. Like a Rolling Stone נבחר שוב ושוב לאחד השירים הגדולים שנכתבו אי פעם, והאלבום כולו הראה שרוק יכול להיות גם ספרות. יחד עם אלבום 50 ואלבום 64, זו השלישייה שבה דילן שינה את הכללים, בפחות משנה וחצי.''',
'''שמעו את Like a Rolling Stone בווליום גבוה, והקשיבו לתוף הבודד שפותח אותו, כמו דלת שנטרקת. אחר כך המשיכו לאלבום 64, השלישי בשלישייה.''',
], [
('Like a Rolling Stone', 'שש דקות על נפילה מהגובה, ואחד השירים הגדולים בתולדות הרוק. הקשיבו לעוגב.'),
('Ballad of a Thin Man', 'שיר מרושע ואפל, על אדם שלא מבין את מה שקורה סביבו.'),
('Desolation Row', 'שיר אקוסטי ארוך ומלא דמויות, שקט אחרי הסערה.'),
])

add(59, [
'''The Who היו ארבעה בחורים מלונדון: הזמר רוג׳ר דלטרי, הגיטריסט פיט טאונשנד, הבסיסט ג׳ון אנטוויסל והמתופף קית׳ מון. הם הפכו לגיבורים של ה"מודס", הנוער הבריטי האופנתי עם הקטנועים, והתפרסמו בהופעות שבהן טאונשנד ניפץ את הגיטרה ומון בעט בתופים. אלבום הבכורה שלהם יצא ב־3 בדצמבר 1965, באותו יום כמו Rubber Soul של הביטלס (אלבום 55). טאונשנד, בן 20, כתב את רוב השירים.''',
'''הלהקה נשמעת כמו משהו שעומד להתפוצץ: גיטרות רועשות ומשובשות, תופים שמתפרצים כל הזמן, והבס של אנטוויסל, שמנגן כאן סולו, דבר כמעט לא מוכר בשיר רוק. My Generation הוא שיר על כעס של צעירים, שבו דלטרי מגמגם כאילו הוא כועס מכדי לדבר, ושר שעדיף למות לפני שמזדקנים. יש כאן גם שני שירים של ג׳יימס בראון, קטע אינסטרומנטלי פרוע בשם The Ox, ושירי פופ עם הרמוניות, כמו The Kids Are Alright.''',
'''זה הקול של דור שלם של צעירים בריטים שמדבר חזק, ואחד מאבות הרוק הקשה והפאנק. כאן רואים את ההתחלה של להקה שתיצור אחר כך את The Who Sell Out (אלבום 90), את אופרת הרוק Tommy ואת Who’s Next. ובעוד שהביטלס של אותו יום התחילו להסתכל פנימה, The Who עדיין רצו בעיקר לעשות רעש.''',
'''שמעו את I Don’t Mind ואת Please, Please, Please כאן, ואז את ג׳יימס בראון שר את שניהם באלבום 40. ואחר כך שמעו את My Generation פעם נוספת, והפעם הקשיבו רק לבס.''',
], [
('My Generation', 'הריף והגמגום המפורסם, ההמנון של המרד. הקשיבו לסולו הבס.'),
('The Kids Are Alright', 'שיר פופ מתוק וישר, עם הרמוניות נקיות וגיטרות מצלצלות.'),
('The Ox', 'קטע אינסטרומנטלי פרוע, שבו כל אחד מהארבעה מנסה לנגן חזק יותר מהשאר.'),
])

add(60, [
'''ב־1966 הביטלס כבר היו עייפים מסיבובי הופעות: הקהל צרח כל כך חזק שהם לא שמעו את עצמם מנגנים. באולפני אבי רוד, לעומת זאת, הם יכלו לנסות כל מה שעלה בדעתם, עם המפיק ג׳ורג׳ מרטין ומהנדס צעיר בן 20 בשם ג׳וף אמריק. את Revolver הקליטו בין אפריל ליוני, והוא יצא באוגוסט 1966, בזמן סיבוב ההופעות האחרון שלהם. אף שיר מהאלבום לא בוצע בהופעות, וכמה מהם כנראה גם לא היו יכולים להתבצע אז על במה. את העטיפה צייר קלאוס פורמן, חבר ותיק מימי המבורג.''',
'''כל שיר נשמע כמו עולם משלו. האלבום נפתח ב־Taxman של ג׳ורג׳ הריסון, שיר זועם על מס הכנסה. ב־Eleanor Rigby מלווה את מקרטני רק תזמורת כלי קשת קטנה, בלי אף ביטל שמנגן. יש שיר הודי, Love You To, שיר ילדים שכולם שרים, Yellow Submarine, בלדות של מקרטני וכלי נשיפה בסגנון הסול האמריקאי. ובסוף Tomorrow Never Knows, השיר הראשון שהוקלט לאלבום: לולאות של סרט הקלטה, תופים שחוזרים כמו מכונה, והקול של לנון שנשמע כאילו הוא מגיע מפסגת הר.''',
'''רבים רואים ב־Revolver את האלבום הטוב ביותר של הביטלס, ויש שאומרים שהוא האלבום שבו הרוק גילה את האולפן. הוא ההמשך של Rubber Soul (אלבום 55), בן זמנו של Pet Sounds (אלבום 61), שיצא כמה חודשים קודם, והכנה ל־Sgt. Pepper (אלבום 78).''',
'''שמעו את Eleanor Rigby ואז מיד את Tomorrow Never Knows: באותו אלבום, אותה להקה, ושני קצוות של מה שהיא יכלה לעשות. ואחר כך שמעו את Got to Get You Into My Life, וחזרו לאלבום 51 כדי לשמוע מאיפה באו כלי הנשיפה.''',
], [
('Eleanor Rigby', 'שיר על בדידות, מלווה בכלי קשת בלבד.'),
('Tomorrow Never Knows', 'סיום ניסיוני שנשמע כמו משהו מעולם אחר, ואחד השירים הכי מוזרים של הלהקה.'),
('Here, There and Everywhere', 'בלדה עדינה שפול מקרטני כתב, ואחד השירים האהובים עליו מכל מה שכתב.'),
])

add(61, [
'''בסוף 1965 בריאן וילסון, בן 23, כבר לא הופיע עם הביץ׳ בויז, והקדיש את כל זמנו לאולפן (אלבום 52). הוא שמע את Rubber Soul של הביטלס (אלבום 55), התרשם מאלבום שבו כל השירים טובים, והחליט ליצור משהו גדול עוד יותר. בזמן ששאר הלהקה הופיעה ביפן, הוא עבד חודשים באולפנים בלוס אנג׳לס עם נגני האולפן הטובים בעיר, ועם כותב מילים צעיר מעולם הפרסום, טוני אשר. כשהלהקה חזרה, נשאר לה רק להוסיף את הקולות. Pet Sounds יצא במאי 1966.''',
'''האלבום מלא בעיבודים שלא נשמעו קודם בפופ: חלילים, צ׳מבלו, פעמוני אופניים, כלי מיתר, כלי נשיפה, ואפילו נביחות של הכלבים של בריאן ורכבת חולפת בסוף. מעל כל זה ההרמוניות הקוליות המורכבות של הלהקה. והשירים, שנשמעים שמחים במבט ראשון, מדברים על געגוע, על הפחד מהתבגרות, על בדידות ועל אהבה שאולי לא תחזיק. I Just Wasn’t Made for These Times הוא בעצם וידוי של בריאן על עצמו.''',
'''באמריקה האלבום מכר פחות מהצפוי, וחברת התקליטים מיהרה להוציא אחריו אוסף להיטים. אבל בבריטניה הוא הצליח מאוד, והמוזיקאים שם שמעו אותו היטב: פול מקרטני אמר שוב ושוב ש־God Only Knows הוא אחד השירים האהובים עליו בכל הזמנים, והביטלס עצמם אמרו שהאלבום השפיע על Sgt. Pepper (אלבום 78). עם השנים Pet Sounds הפך לאחד האלבומים המוערכים ביותר בתולדות הפופ.''',
'''הקשיבו עם אוזניות, ובחרו שיר אחד, למשל God Only Knows, כדי לנסות לעקוב אחרי כל הכלים. שמעו גם את Let’s Go Away for Awhile, קטע אינסטרומנטלי קצר שבריאן אמר שהוא מהדברים היפים שהקליט.''',
], [
('God Only Knows', 'שיר אהבה יוצא דופן, שנפתח דווקא במחשבה שהאהבה עלולה להיגמר. הקשיבו לסוף, שבו הקולות משתלבים זה בזה.'),
("Wouldn't It Be Nice", 'פתיחה נוצצת, על שני נערים שרוצים כבר להיות מבוגרים ולחיות יחד.'),
('Caroline, No', 'סיום עצוב על אהבה שהשתנתה, ובסופו נביחות ורכבת שמתרחקת.'),
])

add(62, [
'''פרד ניל היה אחד האנשים החשובים בסצנת הפולק של גריניץ׳ וילג׳ בתחילת שנות השישים, אף שמעט אנשים מחוצה לה הכירו אותו. כשבוב דילן הצעיר הגיע לניו יורק ב־1961, אחד הדברים הראשונים שעשה היה לנגן במפוחית בהופעות של ניל. ניל כתב שירים לאחרים, הופיע במועדונים, אבל שנא את הבמה ואת הפרסום, ובילה כל הזדמנות בפלורידה, ליד הים. באוקטובר 1966 הוא הקליט באולפני חברת Capitol את האלבום השני שלו, שנקרא פשוט בשמו.''',
'''הקול של ניל הוא הדבר הראשון ששמים לב אליו: בריטון עמוק, חם ואיטי, של מישהו שלא ממהר לשום מקום. הגיטרה האקוסטית מנגנת בקצב מתגלגל, עם נגינה של גיטרה חשמלית ובס ברקע, והשירים נעים בין פולק, בלוז וג׳אז. The Dolphins הוא שיר על הים ועל הדולפינים שניל אהב, ו־Everybody’s Talkin’ הוא שיר על אדם שרוצה רק לברוח מהרעש, אל השמש ואל הים. בסוף האלבום יש קטע אלתור ארוך, בהשפעת מוזיקה הודית.''',
'''התקליט לא הצליח בזמנו. שלוש שנים אחר כך הארי נילסון הקליט את Everybody’s Talkin’ לסרט "קאובוי של חצות", השיר הפך ללהיט וזכה בגראמי, והאלבום של ניל יצא מחדש תחת שם השיר. ניל עצמו כמעט הפסיק להופיע, עבר לפלורידה, והקדיש את רוב שארית חייו להגנה על דולפינים. מוזיקאים רבים, מטים באקלי ועד ג׳פרסון איירפליין, הקליטו את שיריו, והקול שלו השפיע על זמרים רבים שבאו אחריו.''',
'''שמעו את Everybody’s Talkin’ כאן, ואז את הגרסה של הארי נילסון: אותו שיר, בגרסה אחת לסלון ובשנייה לקולנוע. ואחר כך המשיכו לטים באקלי באלבום 86, שהושפע מניל ושר לימים את The Dolphins.''',
], [
("Everybody's Talkin'", 'השיר המפורסם ביותר של ניל, שנשמע כאן פשוט ואינטימי, הרבה לפני שהפך ללהיט בקולנוע.'),
('The Dolphins', 'שיר שקט ומהפנט על הים ועל דולפינים, ואחד האהובים על מוזיקאים אחרים.'),
("That's The Bag I'm In", 'בלוז פולק מתגלגל, עם גיטרה בחזית וקול שמזמין לשבת ולהקשיב.'),
])

add(63, [
'''בתחילת 1966 הבירדס היו אחת הלהקות הגדולות באמריקה, אחרי שני אלבומים של פולק־רוק (אלבום 57). אבל הם כבר רצו משהו אחר. ג׳ין קלארק, הכותב העיקרי שלהם, עזב את הלהקה, בין השאר בגלל פחד מטיסות, ורוג׳ר מקגווין ודייוויד קרוסבי נשארו להוביל. בסיבובי ההופעות הם שמעו שוב ושוב קלטות של ג׳ון קולטריין ושל נגן הסיטאר ההודי ראווי שנקר, והמוזיקה הזאת נכנסה לגיטרות שלהם. האלבום השלישי שלהם, Fifth Dimension, יצא ביולי 1966.''',
'''ב־Eight Miles High הגיטרה של מקגווין מנגנת בצורה שלא נשמעה קודם ברוק: שורות ארוכות וחוזרות, מושפעות מהסקסופון של קולטריין ומהסיטאר, שנשמעות כמו מטוס שמתרומם ומיטלטל. גם 5D, שיר על המימד החמישי, ו־Mr. Spaceman, שיר הומוריסטי על חייזרים, מנסים דברים חדשים. לצדם יש שירי עם ישנים, כמו Wild Mountain Thyme הסקוטי, ו־I Come and Stand at Every Door, שיר שקט ומצמרר על ילדה שנהרגה בהירושימה.''',
'''Eight Miles High נחשב לאחד השירים הפסיכדליים הראשונים. רוב תחנות הרדיו האמריקאיות הפסיקו להשמיע אותו אחרי שנטען שהוא מדבר על סמים, והלהקה התעקשה שהוא מדבר על טיסה ללונדון. השיר הגיע רק למקום ה־14, אבל השפיע מאוד על הרוק של השנים הבאות, והראה שגיטרה חשמלית יכולה לנגן גם כמו כלי ג׳אז או כלי הודי.''',
'''שמעו את Hey Joe כאן, ששר קרוסבי, ואז את הגרסה של ג׳ימי הנדריקס באלבום 100, שהפכה אותו ללהיט: אותו שיר, בשתי מהירויות שונות לגמרי. והשוו את Eight Miles High ל־Mr. Tambourine Man באלבום 57, שיצא שנה אחת קודם.''',
], [
('Eight Miles High', 'סינגל שהראה לרוק דרך חדשה להשתמש בגיטרה. הקשיבו לפתיחה של הבס ולגיטרה שנכנסת אחריו.'),
('5D (Fifth Dimension)', 'שיר על המימד החמישי, עם עוגב, שנשמע כמו כניסה לעולם אחר.'),
('I Come and Stand at Every Door', 'שיר שקט ועצוב על ילדה שנהרגה בהירושימה, ששרה מדלת לדלת ומבקשת שלום.'),
])

add(64, [
'''אחרי Highway 61 Revisited (אלבום 58) ניסה בוב דילן להקליט את האלבום הבא בניו יורק, והתאכזב. המפיק בוב ג׳ונסטון הציע לו לנסוע לנאשוויל, בירת הקאנטרי, ולעבוד עם נגני האולפן שם, מהטובים באמריקה. בפברואר ובמרץ 1966, יחד עם אל קופר ורובי רוברטסון, דילן הקליט שם את Blonde on Blonde. הוא כתב את המילים כמעט במקום, והנגנים חיכו לו שעות, לפעמים עד הבוקר, עד שסיים שיר ואמר "עכשיו". האלבום יצא ביוני 1966, ונחשב לאלבום הכפול הראשון ברוק.''',
'''הצליל כאן רך ועשיר יותר מבאלבומים הקודמים, מה שדילן כינה "הצליל הדק והפרוע, כמו כספית": עוגב, מפוחית, גיטרות שנעות זו סביב זו. השירים עוקצניים ורכים, מצחיקים ומסתוריים: Rainy Day Women #12 & 35 נשמע כמו מצעד של להקה שיכורה, Visions of Johanna נע בין חלום למציאות בלילה ארוך, ו־Just Like a Woman הוא שיר אהבה שבור. ובצד הרביעי יש שיר אחד בלבד, Sad-Eyed Lady of the Lowlands, שנמשך יותר מאחת־עשרה דקות ונכתב לשרה, שדילן התחתן איתה כמה חודשים קודם.''',
'''זה השיא של תקופת דילן הצעיר והחשמלי, והאחרון בשלישייה שהתחילה באלבום 50. חודש אחרי שהאלבום יצא דילן נפצע בתאונת אופנוע, נעלם מהבמות לשנים, וכשחזר הוא כבר נשמע אחרת. Blonde on Blonde גם הראה שנאשוויל היא לא רק עיר של קאנטרי, ותוך כמה שנים הרבה מוזיקאי רוק נסעו להקליט שם.''',
'''הקשיבו ל־Visions of Johanna בלילה, בשקט ובאוזניות, ותנו למילים לעבור בלי לנסות להבין כל שורה. ושמרו את Sad-Eyed Lady לסוף, כמו שדילן תכנן.''',
], [
('Visions of Johanna', 'שיר שנע בין חלום למציאות, ואחד הגדולים שדילן כתב.'),
('Just Like a Woman', 'שיר פרידה שבור ועדין, ואחד הלהיטים של האלבום.'),
('I Want You', 'שיר אהבה קליל וקופצני, עם גיטרה שרצה מסביב לקול. הכי קרוב שדילן הגיע לפופ.'),
])

add(65, [
'''The Monks היו חמישה חיילים אמריקאים שהוצבו בגרמניה בתחילת שנות השישים והקימו להקת רוקנרול רגילה. אחרי השחרור הם נשארו בגרמניה, ופגשו שני אנשי פרסום גרמנים שהציעו להם להפוך למשהו אחר לגמרי: "הנזירים". הם גילחו קרחת באמצע הראש, כמו נזירים מימי הביניים, לבשו גלימות שחורות, ענדו חבל תלייה במקום עניבה, והחליטו לנגן מוזיקה שתהיה ההפך מכל מה שהקהל מכיר. ב־1966 הם הוציאו בגרמניה את האלבום היחיד שלהם, Black Monk Time.''',
'''זה נשמע כמו רוקנרול שפירקו לחלקים והרכיבו מחדש: תופים עקשניים וחוזרים, כמעט בלי מצלתיים, בנג׳ו חשמלי שמנגן אקורדים חדים כמו תוף, עוגב צורם, גיטרה משובשת, וקולות שצועקים ביחד. השירים קצרים, מונוטוניים בכוונה, ומלאים במילים מרדניות ומצחיקות: Monk Time מדבר על מלחמת וייטנאם ועל הפצצה, ו־I Hate You הוא בדיוק מה שהשם מבטיח, עם "אני שונא אותך" שחוזר שוב ושוב.''',
'''בזמנו כמעט איש לא הבין אותם. הקהל הגרמני שציפה לביטלס נבהל, והלהקה התפרקה ב־1967, זמן קצר לפני סיבוב הופעות מתוכנן במזרח הרחוק. רק בשנות התשעים, כשהאלבום יצא מחדש, גילו אותו מוזיקאים והבינו שהוא הקדים את הפאנק ואת הרוק הניסיוני הגרמני של שנות השבעים בכמעט עשור. היום הוא נחשב לאחד האלבומים המוזרים והמקוריים של התקופה, במובן הכי טוב.''',
'''שמעו את Monk Time בווליום גבוה, ואחר כך את הסוניקס באלבום 49: שתי להקות שבאותה שנה ניסו לעשות רוקנרול רועש ופרוע יותר, כל אחת מצד אחר של העולם.''',
], [
('Monk Time', 'הפתיחה והצהרת הכוונות של הלהקה, עם צעקות על מלחמה ועל פצצות.'),
('I Hate You', 'שיר קצר ועוקצני, עם בנג׳ו שמכה כמו תוף וצעקה שחוזרת בלי סוף.'),
('Complication', 'אחד הסינגלים של הלהקה, קצבי, מתוח ומוזר.'),
])

add(66, [
'''בתחילת 1966 ריי דייוויס, הכותב של הקינקס, קרס מעייפות אחרי שנתיים של הופעות, להיטים ולחץ. בזמן שהחלים הוא התחיל לכתוב אחרת: פחות שירי אהבה וריפים, ויותר שירים על אנשים, על המעמדות בבריטניה ועל החיים הקטנים. הלהקה, עם אחיו הצעיר דייב בגיטרה, התחילה להקליט אותם באותה שנה. הסינגל Sunny Afternoon הגיע למקום הראשון בבריטניה בקיץ 1966, והאלבום Face to Face יצא באוקטובר.''',
'''השירים מציירים דמויות, עם הומור בריטי חד וקצת מלנכוליה: Dandy, הרווק שעובר מאישה לאישה, Session Man, נגן האולפן שמנגן בכל מקום ואף אחד לא יודע מי הוא, בעלי האחוזה שמאבדים את הבית, ו־Sunny Afternoon, על אריסטוקרט שמס ההכנסה לקח לו את הכול והוא יושב בשמש ומתלונן. יש כאן גם צלילים מפתיעים, כמו טלפון שמצלצל וגלים של ים, וצ׳מבלו שנותן לחלק מהשירים צבע של אנגליה ישנה.''',
'''Face to Face מסמן את המעבר של הקינקס מלהקת ריף חדה ללהקה שמתבוננת בחיים. ריי דייוויס הפך בו לאחד הכותבים החשובים של הרוק הבריטי, מספר סיפורים שמדבר על אנגליה בחיבה ובעוקץ. הדרך הזאת מובילה ישר אל Something Else (אלבום 97), וממנו לאלבומים הגדולים של הקינקס בסוף העשור.''',
'''שמעו את Sunny Afternoon ואחר כך את Taxman של הביטלס, שפותח את אלבום 60, שיצא כמה חודשים אחר כך: שני שירים זועמים וחייכניים על מס הכנסה, באותה שנה. ומשם המשיכו לאלבום 97.''',
], [
('Sunny Afternoon', 'להיט קליל ועצלני, עם מילים מצחיקות ועצובות על אדם שהפסיד הכול למס.'),
('Dandy', 'דיוקן קליל ואירוני של רווק שלא רוצה להתחייב לאף אחת.'),
('Session Man', 'שיר על נגן אולפן שכולם צריכים ואף אחד לא מכיר, עם צ׳מבלו בפתיחה.'),
])

add(67, [
'''The Mamas & the Papas היו ארבעה זמרים שהגיעו מסצנת הפולק של ניו יורק: ג׳ון פיליפס, שכתב את רוב השירים, אשתו הצעירה מישל, דני דוהרטי, וקאס אליוט, בעלת הקול העמוק. בחורף 1963, בדירה קרה בניו יורק, כתבו ג׳ון ומישל את California Dreamin’, שיר געגוע לשמש. כמה שנים אחר כך הם עברו ללוס אנג׳לס, והמפיק לו אדלר החתים אותם. אלבום הבכורה שלהם יצא בתחילת 1966 והגיע למקום הראשון במצעד האמריקאי, היחיד שלהם שהגיע לשם.''',
'''הקולות של הארבעה נשזרים להרמוניות עשירות ומורכבות, שמזכירות גם פולק, גם ג׳אז וגם מקהלת כנסייה, ומעליהן בולט הקול החם והעמוק של קאס אליוט. ברקע מנגנים נגני האולפן הטובים של לוס אנג׳לס. California Dreamin’, עם סולו החליל המפורסם באמצע, הוא שיר על חורף אפור בניו יורק. Monday, Monday, שיר שמח על יום עצוב, עלה לראש המצעד. לצדם יש גרסאות לשירים של אחרים, מהביטלס ועד שירי ריקוד.''',
'''זה הצליל של קליפורניה של אמצע שנות השישים: פולק שהפך לפופ, בין חלום לזיכרון. גם העטיפה עשתה היסטוריה: הארבעה צולמו באמבטיה, אבל בפינה הופיעה אסלה, וחברת התקליטים כיסתה אותה בגרסאות מאוחרות. בשנה שאחרי ג׳ון פיליפס היה מהמארגנים של פסטיבל מונטריי, אחד מהאירועים שפתחו את "קיץ האהבה" של 1967.''',
'''שמעו את I Call Your Name, שיר של הביטלס, והשוו את ההרמוניות כאן לאלה של הביץ׳ בויז באלבום 52. ושימו לב בכל שיר מי מהארבעה שר איזה קו: לפעמים קשה לדעת.''',
], [
("California Dreamin'", 'געגוע לשמש ביום חורף אפור, עם סולו חליל מפורסם באמצע.'),
('Monday, Monday', 'הלהיט הגדול שלהם, שיר שמח על כמה שקשה יום שני.'),
('Go Where You Wanna Go', 'שיר על אהבה שנותנת חופש, עם עיבוד קולי מורכב.'),
])

add(68, [
'''Paul Revere & the Raiders התחילו בסוף שנות החמישים באיידהו, ועברו לפורטלנד שבאורגון, שם ניגנו רוקנרול באולמות ריקודים. פול ריוויר, שזה באמת שמו, היה הקלידן והמנהיג, והזמר מארק לינדזי היה הפנים של הלהקה. הם הופיעו בתחפושות של חיילים מימי מלחמת העצמאות האמריקאית, עם כובעים משולשים, ובזכות תוכנית טלוויזיה יומית לנוער, שבה היו להקת הבית, הם הפכו לכוכבים. האלבום Midnight Ride יצא ב־1966, בהפקה של טרי מלצ׳ר, שהפיק גם את הבירדס (אלבום 57).''',
'''זה רוקנרול אמריקאי חד וקצבי, עם גיטרות, עוגב, והקול המחוספס והבטוח של לינדזי. Kicks, שכתבו זוג הכותבים המקצועיים בארי מאן וסינתיה וייל, הוא שיר שמזהיר חבר מסמים, ובכל זאת נשמע כמו מסיבה. I’m Not Your Stepping Stone הוא שיר חצוף ובועט על מישהי שמנצלת את המספר, ו־Louie, Go Home ממשיך את השיר Louie Louie, השיר שכל להקה בצפון־מערב ארצות הברית ניגנה אז.''',
'''באותן שנים המבקרים ראו בהם להקת טלוויזיה ולא יותר. עשרות שנים אחר כך חזרו לזהות בלהקה הזאת משהו חשוב: את הגראז׳ רוק האמריקאי של אמצע שנות השישים, מלא אנרגיה ופחות נוצץ מהלהיטים הגדולים של הביטלס. I’m Not Your Stepping Stone הפך מאוחר יותר ללהיט של המונקיז, ולהקות פאנק, ובהן הסקס פיסטולס, ניגנו אותו בהופעות.''',
'''שמעו את I’m Not Your Stepping Stone כאן, ואחר כך את הגרסה של המונקיז, הלהקה של אלבום 85: אותו שיר, בגרסה מחוספסת ובגרסה של פופ טלוויזיוני. והשוו את Kicks לסוניקס באלבום 49.''',
], [
('Kicks', 'שיר נגד סמים שנשמע כמו חגיגה. הקשיבו לגיטרה בפתיחה.'),
("I'm Not Your Stepping Stone", 'שיר קצבי וחצוף, שלהקות פאנק ביצעו לימים בעצמן.'),
('Louie, Go Home', 'המשך לשיר Louie Louie, עם כל הרעש של הצפון־מערב.'),
])

add(69, [
'''פרנק זאפה גדל בקליפורניה, אהב באותה מידה ריתם אנד בלוז ומלחינים מודרניים כמו אדגר וארז וסטרווינסקי, וב־1965 הפך להיות המנהיג של להקת בר בלוס אנג׳לס, שקראה לעצמה The Mothers. המפיק טום וילסון, שהפיק לדילן את אלבומים 50 ו־58, שמע רק שיר אחד שלהם, Trouble Every Day, על המהומות בשכונת ווטס, וחשב שמדובר בלהקת בלוז. הוא החתים אותם במרץ 1966, וגילה עד כמה טעה. Freak Out! יצא ביוני 1966, שבוע אחרי Blonde on Blonde (אלבום 64), כאחד האלבומים הכפולים הראשונים ברוק.''',
'''האלבום מלא בהומור מוזר, בלחנים מעוותים ובקולות משונים. בחלקו הראשון יש שירים שנשמעים כמו פרודיה על שירי אהבה של להקות נוער, עם הרמוניות מתקתקות ומילים מגוחכות. Hungry Freaks, Daddy פותח בהתקפה על החברה האמריקאית הצרכנית, Trouble Every Day הוא בלוז זועם על גזענות ועל תקשורת. ובסוף, הצד האחרון שוקע בקטע ארוך של כלי הקשה, צעקות ורעש, שזאפה הקליט עם חבורה של "פריקים" מלוס אנג׳לס.''',
'''זה אלבום שהראה שאפשר להשתמש ברוק לא רק לשירי אהבה, אלא גם לסאטירה, לביקורת חברתית ולניסויים. הוא נכשל כמעט לגמרי בזמנו, אבל מוזיקאים שמו לב: יש שאומרים שגם הביטלס התרשמו ממנו כשעבדו על Sgt. Pepper (אלבום 78). זאפה המשיך בדרך הזאת עוד כמעט שלושים שנה, בעשרות אלבומים.''',
'''התחילו מ־Trouble Every Day, השיר הכי ישיר וברור באלבום, ורק אחר כך עברו להתחלה. ואם תרצו לשמוע מה עוד טום וילסון הפיק באותה שנה, חפשו את שמו על אלבום 91.''',
], [
('Hungry Freaks, Daddy', 'פתיחה זועמת ומצחיקה, על מה שזאפה חושב על אמריקה.'),
('Trouble Every Day', 'שיר על המהומות בלוס אנג׳לס, בלוז חד וכועס.'),
('Who Are the Brain Police?', 'שיר אפל ומפחיד על שליטה במחשבות, שנשמע כמו חלום רע.'),
])

add(70, [
'''באביב 1966 הרולינג סטונס כבר היו אחת משתי הלהקות הגדולות בעולם, לצד הביטלס. באלבומים הקודמים שלהם (כמו אלבום 46) הם ניגנו בעיקר שירי בלוז ורוקנרול של אחרים, אבל המנהל שלהם, אנדרו לוג אולדהם, לחץ על מיק ג׳אגר וקית׳ ריצ׳רדס לכתוב בעצמם. Aftermath, שהוקלט בעיקר באולפן בהוליווד בין דצמבר 1965 למרץ 1966, הוא האלבום הראשון שלהם שכל שיריו נכתבו על ידם. בגרסה האמריקאית, שאותה תשמעו כאן, יש אחד־עשר שירים, ובהם Paint It, Black.''',
'''בריאן ג׳ונס, שכמעט הפסיק לכתוב ולהוביל, מצא את מקומו בכלים חדשים: סיטאר ב־Paint It, Black, מרימבה ב־Under My Thumb ודולצימר, כלי מיתרים עממי אמריקאי, ב־Lady Jane. השירים נעים בין בלוז מחוספס, בלדות עדינות בנוסח אנגליה העתיקה, ופופ עוקצני. ובסוף יש Going Home, בלוז ארוך של יותר מאחת־עשרה דקות, מהראשונים ברוק שבהם הלהקה פשוט המשיכה לנגן והקלטת המשיכה להסתובב.''',
'''זה האלבום שבו הסטונס הוכיחו שהם יכולים ליצור לבד, בלי לחקות. חלק מהמילים, במיוחד על נשים, נחשבות היום מכוערות, ואי אפשר להתעלם מזה. אבל מבחינה מוזיקלית זה אחד האלבומים החשובים שלהם, והוא פתח את התקופה שבה הם הפכו מלהקת בלוז בריטית לאחת מלהקות הרוק הגדולות בהיסטוריה.''',
'''השוו לאלבום 46, שיצא שנתיים קודם: אותה להקה, אבל עכשיו כל השירים שלה. ושמעו את Paint It, Black ואז את Norwegian Wood באלבום 55: שני שירים עם סיטאר, מאותה חצי שנה, שנשמעים שונים לגמרי.''',
], [
('Paint It, Black', 'סיטאר ותופים שנשמעים כמו מרדף, ואחד הלהיטים הגדולים והאפלים שלהם.'),
('Under My Thumb', 'קצב מתפתל עם מרימבה, ושיר שהמילים שלו שנויות במחלוקת עד היום.'),
('Lady Jane', 'בלדה עדינה עם דולצימר, שנשמעת כמו שיר מחצר המלוכה באנגליה הישנה.'),
])

add(71, [
'''פול סיימון וארט גרפונקל גדלו באותה שכונה בניו יורק ושרו יחד כבר כנערים. אלבום הפולק הראשון שלהם, ב־1964, נכשל, והם נפרדו: סיימון נסע לאנגליה והופיע שם במועדוני פולק. ואז, בלי שידעו, המפיק טום וילסון הוסיף גיטרות חשמליות ותופים לשיר שלהם The Sound of Silence, והוא הגיע למקום הראשון באמריקה בתחילת 1966. הם התאחדו מחדש, והפעם לקחו את הזמן: Parsley, Sage, Rosemary and Thyme, שהוקלט במשך כמה חודשים, יצא באוקטובר 1966.''',
'''האלבום נפתח ב־Scarborough Fair / Canticle: בלדה אנגלית עתיקה, שסיימון למד באנגליה מזמר הפולק מרטין קארתי, ומעליה, בקול שני, שיר נגד מלחמה שסיימון כתב בעצמו. ההרמוניות של השניים צמודות ועדינות, והעיבודים משלבים גיטרה אקוסטית, צ׳מבלו וכלי מיתר. Homeward Bound הוא געגוע הביתה של זמר בדרכים, The 59th Street Bridge Song (Feelin’ Groovy) קליל וחייכני, ו־The Dangling Conversation עצוב ושקט. ויש גם פרודיה מצחיקה על בוב דילן.''',
'''זה אלבום של מילים חכמות ולחנים מדויקים, ואחד המקומות הטובים להכיר את סיימון וגרפונקל בשיאם המוקדם. בסופו, Silent Night מושר בעדינות, ומתחתיו קריין קורא מבזק חדשות של יום אחד באוגוסט 1966: מלחמת וייטנאם, הפגנות, רצח, ומותו של קומיקאי. החדשות עולות בהדרגה עד שהן מכסות את השיר. זה אחד הסיומים המצמררים של התקופה, והוא אומר על המציאות יותר ממה שכל שיר מחאה יכול היה לומר.''',
'''שמעו את Scarborough Fair כאן, ואז את Girl from the North Country של בוב דילן באלבום 36: שני כותבים אמריקאים ששמעו באנגליה את אותו שיר עם, ויצרו ממנו שני שירים שונים לגמרי.''',
], [
('Scarborough Fair / Canticle', 'בלדה עתיקה ושיר נגד מלחמה, שנשזרים זה בזה בשני קולות.'),
('Homeward Bound', 'געגוע הביתה של זמר שיושב בתחנת רכבת, רחוק ממי שהוא אוהב.'),
("7 O'Clock News / Silent Night", 'שיר חג שקט, ומתחתיו חדשות קשות שהולכות ומתגברות. סיום מצמרר.'),
])

add(72, [
'''13th Floor Elevators נוסדו ב־1965 באוסטין שבטקסס, סביב שני אנשים: הזמר והגיטריסט רוקי אריקסון, נער בן 18 עם קול פראי, וטומי הול, סטודנט שכתב את רוב המילים והאמין שסמים פסיכדליים יכולים לשנות את התודעה של האנושות. הם הופיעו בטקסס השמרנית, והמשטרה רדפה אותם שוב ושוב. בנובמבר 1966 יצא אלבום הבכורה שלהם, בחברת תקליטים קטנה מיוסטון, והשם שלו הוא ככל הנראה הפעם הראשונה שהמילה "פסיכדלי" הופיעה בשם של אלבום.''',
'''הצליל שלהם מיוחד מאוד: גיטרות חשמליות חדות ומהדהדות, הקול הנסער והצורח של אריקסון, ומעל הכול צליל מוזר ומבעבע, כמו בועות או כמו ציפור מכנית. זה טומי הול, שמנגן על כד חימר עם מיקרופון, כלי שבדרך כלל שייך ללהקות כפריות ישנות, וכאן נשמע כמו משהו מהחלל. You’re Gonna Miss Me הוא שיר גראז׳ פרוע על פרידה, ו־Roller Coaster מסתחרר כמו שמו, עם מילים על מסע פנימי.''',
'''You’re Gonna Miss Me הגיע למקום ה־55 במצעד, והלהקה הופיעה בסן פרנסיסקו והשפיעה על הלהקות שם. אבל הסיפור שלהם נגמר רע: ב־1969 אריקסון נעצר על החזקת סם, ובמקום כלא נשלח לבית חולים פסיכיאטרי, שם עבר טיפולים קשים. רק שנים רבות אחר כך הוא חזר להופיע, ומוזיקאים רבים, מלהקות פאנק ועד להקות אינדי, סיפרו כמה האלבום הזה השפיע עליהם.''',
'''שמעו את You’re Gonna Miss Me ונסו לעקוב רק אחרי צליל הכד של טומי הול, מההתחלה ועד הסוף. ואחר כך השוו לסוניקס באלבום 49: שתי להקות גראז׳ פרועות מאותה תקופה, אחת פשוט רועשת, והשנייה רוצה לשנות את העולם.''',
], [
("You're Gonna Miss Me", 'שיר גראז׳ פרוע עם צעקות של אריקסון, ואחד השירים המפורסמים של התקופה.'),
('Roller Coaster', 'שיר מסתחרר עם צליל הבועות המוזר של הכד.'),
('Reverberation (Doubt)', 'שיר על ספק ועל פחד, עם גיטרה שמהדהדת ומתפוצצת.'),
])

add(73, [
'''באביב 1965 עזב אריק קלפטון, בן 19, את הירדבירדס (אלבום 74), כי הם רצו להיות להקת פופ והוא רצה לנגן בלוז. הוא הצטרף ללהקה של ג׳ון מאייל, מוזיקאי בלוז בריטי ותיק שאסף סביבו נגנים צעירים, לצד הבסיסט ג׳ון מקווי, לימים מפליטווד מק. במועדונים של לונדון הנגינה שלו עשתה רושם כזה, שעל קירות העיר הופיעו כתובות "קלפטון הוא אלוהים". במאי 1966 הקליטה הלהקה את האלבום הזה, שיצא ביולי. על העטיפה קלפטון קורא חוברת קומיקס לילדים בשם Beano, רק כדי להרגיז את הצלם, ומכאן השם שהאלבום קיבל: "אלבום הבינו".''',
'''קלפטון ניגן על גיטרת גיבסון לס פול, דרך מגבר מרשל שהפעיל בעוצמה מלאה, גם באולפן. מהנדס ההקלטה נבהל מהרעש, אבל הצליל שיצא, עבה, חם ומתמשך, הפך לסמל של הבלוז הבריטי ולצליל שגיטריסטים מחפשים עד היום. האלבום מלא בשירי בלוז אמריקאיים של אמנים כמו אוטיס ראש, פרדי קינג ורוברט ג׳ונסון, בביצוע צעיר, חם ובוטה, לצד שירים של מאייל. ב־Ramblin’ on My Mind קלפטון שר בפעם הראשונה בהקלטה.''',
'''זה אחד האלבומים שהתחילו את עידן "הגיטריסט הגיבור", שבו הסולו של הגיטרה הוא מרכז השיר. האלבום הגיע למקום השישי במצעד הבריטי, הישג נדיר לתקליט בלוז. חודשים ספורים אחר כך עזב קלפטון והקים את Cream (אלבום 88), ומאייל המשיך לגלות גיטריסטים צעירים, ביניהם פיטר גרין, שהקים אחר כך את פליטווד מק.''',
'''השוו את Hideaway כאן לגרסה המקורית של פרדי קינג, או לנגינה של בי. בי. קינג באלבום 54: קלפטון למד מהם הכול, אבל הצליל שלו חזק ועבה יותר. ואחר כך עברו לאלבום 88.''',
], [
('All Your Love', 'שיר של אוטיס ראש, וגיטרה בוכייה שפותחת את האלבום.'),
('Hideaway', 'קטע אינסטרומנטלי של פרדי קינג, שהפך לסימן היכר של קלפטון.'),
('Ramblin’ on My Mind', 'בלוז של רוברט ג׳ונסון, והפעם הראשונה שקלפטון שר בהקלטה.'),
])

add(74, [
'''הירדבירדס התחילו ב־1963 כלהקת בלוז מלונדון, ובמשך שלוש שנים עברו בה שלושה מהגיטריסטים החשובים בתולדות הרוק. הראשון היה אריק קלפטון, שעזב ב־1965 כשהלהקה עברה לפופ (אלבום 73). את מקומו תפס ג׳ף בק, גיטריסט פרוע וניסיוני. ב־1966, עם בק, הם הקליטו את האלבום היחיד שלהם שכל שיריו נכתבו על ידי חברי הלהקה. שמו הרשמי הוא פשוט Yardbirds, אבל כולם קוראים לו Roger the Engineer, על שם הציור של מהנדס ההקלטה רוג׳ר שצייר חבר הלהקה כריס דרייה לעטיפה.''',
'''הגיטרה של בק פורצת כאן החוצה: היא מצחקקת, צורחת, מתפתלת כמו כלי מזרחי, ומפזרת צלילים שנשמעים כמעט כמו מכונות. מסביבה יש שירה של קית׳ רלף עם מפוחית, ותופים ובס שמחזיקים קצב חזק. Lost Women ו־The Nazz Are Blue הם בלוז מהיר ועצבני, Over, Under, Sideways, Down הוא הסינגל המוכר, עם ריף שנשמע כמו מזרח תיכוני, ו־Jeff’s Boogie הוא קטע שבו בק פשוט מראה מה הוא יודע.''',
'''זמן קצר אחרי האלבום עזב הבסיסט, ובמקומו הצטרף גיטריסט אולפן צעיר בשם ג׳ימי פייג׳. לתקופה קצרה ניגנו בק ופייג׳ יחד, כמו ב־Happenings Ten Years Time Ago, סינגל פסיכדלי ורועש. אחר כך בק עזב, וב־1968 הלהקה התפרקה, ופייג׳ הקים ממה שנשאר ממנה את לד זפלין. הירדבירדס השפיעו על הרוק הקשה והפסיכדלי של השנים שאחר כך יותר מכמעט כל להקה אחרת מאותה תקופה.''',
'''השוו את הגיטרה של בק כאן לזו של קלפטון באלבום 73, שהוקלט כמה חודשים קודם: שני גיטריסטים מאותה להקה, והפוכים לגמרי. ואחר כך שמעו את Happenings Ten Years Time Ago, ונסו לזהות את שתי הגיטרות.''',
], [
('Over, Under, Sideways, Down', 'סינגל קצבי עם גיטרה שנשמעת כמו כלי מזרחי.'),
('Lost Women', 'בלוז מהיר שנפתח בבס מתגלגל, כמו תחילת מרוץ.'),
('Happenings Ten Years Time Ago', 'סינגל פסיכדלי שבו מנגנים יחד ג׳ף בק וג׳ימי פייג׳.'),
])

add(75, [
'''נינה סימון נולדה כיוניס ווימון בצפון קרוליינה, והתחילה לנגן בפסנתר בכנסייה בגיל שלוש. היא חלמה להיות פסנתרנית קלאסית, אבל נדחתה מבית ספר יוקרתי למוזיקה, דחייה שהיא ייחסה לגזענות. כדי להתפרנס התחילה לנגן ולשיר בבארים, ושינתה את שמה כדי שאמה לא תדע. באמצע שנות השישים היא כבר הייתה כוכבת, וגם קול חשוב בתנועה לזכויות האזרח. Wild Is the Wind יצא ב־1966, והורכב משירים שהקליטה ב־1964 וב־1965 ולא נכנסו לאלבומים קודמים.''',
'''אף שזה אוסף של "שאריות", הוא לא נשמע כך בכלל. סימון מנגנת בפסנתר ושרה בקול עמוק, נמוך ורועד, שלא דומה לשום קול אחר. היא עוברת בין ג׳אז, בלוז, גוספל ושירי עם, ובתוך אותו שיר בין רוך, כעס וכאב. Four Women הוא דיוקן של ארבע נשים שחורות, כל אחת עם גורל אחר, שנכתב בכאב ובזעם. Lilac Wine הוא בלדה רכה וחלומית, ו־Wild Is the Wind, שיר מסרט הוליוודי, הופך אצלה לשיר אהבה סוער ומפחיד.''',
'''Four Women יצא כסינגל, ותחנת רדיו ג׳אז בניו יורק הפסיקה להשמיע אותו בגלל המילים. היום הוא נחשב לאחד השירים החשובים שנכתבו על נשים שחורות באמריקה. ושני שירים מהאלבום עברו הלאה: דייוויד בואי הקליט את Wild Is the Wind ב־1976, אחרי שהגרסה שלה ריגשה אותו, וג׳ף באקלי הקליט את Lilac Wine. זה אלבום שמראה את הכוח שיש בקול שאינו מנסה לרצות.''',
'''הקשיבו ל־Four Women ושימו לב איך כל אחת מהנשים מקבלת בית משלה, ואיך הקול והקצב משתנים עד הצעקה בסוף. ואחר כך, אם יש לכם זמן, שמעו את Wild Is the Wind של בואי.''',
], [
('Four Women', 'ארבע נשים, ארבעה גורלות, ושיר אמיץ וכועס שעדיין מצמרר.'),
('Lilac Wine', 'שיר שקט ורך על אהבה ויין, עם קול שנשמע כמעט כמו לחישה.'),
('Wild Is The Wind', 'שיר אהבה סוער ותאב, ואחד הביצועים הגדולים של סימון.'),
])

add(76, [
'''אסטרוד ז׳ילברטו לא תכננה להיות זמרת. היא הייתה אשתו של ז׳ואאו ז׳ילברטו, והגיעה איתו לאולפן בניו יורק ב־1963, שם שרה במקרה בית אחד באנגלית ב־The Girl from Ipanema (אלבום 41). השיר הפך ללהיט עולמי והיא לכוכבת, והנישואים התפרקו. היא נשארה באמריקה, והמפיק קריד טיילור הקליט איתה אלבום אחרי אלבום. Beach Samba הוקלט בניו יורק בקיץ 1967, בעיבודים של הברזילאי אומיר דאודאטו והאמריקאי דון סבסקי.''',
'''האלבום מחבר בין שני העולמות שלה: שירים ברזילאיים, כמו A Banda של שיקו בוארקי ו־Canoeiro של דוריבל קאימי, ושירי פופ אמריקאיים עדכניים, של טים הארדין ושל The Lovin’ Spoonful, לצד בלדות ישנות כמו My Foolish Heart. הכול עטוף בכלי מיתר, בחלילים ובמקצב בוסה נובה רגוע. הקול של אסטרוד שקט, צלול ומעט מרוחק, כאילו היא שרה לעצמה. ב־Não Bate O Coração היא מפתיעה, ומאלתרת בקול בחופש ובשמחה שכמעט לא נשמעו אצלה בשום מקום אחר.''',
'''מבקרי ג׳אז לא תמיד לקחו את אסטרוד ברצינות, בגלל הקול הקטן והפשוט שלה. אבל בזכותה הבוסה נובה הגיעה למיליוני מאזינים שמעולם לא שמעו ג׳אז, והאלבומים שלה מאותן שנים נשמעים היום כמו פסקול של חופשה. זה תקליט קצר ומרגיע, שמתאים ליום חופשי, ועוזר להבין למה הבוסה נובה כבשה את העולם.''',
'''שמעו את האלבום בבוקר של יום חופש, או בדרך לים. ואם אתם רוצים לשמוע את השורשים, חזרו לאלבום 41, ואחר כך לאלבום 92, של פרנק סינטרה עם ז׳ובים, מאותה שנה.''',
], [
('Stay', 'פתיחה רכה, עם קול צלול ומרוחק ומיתרים שמתנדנדים ברקע.'),
('Beach Samba (Bossa na praia)', 'שיר הכותרת, קצבי וקליל כמו יום על החוף.'),
('Não Bate O Coração', 'שיר של דאודאטו, שבו אסטרוד משתחררת ומאלתרת בקול בשמחה.'),
])

add(77, [
'''ניקו נולדה בגרמניה, הייתה דוגמנית, והופיעה ב־1960 בתפקיד קטן בסרט "לה דולצ׳ה ויטה" של פליני. באמצע שנות השישים היא הגיעה לניו יורק, לסטודיו של האמן אנדי וורהול, והוא צירף אותה כזמרת ללהקה שניהל, הוולווט אנדרגראונד (אלבום 91). אחרי אלבום אחד היא יצאה לדרך משלה, והופיעה במועדון בניו יורק עם גיטריסטים שהתחלפו, ביניהם נער בן 18 מקליפורניה בשם ג׳קסון בראון. Chelsea Girl יצא באוקטובר 1967, בהפקה של טום וילסון, ושמו לקוח מסרט של וורהול שניקו הופיעה בו.''',
'''הקול של ניקו נמוך, קר וכבד, עם מבטא גרמני, והוא נשמע כמו מישהי ששרה מתוך חלום עצוב. את השירים כתבו לה חברים: שלושה של ג׳קסון בראון, ובהם These Days, כמה של חבריה מהוולווט אנדרגראונד, לו ריד וג׳ון קייל, שיר של בוב דילן ושיר של טים הארדין. מעל הגיטרות האקוסטיות הוסיפו כלי מיתר וחלילים. ניקו שנאה את העיבודים האלה: "בכיתי כששמעתי את האלבום", אמרה, "בכיתי בגלל החליל".''',
'''האלבום לא הצליח בזמנו, וניקו עצמה המשיכה לאלבומים קודרים וניסיוניים הרבה יותר. אבל עם השנים Chelsea Girl התגלה מחדש, ו־These Days, שכתב נער בן 16, הפך לקלאסיקה שזמרים רבים הקליטו, ובהם בראון עצמו. דווקא הניגוד בין הקול הקר לבין העיבודים המתוקים הוא שהופך את האלבום לאחד התקליטים העדינים והמוזרים של התקופה.''',
'''שמעו את These Days, ואחר כך את Femme Fatale באלבום 91, שניקו שרה שם עם הוולווט אנדרגראונד. ושימו לב לחליל: האם הוא מפריע לכם, כמו שהפריע לה?''',
], [
('These Days', 'שיר עצוב ובוגר שכתב ג׳קסון בראון כשהיה נער, בקולה העמוק של ניקו.'),
("I'll Keep It With Mine", 'שיר של בוב דילן, שהוא עצמו לא הוציא אז, ונתן לניקו.'),
('Chelsea Girls', 'שיר של לו ריד על מלון צ׳לסי בניו יורק ועל הדמויות שגרו בו.'),
])

add(78, [
'''באוגוסט 1966 הביטלס הופיעו בפעם האחרונה בסיבוב הופעות, ומאז החליטו להתמסר לאולפן בלבד. בנובמבר הם נכנסו לאבי רוד, ובמשך חמישה חודשים, עם המפיק ג׳ורג׳ מרטין, הקליטו את Sgt. Pepper’s Lonely Hearts Club Band. הרעיון של פול מקרטני היה שהאלבום יוצג כהופעה של להקה דמיונית, "להקת הלבבות הבודדים של סמל פפר", כדי שהביטלס יוכלו לעשות כל מה שבא להם. האלבום יצא בסוף מאי 1967, ובתוך כמה ימים הפך לפסקול של "קיץ האהבה".''',
'''האלבום מלא בצלילים חדשים: כלי נגינה הודיים ב־Within You Without You של ג׳ורג׳ הריסון, להקת כלי נשיפה של קרקס ב־Being for the Benefit of Mr. Kite!, קלרינטים ב־When I’m Sixty-Four, תרנגול, קהל וצחוק. יש שירים חלומיים כמו Lucy in the Sky with Diamonds ושירים פשוטים כמו With a Little Help from My Friends, שרינגו שר. ובסוף A Day in the Life, שבו תזמורת של ארבעים נגנים עולה בכאוס מהצליל הנמוך לגבוה, ואקורד פסנתר אחד שמתמשך יותר מחצי דקה עד שנעלם.''',
'''Sgt. Pepper נחשב לאחד האלבומים המשפיעים בהיסטוריה. הוא קבע שאלבום רוק יכול להיות יצירה שלמה, עם עטיפה שהיא יצירת אמנות, עשרות פרצופים של אנשים מפורסמים, ובפעם הראשונה המילים של כל השירים מודפסות על גב העטיפה. הוא היה אלבום הרוק הראשון שזכה בגראמי לאלבום השנה. הוא בא אחרי Revolver (אלבום 60), והושפע מ־Pet Sounds (אלבום 61).''',
'''הקשיבו מההתחלה ועד הסוף, בלי הפסקה ובלי לדלג: השירים עוברים זה לזה כמעט בלי שקט. ושמרו כוח ל־A Day in the Life, בווליום גבוה, עד שהאקורד האחרון נעלם לגמרי.''',
], [
('A Day In The Life', 'סיום גדול, עם תזמורת שעולה בכאוס ואקורד אחרון שנמשך ונמשך.'),
('Lucy In The Sky With Diamonds', 'שיר חלומי עם דימויים צבעוניים, בהשראת ציור של בנו של לנון.'),
('With A Little Help From My Friends', 'רינגו שר שיר שמח ופשוט על חברות, שעובר ישר מהפתיחה.'),
])

add(79, [
'''Country Joe and the Fish נוסדו ב־1965 בברקלי שבקליפורניה, עיר האוניברסיטה שהייתה אז מרכז של מחאה סטודנטית. ג׳ו מקדונלד, שקראו לו "קאנטרי ג׳ו", היה זמר פולק ופעיל פוליטי, והגיטריסט בארי מלטון היה חברו הקרוב. בהתחלה הם הוציאו בעצמם תקליטונים של שירי מחאה, ולאט לאט הפכו ללהקת רוק חשמלית. Electric Music for the Mind and Body הוקלט בברקלי בפברואר 1967 ויצא במאי, כמה שבועות לפני "קיץ האהבה", כאחד מאלבומי הפסיכדליה הראשונים מאזור סן פרנסיסקו.''',
'''האלבום מלא בגיטרות חשמליות מתפתלות, בעוגב מהדהד ובמילים על אהבה, חופש, מסעות תודעה ופוליטיקה. Not So Sweet Martha Lorraine הוא שיר מסתורי על אישה מוזרה, ו־Section 43 הוא קטע אינסטרומנטלי ארוך שמשתנה כל הזמן, כמו מסע. Superbird צוחק על הנשיא האמריקאי לינדון ג׳ונסון, ו־Grace הוא שיר אהבה שקט וחלומי שסוגר את האלבום.''',
'''השיר שעשה את Country Joe and the Fish למפורסמים, שיר המחאה הסרקסטי נגד מלחמת וייטנאם, מופיע באלבום הבא שלהם. בקיץ 1969 מקדונלד שר אותו מול חצי מיליון איש בפסטיבל וודסטוק, ורגע זה הפך לאחד הזכורים של הפסטיבל. אבל האלבום הזה מראה איך נשמעה ברקלי של 1967, בין פוליטיקה לחלום, והוא נחשב לאחד מאלבומי הפסיכדליה הטובים של החוף המערבי.''',
'''שמעו את Section 43 ואחר כך את White Rabbit באלבום 96, של ג׳פרסון איירפליין מסן פרנסיסקו, מאותה שנה: שתי להקות מאותו מפרץ ומאותה שנה, שתי דרכים לנסוע רחוק.''',
], [
('Not So Sweet Martha Lorraine', 'שיר מסתורי עם עוגב, והסינגל היחיד שלהם שנכנס למצעד.'),
('Section 43', 'קטע אינסטרומנטלי ארוך, שמתחלף כל כמה דקות כמו נוף מחלון רכבת.'),
('Grace', 'שיר אהבה שקט וחלומי, שסוגר את האלבום בקול רך.'),
])

add(80, [
'''Buffalo Springfield נוסדו ב־1966 בלוס אנג׳לס, ובחמישה חבריה היו שלושה כותבים מוכשרים: סטיבן סטילס, ניל יאנג הקנדי וריצ׳י פיוריי. בתחילת 1967 היה להם להיט גדול, For What It’s Worth, אבל הלהקה הייתה מלאה במתחים: סטילס ויאנג התחרו זה בזה, הבסיסט גורש מהמדינה, ויאנג עזב וחזר כמה פעמים. את האלבום השני שלהם הקליטו לאורך כמעט כל שנת 1967, לפעמים כל כותב בנפרד עם נגנים אחרים. הוא יצא בסוף אוקטובר 1967.''',
'''כל אחד מהשלושה הביא שירים משלו, וכך יצא אלבום מגוון מאוד. Mr. Soul של יאנג נפתח בריף גיטרה חד ומחוספס. Expecting to Fly, גם שלו, הוא שיר חלומי עם תזמורת מלאה, שהופק עם ג׳ק ניצ׳ה, ובו לא מנגן אף חבר להקה חוץ מיאנג. Bluebird של סטילס מתחיל בגיטרה אקוסטית ומסתיים בסולו רועם, ו־A Child’s Claim to Fame של פיוריי כבר נשמע כמו קאנטרי. ובסוף, Broken Arrow הוא קולאז׳ של צלילים, קהל צורח ופסנתר ג׳אז.''',
'''זה אחד האלבומים שבנו גשר בין פולק, רוק וקאנטרי. הלהקה התפרקה חצי שנה אחרי שיצא, והחברים שלה פיזרו את הרעיונות שלהם לכל עבר: סטילס הקים את Crosby, Stills & Nash עם דייוויד קרוסבי מהבירדס, ויאנג הצטרף אליהם מאוחר יותר ובמקביל התחיל קריירת סולו גדולה. פיוריי הקים את Poco, מהלהקות הראשונות של הקאנטרי־רוק. מתוך הלהקה הקצרה הזאת צמח חלק גדול מהרוק האמריקאי של שנות השבעים.''',
'''שמעו את Mr. Soul ומיד אחריו את Expecting to Fly: אותו כותב, באותו אלבום, ושני קצוות. ואחר כך שמעו את הבירדס באלבום 94, מאותה שנה, שבו מנגן דייוויד קרוסבי, שותפו הבא של סטילס.''',
], [
('Mr. Soul', 'פתיחה חשמלית עם ריף חד ומילים על המחיר של התהילה.'),
('Expecting to Fly', 'שיר עדין עם תזמורת, כמעט חלום. יאנג לבד מול העולם.'),
('Bluebird', 'שיר של סטילס שמתחיל באקוסטית ומסתיים בסולו גיטרות רועם.'),
])

add(81, [
'''Moby Grape נוסדו בסן פרנסיסקו ב־1966, וכבר מההתחלה היו להקה נדירה: חמישה חברים, וכולם כותבים ושרים. הגיטריסט סקיפ ספנס היה קודם המתופף הראשון של ג׳פרסון איירפליין (אלבום 96), ולצדו ניגנו עוד שני גיטריסטים, בסיסט ומתופף. חברת Columbia הגדולה החתימה אותם והוציאה את אלבום הבכורה ביוני 1967, כמה ימים לפני "קיץ האהבה", עם מסע פרסום עצום: באותו יום יצאו גם חמישה סינגלים, עשרה שירים מתוך שלושה־עשר, ובמסיבת ההשקה נשרו מהתקרה אלפי סחלבים סגולים.''',
'''האלבום נשמע כמו כל מה שהיה אפשרי בסן פרנסיסקו של אותה שנה, אבל דחוס ומדויק: שלוש גיטרות שמשוחחות זו עם זו בלי להפריע, הרמוניות של חמישה קולות, ושירים קצרים שנעים בין רוק מהיר, קאנטרי, בלוז ובלדות פולק. Omaha הוא שתי דקות של גיטרות מתנגשות, Hey Grandma קצבי ומלא הומור, ו־8:05 הוא שיר קאנטרי עדין שנשמע כאילו נכתב שנים אחר כך.''',
'''מסע הפרסום פגע בהם: חמישה סינגלים בבת אחת בלבלו את תחנות הרדיו, ואף אחד מהם לא הפך ללהיט גדול. באותו לילה של מסיבת ההשקה שלושה מחברי הלהקה נעצרו, ועל העטיפה אחד מהם עשה תנועה גסה, שנמחקה בהדפסות מאוחרות. בתוך שנה הלהקה התחילה להתפרק. אבל האלבום עצמו נחשב היום לאחד מאלבומי הבכורה הטובים של אותו עשור, ולהקות רבות, מסוף שנות השישים ועד היום, מזכירות אותו כהשראה.''',
'''שמעו את 8:05 ואחר כך את Buffalo Springfield באלבום 80: שתי להקות מקליפורניה שכבר ב־1967 מחפשות את הקאנטרי בתוך הרוק. ואחר כך קפצו לאלבום 96, להקה אחרת מאותה עיר, עם המתופף הקודם של הגרייפ.''',
], [
('Omaha', 'שתי דקות של שלוש גיטרות חשמליות שמתנגשות ומתחברות. הסינגל שהגיע הכי רחוק.'),
('Hey Grandma', 'פתיחה קצבית, מלאת חיים והומור.'),
('8:05', 'שיר קאנטרי עדין על פרידה בשעת בוקר, עם הרמוניות יפות.'),
])

add(82, [
'''Love נוסדו בלוס אנג׳לס ב־1965, בהובלת ארתור לי, מהמנהיגים השחורים הראשונים של להקת רוק לבנה ברובה. במועדונים של סאנסט סטריפ הם היו הלהקה הגדולה בעיר, וחברת Elektra החתימה אותם כלהקת רוק ראשונה שלה. אומרים שג׳ים מוריסון מהדורס (אלבום 93) רצה להגיע לאותה חברה בעיקר בגלל Love. Da Capo, האלבום השני שלהם, יצא בסוף 1966, עם נגן סקסופון וחליל חדש, ומתופף חדש, כשהמתופף הקודם עבר לצ׳מבלו.''',
'''הצד הראשון של התקליט הוא שישה שירים קצרים ושונים לגמרי זה מזה. 7 and 7 Is הוא שתי דקות של תופים מהירים וצעקות, שנגמרות בפיצוץ, וכמעט נשמע כמו פאנק שנים לפני הפאנק. Stephanie Knows Who עוברת בין רוק לג׳אז עם סקסופון, She Comes In Colors רכה וחלומית עם חליל, ו־Orange Skies של בריאן מקלין, הכותב השני בלהקה, כמעט בוסה נובה. הצד השני הוא Revelation, אלתור בלוז של כמעט עשרים דקות, שתפס צד שלם בתקליט.''',
'''Da Capo הוא אחד האלבומים המגוונים של התקופה, וממנו אפשר לשמוע איך להקת גראז׳ קצבית הפכה ליוצרים של משהו עדין ומורכב הרבה יותר. 7 and 7 Is היה הלהיט הכי גדול של הלהקה, והצד הראשון של התקליט הוא הדרך אל Forever Changes (אלבום 87), יצירת המופת שלהם, שיצאה שנה אחר כך.''',
'''הקשיבו לצד הראשון ברצף: שישה שירים, שישה סגנונות. ואת Revelation שמרו לפעם אחרת, כשיש לכם עשרים דקות וסבלנות. ומשם ישר לאלבום 87.''',
], [
('7 and 7 Is', 'שיר עצבני ומהיר, עם תופים מטורפים ופיצוץ בסוף. כמעט פאנק לפני הזמן.'),
('She Comes In Colors', 'שיר רך וחלומי עם חליל וצ׳מבלו.'),
('Stephanie Knows Who', 'רוק שמתחלף לג׳אז ובחזרה, עם סקסופון וצ׳מבלו.'),
])

add(83, [
'''דון ואן פליט גדל במדבר בקליפורניה, והיה חבר ילדות של פרנק זאפה (אלבום 69). השניים הקשיבו יחד לתקליטי בלוז ישנים, ושניהם הפכו לימים לאנשים הכי מוזרים ברוק האמריקאי. באמצע שנות השישים הקים ואן פליט להקה, The Magic Band, והקליט את Safe as Milk ב־1967, עם גיטריסט בן 20 בשם ריי קודר, שגם עזר לעבד את השירים. האלבום יצא באוגוסט 1967, כתקליט הראשון של חברת תקליטים חדשה.''',
'''ביפהארט שר בקול נמוך, גס וחזק, שנע על פני טווח ענק, כמו זמר בלוז מהדלתא שהגיע מכוכב אחר. לפי הסיפור, ב־Electricity הוא צעק כל כך חזק שהמיקרופון היקר באולפן לא עמד בזה. האלבום מחבר בלוז ישן, רוקנרול, ריתם אנד בלוז וצלילים מוזרים, כמו התרמין, הכלי האלקטרוני מסרטי המדע הבדיוני, ב־Electricity. Sure ’Nuff ’n’ Yes, I Do נשען על בלוז קלאסי, Abba Zaba נקרא על שם חטיף אמריקאי, ו־I’m Glad הוא בלדת סול מתוקה, כמעט רגילה.''',
'''זו נקודת המפגש של הבלוז והפסיכדליה, ואולי האלבום הכי נגיש של ביפהארט. באלבומים הבאים הוא המשיך לדרך מוזרה ופראית הרבה יותר, והפך לאחד היוצרים המשפיעים ברוק הניסיוני: מוזיקאים כמו טום ווייטס ולהקות פאנק ופוסט־פאנק רבות אמרו שלמדו ממנו. ריי קודר המשיך לקריירה ארוכה כאחד הגיטריסטים החשובים באמריקה.''',
'''התחילו מ־Sure ’Nuff ’n’ Yes, I Do, ושימו לב כמה הוא קרוב לבלוז של מאדי ווטרס באלבום 29. ואז שמעו את Electricity, ותראו כמה רחוק אפשר לקחת את אותם שורשים.''',
], [
('Electricity', 'שיר מוזר ומסעיר עם תרמין, וקול שכמעט שובר את ההקלטה.'),
("Sure 'Nuff 'n' Yes, I Do", 'הפתיחה, בלוז דלתא עם גיטרת סלייד, שמתחיל כמו שיר ישן ומשתגע לאט.'),
('Abba Zaba', 'שיר מקפץ על חטיף אמריקאי, עם תופים מתגלגלים והומור מוזר.'),
])

add(84, [
'''The Beau Brummels הגיעו מסן פרנסיסקו, ובחרו שם שנשמע בריטי בכוונה, כדי ליהנות מהפלישה הבריטית. ב־1965, כמה חודשים אחרי ההופעה הראשונה שלהם, הגיע השיר Laugh, Laugh למקום ה־15 במצעד האמריקאי. המפיק שלו היה צעיר בשם סילבסטר סטיוארט, שנודע אחר כך בשם סליי סטון. עד 1967 הלהקה כבר הצטמצמה לשלושה חברים, והם עברו לחברת Warner. Triangle יצא ביולי 1967, בהפקה של לני וורונקר, עם עיבודי מיתרים של ואן דייק פארקס ונגני אולפן מקצועיים.''',
'''הצליל כאן רך, מוזר ומלא דמיון: גיטרות אקוסטיות, מיתרים וצ׳מבלו, וקולו העמוק והנוגה של סאל ולנטינו. בפעם הראשונה ולנטינו והגיטריסט רון אליוט כתבו יחד, והשירים שלהם מלאים בדמויות מאגדות: צייר של נשים, שומר הזמן, זאב של מזל. Magic Hollow שקט וחלומי, Are You Happy? פותח בעדינות, ו־Nine Pound Hammer, שיר עבודה עממי ישן, מקבל עיבוד כפרי שמרמז על מה שיבוא.''',
'''Triangle לא נמכר כמעט, והלהקה נשכחה למדי, אבל האלבום נחשב היום לאחד היפים והמוזרים של 1967. באלבום הבא הם נסעו לנאשוויל והקליטו תקליט קאנטרי־רוק, מהראשונים מסוגו. כך הם שייכים לאותה משפחה של להקות קליפורניה, כמו Buffalo Springfield (אלבום 80) והבירדס, שחיפשו את הדרך מהפולק־רוק אל הקאנטרי.''',
'''שמעו את האלבום בערב, בשקט, כמו ספר אגדות קצר. ואם אהבתם את הקסם המוזר שלו, עברו לאלבום 87, של Love, שיצא כמה חודשים אחר כך ומשתמש בכלי מיתר וכלי נשיפה באותה עדינות.''',
], [
('Are You Happy?', 'פתיחה עדינה עם קול מלא רגש ושאלה פשוטה.'),
('Magic Hollow', 'שיר חולמני עם צ׳מבלו ומיתרים.'),
('Nine Pound Hammer', 'שיר עבודה עממי ישן, בעיבוד כפרי ורך.'),
])

add(85, [
'''המונקיז נוצרו ב־1966 בשביל סדרת טלוויזיה: מפיקים חיפשו ארבעה צעירים שישחקו להקה בנוסח הביטלס, ומצאו שני שחקנים ושני מוזיקאים. הסדרה הצליחה מאוד, והתקליטים עוד יותר, אבל את המוזיקה ניגנו נגני אולפן, ושירים נבחרו בלי לשאול אותם. בתחילת 1967 הארבעה מרדו: הם התעקשו לנגן בעצמם ולבחור את השירים, ובסוף גם הצליחו להדיח את המנהל המוזיקלי שלהם. Headquarters, שיצא במאי 1967, הוא האלבום הראשון שבו ניגנו כמעט את הכול בעצמם.''',
'''האלבום נשמע חברי, קליל ופחות מלוטש מהלהיטים הקודמים שלהם, כמו להקה שמנגנת בחדר אחד. מייקל נסמית׳ תורם שירים בסגנון קאנטרי, כמו You Just May Be the One ו־Sunny Girlfriend, פיטר טורק כתב את For Pete’s Sake, ומיקי דולנץ כתב את Randy Scouse Git, שיר מוזר ושמח בהשראת ביקור בלונדון ומסיבה עם הביטלס. Shades of Gray הוא בלדה מלנכולית שכתבו מאן ווייל, אותם כותבים של Kicks (אלבום 68).''',
'''Headquarters הגיע למקום הראשון במצעד האמריקאי, ושבוע אחר כך הדיח אותו Sgt. Pepper (אלבום 78). זה סיפור על להקה שנולדה כמוצר של טלוויזיה ורצתה להיות אמיתית, והצליחה לפחות לתקליט אחד. מבקרים לא לקחו אותם ברצינות אז, אבל היום רבים רואים באלבום הזה פופ מצוין של 1967, ובמונקיז להקה טובה בהרבה ממה שחשבו.''',
'''שמעו את Randy Scouse Git ואת You Just May Be the One ברצף: שני כותבים, אותה להקה, ושני כיוונים שונים לגמרי. ואם אתם רוצים לשמוע את השיר המפורסם שהמונקיז לקחו מלהקה אחרת, חזרו ל־I’m Not Your Stepping Stone באלבום 68.''',
], [
('Randy Scouse Git', 'שיר מוזר ושמח של מיקי דולנץ, בהשראת ביקור בלונדון.'),
('Shades of Gray', 'בלדה מלנכולית ועדינה על כך שהעולם כבר לא שחור ולבן.'),
("For Pete's Sake", 'שיר של פיטר טורק על אהבה ושלום, שליווה את סוף פרקי הטלוויזיה.'),
])

add(86, [
'''טים באקלי גדל בקליפורניה, והתחיל לשיר במועדוני פולק בלוס אנג׳לס כשהיה עוד בתיכון. ב־1966, בגיל 19, הוא כבר חתם בחברת Elektra והוציא אלבום ראשון. Goodbye and Hello, האלבום השני, יצא באוגוסט 1967, כשהיה בן 20. את רוב המילים כתב חברו מבית הספר, המשורר לארי בקט, ובאקלי הלחין ושר. באותה תקופה באקלי כבר היה אב לתינוק, שכמעט לא הכיר: ג׳ף באקלי, שהפך שנים אחר כך בעצמו לזמר מפורסם.''',
'''הקול של באקלי הוא הדבר המרכזי: טווח עצום, מנמוך ורך עד צעקה גבוהה, והוא משתמש בו ככלי נגינה, מתנדנד, מתאבל ומתפוצץ. סביבו גיטרות אקוסטיות, צ׳מבלו, כלי הקשה ועיבודים עשירים וחלומיים. No Man Can Find the War הוא שיר מחאה נגד מלחמה, Pleasant Street קודר ועצבני, ושיר הכותרת, ארוך ומבני, מחליף בין שני עולמות: "שלום" של הדור הצעיר מול "להתראות" לעולם הישן. Morning Glory, בסוף, הוא שיר עדין על נווד.''',
'''זה אחד האלבומים היפים והשאפתניים של 1967, בין פולק לפסיכדליה, והוא מראה זמר שלא מפחד להשתנות. באקלי המשיך לשנות סגנון כמעט בכל אלבום, מג׳אז ועד סול, ומת ב־1975, בגיל 28. הקול שלו השפיע על זמרים רבים, ובנו ג׳ף הלך בדרכו.''',
'''שמעו את Morning Glory, ואז חזרו לפרד ניל באלבום 62: באקלי למד ממנו הרבה, והקליט לימים את The Dolphins. ואם אהבתם את הקול, חפשו גם את ג׳ף באקלי, שנשמע לפעמים כמעט כמו אביו.''',
], [
('Morning Glory', 'שיר עדין ומרגש על נווד שמבקש מקום לנוח בו.'),
('Pleasant Street', 'שיר קודר ועצבני, עם קול שמטפס ומתפוצץ.'),
('Goodbye and Hello', 'שיר הכותרת, ארוך ומרחף, שבו העולם הישן והחדש מתחלפים שורה אחרי שורה.'),
])

add(87, [
'''בשנת 1967 Love היו מהלהקות הגדולות של לוס אנג׳לס (אלבום 82), אבל כמעט לא יצאו ממנה להופעות, והמצב בתוך הלהקה היה קשה: ויכוחים, סמים, ונגנים שלא הגיעו לחזרות. ארתור לי, בן 22, היה משוכנע שהוא הולך למות בקרוב, והשירים שכתב מלאים במחשבות על מוות, על פחד ועל אכזבה מהאידיאלים של "קיץ האהבה". בתחילת ההקלטות המפיק הביא נגני אולפן לשני שירים, וזה זעזע את הלהקה מספיק כדי שתחזור ותנגן את השאר בעצמה. Forever Changes יצא בנובמבר 1967.''',
'''הגיטרות האקוסטיות מתחברות לכלי מיתר ולחצוצרות בעיבודים של דייוויד אנג׳ל, והכול נשמע רך, יפה ומוזר, כמו חלום שמתחיל להיות מפחיד. Alone Again Or, של בריאן מקלין, נפתח בגיטרה אקוסטית, ופורץ בחצוצרה בסגנון מקסיקני. The Red Telephone הוא שיר מוזר ומאיים, שבו לי שר שורות על מלחמה ועל חופש, ו־You Set the Scene, בסוף, הוא סיכום של כל האלבום, כמעט כמו תפילה. המילים מלאות בדימויים מבלבלים ויפים.''',
'''בזמנו האלבום כמעט לא נמכר באמריקה, והצליח קצת יותר בבריטניה. אבל עם השנים הוא התגלה מחדש, ורבים מחשיבים אותו היום לאחד האלבומים הגדולים של שנות השישים. זה אולי האלבום הכי יפה והכי עצוב שנוצר ב־1967: בזמן שכולם שרו על אהבה ושמש, ארתור לי ראה את הצל.''',
'''הקשיבו ברצף, בשעה שקטה. והשוו את Alone Again Or ל־She Comes In Colors באלבום 82: אותה להקה, שנה אחת, ועולם שלם של עיבודים שנוסף בינתיים.''',
], [
('Alone Again Or', 'הפתיחה, עם גיטרה אקוסטית וחצוצרות מקסיקניות. השיר המפורסם ביותר שלהם.'),
('The Red Telephone', 'שיר מחשיך ומוזר על פחד, מלחמה וחופש.'),
('You Set the Scene', 'סיום ארוך ומרגש, עם כלי נשיפה ומיתרים, כמעט כמו תפילה.'),
])

add(88, [
'''Cream נוסדו בלונדון ב־1966, ונחשבים לאחת מ"להקות העל" הראשונות: שלושה נגנים שכל אחד מהם כבר היה כוכב. אריק קלפטון בגיטרה (אלבום 73), ג׳ק ברוס בבס ובשירה, וג׳ינג׳ר בייקר בתופים. ברוס ובייקר שנאו זה את זה עוד מלהקה קודמת, וזה נשמע במתח שבנגינה. באביב 1967 הם טסו לניו יורק והקליטו את Disraeli Gears בכמה ימים בלבד, עם המפיק פליקס פאפאלרדי. השם הוא בדיחה: אחד מאנשי הצוות התבלבל בין "הילוכי דריילר" של אופניים לבין בנג׳מין דיזרעאלי, ראש ממשלת בריטניה בעבר.''',
'''האלבום מחבר בלוז, פסיכדליה ורוק חזק. Sunshine of Your Love נפתח בריף של ג׳ק ברוס, שהגיטרה והבס מנגנים יחד, והפך לאחד המפורסמים בתולדות הרוק. ב־Tales of Brave Ulysses קלפטון מנגן עם דוושת וואה־וואה, שגורמת לגיטרה "לדבר", וב־Strange Brew הוא מחקה את הבלוזמנים שאהב. חלק גדול מהמילים כתב המשורר פיט בראון, והקול העמוק של ברוס נותן להן עוצמה. גם העטיפה, קולאז׳ צבעוני וזוהר, הפכה לסמל של התקופה.''',
'''זה אחד האלבומים שהביאו לרוק את הגיטרה הכבדה והמגברים החזקים, ואת ההופעות שבהן כל שיר הופך לאלתור ארוך. Cream התפרקו כבר ב־1968, אחרי שנתיים וחצי בלבד, אבל הם השפיעו על כמעט כל להקת רוק כבד שבאה אחריהם. באותה שנה ממש, ג׳ימי הנדריקס (אלבום 100) לקח את הגיטרה עוד צעד קדימה.''',
'''שמעו את Sunshine of Your Love, ואחר כך את Purple Haze באלבום 100, מאותה שנה: שני ריפים ששינו את הרוק. והשוו את קלפטון כאן לקלפטון של אלבום 73, רק שנה קודם.''',
], [
('Sunshine of Your Love', 'אחד הריפים המפורסמים ביותר בתולדות הרוק. הקשיבו גם לתופים של בייקר, שמנגנים קצב מפתיע ושבטי.'),
('Strange Brew', 'בלוז עוקצני עם שירה גבוהה וגיטרה בנוסח הבלוזמנים הוותיקים.'),
('Tales of Brave Ulysses', 'שיר חלומי על המסע של אודיסאוס, עם גיטרת וואה־וואה.'),
])

add(89, [
'''פינק פלויד נוסדו בלונדון באמצע שנות השישים, והשם שלהם לקוח משמותיהם של שני זמרי בלוז אמריקאים לא מוכרים. את הלהקה הוביל הגיטריסט והכותב סיד בארט, צעיר כריזמטי מקיימברידג׳ עם דמיון פרוע. ב־1967 הם היו הלהקה של המחתרת הפסיכדלית של לונדון, עם הופעות רועשות ומופעי אור. The Piper at the Gates of Dawn הוקלט באולפני אבי רוד, באותם חודשים שבהם הביטלס הקליטו בחדר ליד את Sgt. Pepper (אלבום 78). שמו לקוח מפרק בספר הילדים "הרוח בערבי הנחל".''',
'''האלבום מלא בדמיון: שירים על חלל ועל כוכבים, כמו Astronomy Domine, לצד שירים של אגדות ילדים אנגליות, על גמד בשם גרימבל, על דחליל, ועל חתול בשם סאם. בארט שר בקול צלול ובמבטא אנגלי מובהק, והלהקה מקיפה אותו בגיטרות מהדהדות, עוגב משונה ותופים מתגלגלים. Interstellar Overdrive הוא אלתור של כמעט עשר דקות שיוצא לחלל ונעלם, ו־Bike, בסוף, הוא שיר אהבה ילדותי שמסתיים באוסף מבהיל של רעשים.''',
'''זה האלבום היחיד שבו בארט הוא הכוח המוביל של הלהקה. מצבו הנפשי, שהחמיר כנראה גם בגלל שימוש כבד בסמים, הידרדר במהירות, ובתחילת 1968 הוא נאלץ לעזוב. דייוויד גילמור, חבר ילדות, נכנס במקומו, ופינק פלויד הפכה בשנות השבעים לאחת הלהקות הגדולות בעולם. הם לא שכחו אותו: כמה משיריהם המפורסמים נכתבו עליו. כאן נשמע הקסם הראשון, המוזר והילדותי.''',
'''שמעו את The Gnome ואת Interstellar Overdrive ברצף: שני הקצוות של בארט. ואחר כך עברו לאלבום 78, שהוקלט בחדר הסמוך באותם חודשים, והשוו.''',
], [
('Astronomy Domine', 'פתיחה גדולה עם קולות מרחפים ומילים על כוכבים וירחים.'),
('Interstellar Overdrive', 'אלתור ארוך שיוצא לחלל. הקשיבו לריף שבפתיחה, ולאיך הכול מתפרק ונבנה מחדש.'),
('Bike', 'שיר אהבה ילדותי ומצחיק, שמסתיים ברעשים מוזרים.'),
])

add(90, [
'''בבריטניה של אמצע שנות השישים הרדיו הממלכתי השמיע מעט מאוד רוק, והצעירים הקשיבו לתחנות רדיו "פיראטיות" ששידרו מספינות בים, מחוץ למים הטריטוריאליים, עם פרסומות, ג׳ינגלים וכל להיט חדש. באוגוסט 1967 הממשלה הוציאה אותן מחוץ לחוק. The Who, שגדלו על התחנות האלה, החליטו להקדיש להן את האלבום השלישי שלהם: The Who Sell Out, שיצא בדצמבר 1967, בנוי כמו שידור של תחנה כזאת, עם פרסומות מדומות וג׳ינגלים אמיתיים בין השירים.''',
'''הפרסומות, כמו Heinz Baked Beans ו־Odorono, על דאודורנט, הן חלק מהמוזיקה, מצחיקות ומוזרות. ובין הפרסומות, השירים: I Can See for Miles, אחד הרגעים החזקים והרועשים של הלהקה, Armenia City in the Sky, שנפתח בצלילים הפוכים, ו־Tattoo, שיר מצחיק ורגיש על שני אחים שעושים קעקועים. גם העטיפה היא פרסומת: כל חבר בלהקה מצטלם עם מוצר, ורוג׳ר דלטרי יושב באמבטיה מלאה בשעועית אפויה. בסוף יש Rael, אופרת רוק קטנה של שש דקות.''',
'''I Can See for Miles היה הלהיט הגדול ביותר של The Who באמריקה, אבל פיט טאונשנד התאכזב שהוא לא הצליח עוד יותר. הוא חשב שזה השיר הטוב ביותר שכתב. האלבום מראה איך טאונשנד מתחיל לחשוב על אלבום כעל יצירה שלמה, עם רעיון מרכזי, והקטע Rael הוא טיוטה ראשונה לאופרת הרוק הגדולה Tommy, שיצאה שנה וחצי אחר כך.''',
'''השוו לאלבום 59, שנתיים קודם: אותה להקה, אבל עכשיו עם הומור, רעיון ואולפן. ושמעו את I Can See for Miles בווליום גבוה, כמו שטאונשנד רצה.''',
], [
('I Can See for Miles', 'שיר עוצמתי ורועם, ההצלחה הגדולה של הלהקה בארצות הברית.'),
('Armenia City in the Sky', 'פתיחה מוזרה עם צלילים הפוכים, בשיר שכתב חבר של הלהקה.'),
('Tattoo', 'שיר מצחיק ורגיש על שני אחים שמנסים להיות גברים בעזרת קעקוע.'),
])

add(91, [
'''The Velvet Underground נוסדו בניו יורק ב־1965 סביב שני אנשים שונים מאוד: לו ריד, כותב שירים שעבד כמלחין מקצועי בחברת תקליטים זולה ואהב רוקנרול וספרות, וג׳ון קייל, מוזיקאי קלאסי מוויילס שניגן במוזיקה אוונגרדית ניסיונית. לצדם הגיטריסט סטרלינג מוריסון והמתופפת מורין טאקר, שניגנה בעמידה, על תופים פשוטים. האמן אנדי וורהול אימץ אותם, הפך אותם ללהקה של הסטודיו שלו, וצירף אליהם את הזמרת הגרמנייה ניקו (אלבום 77). האלבום הוקלט ב־1966 ויצא במרץ 1967, עם עטיפת הבננה המפורסמת שצייר וורהול.''',
'''השירים מדברים על דברים שהרוק לא דיבר עליהם אף פעם: I’m Waiting for the Man הוא על בחור שמחכה לסוחר סמים בהארלם, Heroin מתאר את הסם מבפנים, בלי שיפוט, כשהמוזיקה מאיצה ומאטה עם הדופק, ו־Venus in Furs הוא על יחסים של כאב ושליטה. הצליל גולמי ומוזר: גיטרות מעוותות, הוויולה החשמלית של קייל שמשמיעה צליל צורם ומתמשך, ותופים חזרתיים. ולצד כל זה יש שירים עדינים ויפים כמו Sunday Morning, ו־Femme Fatale ו־I’ll Be Your Mirror בקולה העמוק של ניקו.''',
'''בזמנו האלבום כמעט לא נמכר, ותחנות הרדיו סירבו להשמיע אותו. אבל שנים אחר כך בריאן אינו, מוזיקאי ומפיק בריטי, אמר את המשפט המפורסם: רק כמה עשרות אלפי אנשים קנו אותו, אבל כל אחד מהם הקים להקה. הפאנק, הרוק האלטרנטיבי והאינדי צמחו במידה רבה מהתקליט הזה. ובאותה שנה שבה הביטלס הוציאו את Sgt. Pepper (אלבום 78), הוא הראה צד אחר לגמרי של 1967: עירוני, קר וכן.''',
'''שמעו את Sunday Morning ואז מיד את Heroin: שני הקצוות של אותו אלבום. ואם אהבתם את קולה של ניקו, המשיכו לאלבום 77, שבו לו ריד וג׳ון קייל כותבים לה שירים.''',
], [
('Heroin', 'שיר ארוך ומהפנט על התמכרות, שבו הקצב מאיץ ומאט כמו דופק.'),
('Femme Fatale', 'שיר עדין על אישה מסוכנת, בקולה העמוק של ניקו.'),
('Sunday Morning', 'הפתיחה: שיר רך ומנומנם עם צלסטה מצלצלת, שמסתיר מתחתיו מתח.'),
])

add(92, [
'''בסוף 1966 פרנק סינטרה, בן 51, היה עדיין אחד הזמרים הגדולים בעולם (אלבומים 1 ו־7), אבל בעולם שהביטלס שלטו בו הוא כבר חיפש כיוונים חדשים. הבוסה נובה, שכבשה את אמריקה בשנים שלפני כן (אלבומים 33 ו־41), נתנה לו כיוון. הוא הזמין את אנטוניו קרלוס ז׳ובים, המלחין הברזילאי של רוב שירי הבוסה נובה המפורסמים, להקליט איתו. בסוף ינואר ובתחילת פברואר 1967, באולפן בהוליווד, הם הקליטו את האלבום, עם תזמורת בעיבוד ובניצוח של קלאוס אוגרמן. הוא יצא במרץ.''',
'''סינטרה שר כאן כמעט בלחישה, ברכות ובאיפוק שלא נשמעו אצלו קודם. "לא שרתי כל כך בשקט מאז שהייתה לי דלקת גרון", התבדח. ז׳ובים מנגן בגיטרה בקצב הבוסה נובה, ולפעמים שר איתו בפורטוגזית, והעיבודים של אוגרמן, עם כלי מיתר וחליל, שקטים כמו רוח בערב. יש כאן עשרה שירים בלבד, פחות מחצי שעה: שירים של ז׳ובים, כמו The Girl from Ipanema, Dindi ו־Quiet Nights of Quiet Stars, לצד שלושה שירים אמריקאיים ישנים שמקבלים את אותו טיפול.''',
'''זה אלבום של אינטימיות: שני אמנים גדולים שלא ממהרים לשום מקום. הוא היה מועמד לפרס הגראמי לאלבום השנה, והפסיד ל־Sgt. Pepper (אלבום 78). רבים רואים בו את אחת ההקלטות היפות של סינטרה בשנים המאוחרות, והוא הוכיח שגם זמר מהדור הישן יכול ללמוד שפה מוזיקלית חדשה, ולשיר אותה כאילו נולד בה.''',
'''שמעו את The Girl from Ipanema כאן, ואז באלבום 41, שלוש שנים קודם: אותו שיר, אותו מלחין, אבל פעם עם אסטרוד הצעירה ופעם עם סינטרה המבוגר. ואחר כך חזרו לאלבום 1, וחשבו כמה רחוק הגיע סינטרה בשתים־עשרה שנה.''',
], [
('The Girl From Ipanema', 'הגרסה השקטה והאינטימית של השיר המפורסם, עם ז׳ובים שמצטרף בפורטוגזית.'),
('Dindi', 'שיר געגוע עדין לאישה, שסינטרה שר ברוך רב.'),
('Quiet Nights of Quiet Stars', 'שיר לילה שקט ורך, וגרסה אמריקאית ל־Corcovado מאלבום 41.'),
])

add(93, [
'''The Doors נוסדו בלוס אנג׳לס ב־1965, כשריי מנזרק, קלידן שלמד קולנוע באוניברסיטה, פגש בחוף ונציה את חברו ללימודים ג׳ים מוריסון, משורר צעיר, ושמע אותו שר שירים שכתב. הם צירפו את המתופף ג׳ון דנסמור ואת הגיטריסט רובי קריגר, ולקחו את השם מספר של אלדוס האקסלי על "דלתות התפיסה". לא היה להם בסיסט: מנזרק ניגן את קווי הבס ביד שמאל, על פסנתר בס קטן. את אלבום הבכורה הקליטו בשישה ימים בלבד באוגוסט 1966, והוא יצא בינואר 1967.''',
'''הצליל של The Doors לא דומה לשום להקה אחרת של אותה תקופה: עוגב מצלצל ומסתורי, גיטרה שנעה בין בלוז לפלמנקו, תופים בהשפעת ג׳אז, ומעל הכול הקול העמוק והדרמטי של מוריסון. האלבום נפתח ב־Break On Through, קצבי ודוחף, וכולל את Light My Fire, שכתב בעיקר קריגר, עם סולו עוגב וסולו גיטרה ארוכים. Alabama Song הוא שיר מאופרה גרמנית של ברכט ווייל משנות העשרים, ו־The End, בסוף, הוא יצירה של כמעט שתים־עשרה דקות, אפלה ומפחידה, שבה מוריסון מדקלם יותר משהוא שר.''',
'''גרסה מקוצרת של Light My Fire הגיעה בקיץ 1967 למקום הראשון במצעד האמריקאי, והפכה את The Doors ללהקה מפורסמת. זה אלבום שהראה שאפשר לשלב רוק, בלוז, ג׳אז, שירה ותיאטרון. מבחינה מסוימת הוא ההיפך מ"קיץ האהבה" המחייך: אפל, מסתורי ומסוכן. מוריסון מת בפריז ב־1971, בגיל 27, והמיתוס סביבו רק גדל מאז.''',
'''שמעו את Light My Fire בגרסה המלאה, והקשיבו לסולו העוגב ולסולו הגיטרה באמצע: זה החלק שנחתך בגרסת הרדיו. ואחר כך שמעו את 7 and 7 Is באלבום 82, של Love, הלהקה שבזכותה, לפי הסיפור, הגיעו The Doors לאותה חברת תקליטים.''',
], [
('Light My Fire', 'שיר עם סולו עוגב ארוך, ואחד הלהיטים הגדולים של 1967.'),
('Break On Through (To The Other Side)', 'פתיחה קצבית ודוחפת, עם תופים בקצב לטיני.'),
('The End', 'סיום אפל ודרמטי של כמעט שתים־עשרה דקות, כמו טקס.'),
])

add(94, [
'''בתחילת 1967 הבירדס כבר היו בלי ג׳ין קלארק (אלבום 63), ובלי להיטים גדולים כמו בהתחלה. אבל מתוך המשבר צמחו שני כותבים חדשים: דייוויד קרוסבי, שהביא שירים חלומיים ופוליטיים, והבסיסט כריס הילמן, שהגיע מעולם הבלוגראס והתחיל לכתוב שירים משלו, בהשפעת הקאנטרי. Younger Than Yesterday יצא בפברואר 1967. שמו נולד בהשראת שורה מתוך השיר של בוב דילן My Back Pages, שהלהקה הקליטה באלבום.''',
'''האלבום נפתח ב־So You Want to Be a Rock ’n’ Roll Star, שיר עוקצני על תעשיית המוזיקה ועל להקות שנוצרות בן לילה, עם חצוצרה של הנגן הדרום אפריקאי יו מסקלה וצרחות של מעריצות שהוקלטו בהופעה אמיתית של הבירדס באנגליה. Have You Seen Her Face ו־Time Between של הילמן כבר נשמעים כמו קאנטרי־רוק, Everybody’s Been Burned של קרוסבי הוא בלדה עצובה בנוסח ג׳אז, ו־C.T.A.-102 הוא שיר מצחיק על מסר מחייזרים בחלל, עם צלילים אלקטרוניים.''',
'''בזמנו האלבום מכר פחות מקודמיו, אבל היום רבים רואים בו את אחד הטובים של הבירדס. הוא מאחד פולק, רוק, פסיכדליה וקאנטרי, ומראה להקה שמתפרקת ובונה את עצמה מחדש. קרוסבי פוטר מהלהקה באותה שנה והקים את Crosby, Stills & Nash, והילמן עזר להוביל את הבירדס אל הקאנטרי.''',
'''שמעו את שלושת האלבומים של הבירדס באתר ברצף: 57, 63 ו־94. שלוש שנים, שלוש להקות שונות. ואחרי My Back Pages, חזרו לדילן עצמו באלבום 64 משנת 1966.''',
], [
("So You Want to Be a Rock 'n' Roll Star", 'שיר עוקצני על תעשיית המוזיקה, עם חצוצרה וצרחות של מעריצות.'),
('My Back Pages', 'גרסה מרגשת לשיר של דילן, שממנו לקוח שם האלבום.'),
("Everybody's Been Burned", 'שיר עדין ועצוב של דייוויד קרוסבי, עם בס שמתפתל כמו בג׳אז.'),
])

add(95, [
'''The Young Rascals נוסדו בניו יורק ב־1965: שני זמרים וכותבים, פליקס קוואליירי, שניגן גם בעוגב, ואדי בריגאטי, לצד הגיטריסט ג׳ין קורניש והמתופף דינו דנלי. ארבעה צעירים לבנים מאזור ניו יורק שאהבו סול וריתם אנד בלוז שחור, ושרו אותו בלהט אמיתי. הם חתמו בחברת Atlantic, הבית של ריי צ׳רלס וסולומון בורק (אלבומים 20 ו־44), והיו מהלהקות הלבנות הראשונות שהצליחו גם אצל קהל שחור. Groovin’ יצא ביולי 1967.''',
'''שיר הכותרת, Groovin’, שונה מכל מה שעשו קודם: בלי עוגב, בלי גיטרות חשמליות ובלי תופים. רק קונגה, בס, מפוחית וציוץ ציפורים, ושיר על אחר צהריים עצלן של יום ראשון. הוא הגיע למקום הראשון במצעד האמריקאי במאי 1967. שאר האלבום מלא בעוגב חם וקולות מתוקים: How Can I Be Sure הוא בלדה מתוקה ועצובה בנוסח ואלס צרפתי, A Girl Like You קצבי וקליל, ו־You Better Run הוא רוק־סול חזק ומהיר. הצליל נקי ושמח, כמו יום שבת בקיץ.''',
'''בשנה שבה כולם הלכו לפסיכדליה, הרסקלס נשארו נאמנים לסול ולשמחה. הם גם עמדו מאחורי מה שהאמינו בו: הם סירבו להופיע באירועים מופרדים, ודרשו שלהקה שחורה תופיע איתם בכל ערב, החלטה שעלתה להם בהופעות רבות בדרום. זה אלבום שמאפשר לשמוע צד אחר של 1967, נעים ואופטימי.''',
'''שמעו את Groovin’ בבוקר של יום חופש. ואחר כך את Respect של אוטיס רדינג באלבום 51, ותשמעו מאיפה הרסקלס למדו לשיר.''',
], [
("Groovin'", 'שיר קליל ומרגיע על אחר צהריים של יום ראשון, בלי תופים, עם קונגה וציפורים.'),
('How Can I Be Sure', 'בלדה מתוקה ועצובה בקצב של ואלס.'),
('You Better Run', 'רוק־סול מהיר וחזק, עם עוגב שדוחף קדימה.'),
])

add(96, [
'''Jefferson Airplane נוסדו בסן פרנסיסקו ב־1965 סביב הזמר מרטי באלין, והיו הלהקה הראשונה מהסצנה החדשה של העיר שחתמה בחברת תקליטים גדולה. בסוף 1966 הצטרפה אליהם גרייס סליק, דוגמנית לשעבר עם קול חזק ובטוח, שהגיעה מלהקה אחרת בעיר והביאה איתה שני שירים: Somebody to Love, שכתב גיסה, ו־White Rabbit, שכתבה בעצמה. Surrealistic Pillow יצא בפברואר 1967. ג׳רי גרסיה, מנהיג הגרייטפול דד, עזר בהקלטות, וקיבל בקרדיט את התואר "יועץ מוזיקלי ורוחני".''',
'''Somebody to Love הוא שיר של תשוקה וכעס, והקול של סליק חותך דרכו כמו סכין. White Rabbit מתחיל בשקט, בקצב של בולרו ספרדי, ומטפס לאט, עם מילים על עליסה בארץ הפלאות, עד שהוא מתפרץ בסוף. סביב שני הלהיטים האלה השירים רכים ופולקיים, עם הרמוניות של שלושה קולות: Today היא בלדה עדינה של באלין, ו־Embryonic Journey הוא קטע קצר לגיטרה אקוסטית בלבד של הגיטריסט יורמה קאוקונן.''',
'''שני השירים של סליק הגיעו לעשירייה הראשונה במצעד האמריקאי, והלהקה הפכה לקול של סן פרנסיסקו בשנת "קיץ האהבה". זה אחד האלבומים שהגדירו את הצליל של העיר בשנה ההיא: פולק שהפך לרוק, עם גיטרות חשמליות, מילים על חופש ועל תודעה, וקול נשי חזק שלא נשמע קודם ברוק. גרייס סליק הפכה לאחת הזמרות המשפיעות של הרוק.''',
'''שמעו את White Rabbit, ועקבו אחרי הדרך שבה השיר נבנה לאט, תו אחרי תו, עד הסוף. ואחר כך שמעו את The Fat Angel של דונובן באלבום 98, שמזכיר את ג׳פרסון איירפליין בשמם עוד לפני שהתפרסמו.''',
], [
('Somebody to Love', 'שיר חזק ונחוש, שבו הקול של גרייס סליק חותך את הגיטרות.'),
('White Rabbit', 'שיר מסתורי על עליסה, שנבנה לאט כמו בולרו ומתפרץ בסוף.'),
('Embryonic Journey', 'קטע קצר ויפה לגיטרה אקוסטית בלבד.'),
])

add(97, [
'''בשנת 1967 ריי דייוויס, מנהיג הקינקס (אלבום 66), כתב אלבום שהתעלם לגמרי מהאופנות של אותה שנה. בזמן שהביטלס ופינק פלויד טסו לחלל, הוא כתב על אנגליה הקטנה והיומיומית: תה של אחר הצהריים, בית ספר, משפחה ועבודה. באותה תקופה הקינקס גם לא יכלו להופיע באמריקה, בגלל איסור של איגוד המוזיקאים שם אחרי סיבוב הופעות סוער, ואולי זה רק קירב אותם לבריטניה. Something Else by The Kinks יצא בספטמבר 1967, וריי לקח על עצמו חלק גדול מההפקה.''',
'''השירים מציירים דמויות ותמונות, עם הרבה חמלה ועוקץ: David Watts הוא על נער מושלם בבית הספר שכולם מקנאים בו, Two Sisters הוא על שתי אחיות, אחת נשואה ועייפה ואחת חופשייה, ו־Death of a Clown, שכתב ושר האח הצעיר דייב דייוויס, הוא על ליצן עצוב שנמאס לו. ובסוף, Waterloo Sunset: אדם מסתכל מחלון על השקיעה מעל גשר בלונדון ועל זוג צעיר שנפגש שם, ומרגיש שלם, אפילו לבדו.''',
'''Waterloo Sunset הגיע למקום השני בבריטניה, אבל האלבום עצמו לא נמכר טוב, ובאמריקה כמעט לא שמעו עליו. היום הוא נחשב לאחד הטובים של הלהקה, ו־Waterloo Sunset לאחד השירים היפים ביותר שנכתבו על לונדון, ואולי על עיר בכלל. ריי דייוויס הראה שרוק יכול לספר סיפורים קטנים ואנושיים, ולהקות בריטיות רבות, מהג׳אם ועד בלר, הלכו בדרכו.''',
'''שמרו את Waterloo Sunset לסוף היום, אולי אפילו לשקיעה. ואחר כך השוו את David Watts ל־Dandy באלבום 66: עוד דיוקן של בחור שכולם מסתכלים עליו.''',
], [
('Waterloo Sunset', 'שיר שקט ויפהפה על לונדון ועל שקיעה, מהשירים הגדולים של שנות השישים.'),
('David Watts', 'שיר קצבי על נער מושלם שכולם מקנאים בו.'),
('Death of a Clown', 'שיר של דייב דייוויס על ליצן עייף, עם צ׳מבלו ושירה בציבור.'),
])

add(98, [
'''דונובן לייץ׳ נולד בגלזגו וגדל ליד לונדון, ובגיל 18, ב־1965, כבר הופיע בטלוויזיה הבריטית עם גיטרה, מפוחית וכובע, והעיתונות קראה לו "הדילן הבריטי". אבל הוא רצה יותר מזה. עם המפיק מיקי מוסט הוא התחיל להקליט שירים עם נגני ג׳אז, כלי מיתר, צ׳מבלו וסיטאר. Sunshine Superman יצא בארצות הברית באוגוסט 1966. בבריטניה הוא לא יצא אז, בגלל סכסוך משפטי בין שתי חברות תקליטים, ורק בשנה אחר כך יצא שם אוסף שונה.''',
'''שיר הכותרת עלה לראש המצעד האמריקאי: בס מתגלגל, צ׳מבלו, גיטרה חשמלית וקול קליל ושמח, ושיר אהבה מלא בגיבורי קומיקס. Season of the Witch, לעומתו, אפל, איטי ומאיים, על תחושה שמשהו רע מתקרב. Legend of a Girl Child Linda הוא אגדה ארוכה ועדינה עם מיתרים, Three King Fishers ו־Guinevere מלווים בסיטאר, ו־Bert’s Blues הוא מחווה לגיטריסט ברט ג׳אנש (אלבום 56), שדונובן העריץ. The Fat Angel אפילו מזכיר את Jefferson Airplane בשמם, עוד לפני שהתפרסמו.''',
'''זה אחד האלבומים ששילבו פולק, ג׳אז ופסיכדליה בצורה רכה ושמחה, והוא מראה איך המוזיקה השתנתה בין 1965 ל־1966. דונובן השפיע על רבים, גם על הביטלס: כשנסעו להודו ב־1968 הוא היה איתם ולימד את ג׳ון לנון טכניקת נגינה באצבעות, שלנון השתמש בה בכמה משיריו. Season of the Witch הוקלט מאז שוב ושוב בידי מוזיקאים אחרים.''',
'''שמעו את Bert’s Blues, ואז חזרו לברט ג׳אנש באלבום 56, ותשמעו ממי דונובן למד. ואחרי The Fat Angel, עברו לאלבום 96 של הלהקה שהוא שר עליה.''',
], [
('Sunshine Superman', 'שיר חלומי ושמח שהפך ללהיט עולמי.'),
('Season of the Witch', 'שיר אפל ואיטי, עם גיטרה חשמלית מאיימת. אחד השירים המוקלטים ביותר של דונובן.'),
('Legend of a Girl Child Linda', 'אגדה עדינה וארוכה, עם מיתרים וחליל.'),
])

add(99, [
'''מרל הגארד נולד ב־1937 בקליפורניה, להורים שהגיעו מאוקלהומה בתקופת הבצורת הגדולה וגרו בקרון רכבת ישן שהפך לבית. אביו מת כשהיה בן תשע, והוא התדרדר לפשע: גניבות, בריחות ממוסדות לנוער, ובסוף שנתיים בכלא סן קוונטין, עד 1960. בכלא ראה את ג׳וני קאש מופיע, והחליט לנסות את המוזיקה ברצינות. הוא חזר לבייקרספילד, ניגן בבארים שבהם ניגן גם באק אוונס (אלבום 47), והקים את להקת The Strangers. I’m a Lonesome Fugitive יצא ב־1967, ושיר הנושא שלו היה הלהיט הראשון שלו שהגיע למקום הראשון במצעד הקאנטרי.''',
'''הצליל כאן הוא הצליל של בייקרספילד: גיטרות טלקסטר חדות, גיטרת פדל סטיל, ומקצב פשוט וחזק, והקול של הגארד, עמוק, חם ועייף, עם הרמוניות של אשתו דאז, בוני אוונס. את שיר הנושא, על אדם שבורח מהחוק ולא יכול לעצור, כתבו לו זוג כותבים שהשראתם הייתה סדרת טלוויזיה. אבל כשהגארד שר אותו, קשה שלא לחשוב על חייו. Life in Prison, שכתב יחד עם חבר, הוא על אסיר שמעדיף מוות על פני מאסר עולם, ו־Skid Row ו־Drink Up and Be Somebody מדברים על רחוב, על שתייה ועל כישלון, בלי להתנצל.''',
'''זה האלבום שביסס את מעמדו של הגארד כאחד היוצרים הגדולים של הקאנטרי. בשנים שאחרי הוא כתב שירים שהפכו לקלאסיקות, דיבר בשם מעמד הפועלים הלבן באמריקה, וב־1972 קיבל חנינה מלאה מהמושל רונלד רייגן. הוא השפיע על דורות של זמרי קאנטרי, ועל מוזיקאי רוק שהתאהבו בקאנטרי, מהבירדס ועד הגרייטפול דד.''',
'''השוו לבאק אוונס באלבום 47: אותה עיר, אותו צליל, אבל אוונס מחייך והגארד לא. ואחר כך חזרו לריי פרייס באלבום 34 ולריי צ׳רלס באלבום 31, כדי לשמוע כמה פנים יש לקאנטרי של שנות השישים.''',
], [
("I'm a Lonesome Fugitive", 'שיר על אדם שבורח מהחוק ולא יכול לעצור. הלהיט הראשון שלו במקום הראשון.'),
('Life in Prison', 'שיר קשה ועצוב על אסיר, שהגארד כתב מתוך מה שראה בכלא.'),
('Skid Row', 'שיר על החיים ברחוב, בלי הצגות.'),
])

add(100, [
'''ג׳ימי הנדריקס גדל בסיאטל, שירת בצבא, ובתחילת שנות השישים נדד בדרום ארצות הברית כגיטריסט מלווה של כוכבי סול ורוקנרול, ובהם ליטל ריצ׳רד (אלבום 14). ב־1966 הוא ניגן בשם "ג׳ימי ג׳יימס" במועדון Cafe Wha? בגריניץ׳ וילג׳, שם ראה אותו צ׳אס צ׳נדלר, הבסיסט של The Animals, שחיפש אמן להפיק. צ׳נדלר לקח אותו ללונדון, צירף אליו את הבסיסט נואל רדינג ואת המתופף מיץ׳ מיצ׳ל, ובתוך כמה חודשים הנדריקס כבר היה הגיטריסט שכל גיבורי הגיטרה של לונדון, כמו קלפטון ובק (אלבומים 73 ו־74), באו לראות.''',
'''הגיטרה של הנדריקס נשמעת כמו משהו שלא נשמע לפני כן: פידבק, עיוותים, צרחות ורעשים שהוא שולט בהם לגמרי, וכל זה צומח ישר מתוך הבלוז. Purple Haze נפתח בריף מתנגש ומעוות, Foxey Lady חושני ומאיים, ו־Manic Depression הוא ואלס רועם. אבל יש גם עדינות: The Wind Cries Mary הוא בלדה יפה ושקטה. ובסוף Third Stone From the Sun, מסע של גיטרה לחלל. הגרסה האמריקאית, שאותה תשמעו כאן, יצאה באוגוסט 1967 וכוללת שלושה סינגלים, ביניהם Hey Joe, השיר שבו הכול התחיל.''',
'''בבריטניה האלבום הגיע למקום השני, אחרי Sgt. Pepper (אלבום 78) בלבד. באמריקה הנדריקס התפרסם בן לילה אחרי ההופעה בפסטיבל מונטריי ביוני 1967, שבה הצית את הגיטרה על הבמה. זה אחד האלבומים החשובים בתולדות הרוק: הוא שינה את מה שגיטרה חשמלית יכולה לעשות. הנדריקס מת ב־1970, בגיל 27, אחרי שלושה אלבומי אולפן בלבד. זה גם האלבום שסוגר את מאה האלבומים הראשונים באתר: מסע שהתחיל בסינטרה שר בלילה, והגיע לגיטרה שצורחת.''',
'''שמעו את Hey Joe כאן ואז באלבום 63, של הבירדס. ואחר כך את Purple Haze ואת Sunshine of Your Love באלבום 88, מאותה שנה: שני ריפים ששינו את הרוק. ובסוף, חזרו לאלבום 1, ותחשבו כמה השתנה בשתים־עשרה שנה.''',
], [
('Purple Haze', 'הריף המעוות שקבע את הצליל של הרוק הכבד.'),
('The Wind Cries Mary', 'בלדה עדינה ויפהפייה, שמראה את הצד השקט של הנדריקס.'),
('Hey Joe', 'השיר הראשון שהקליט עם הלהקה, איטי ומאיים, עם גיטרה שעונה לקול.'),
])
